t.guides["forever/alliance/02-westfall"] = (function() return {
		["Back north past {area:918} to the mine: Kobold Diggers work inside."] = "向北經過{area:918}回到礦坑：狗頭人掘地工在礦坑內工作。",
		["Class trainer"] = "職業訓練師",
		["Defias Rogue Wizards camp on the shores of {area:86}; they drop the Red Linen Bandanas too. {object:56} lies in the murloc village on the north-east shore."] = "迪菲亞流浪巫師在{area:86}岸邊紮營；他們也會掉落紅色亞麻面罩。{object:56}在東北岸的魚人村裡。",
		["Fill the vial at the farm's well"] = "在農場的井裝滿小瓶",
		["Fill the vial at the well"] = "在井邊裝滿小瓶",
		["Follow the hills south to the tower."] = "沿著山丘向南走到塔。",
		["For your {area:16919} run: the {area:2257} from the {object:28027} to {zone:1455}."] = "為了你的{area:16919}之行：從{object:28027}搭乘{area:2257}前往{zone:1455}。",
		["For your {area:16919} run: {npc:265003} and {npc:264943} stand a few steps apart on the city's west side, west of the {object:171709}. The hall's door is a short walk further west."] = "為了你的{area:16919}之行：{npc:265003}和{npc:264943}站在城市西側，相隔幾步，位於{object:171709}西邊。大廳的門再往西走一小段就到。",
		["For {npc:266} in {area:69}, Redridge"] = "為了赤脊山{area:69}的{npc:266}",
		["Gnoll Paws"] = "豺狼人的爪子",
		["Harvest Watchers"] = "看守傀儡",
		["Harvest Watchers and Golems work the fields around {area:918}; they drop the isosprings, gyrostabilizers, {item:732} and sometimes a {item:255155}. {npc:573}, a level 20 rare, walks here: leave it alone."] = "看守傀儡和麥田傀儡在{area:918}周圍的田裡工作；牠們掉落等軸彈簧、陀螺穩定器、{item:732}，有時掉落{item:255155}。{npc:573}是20級稀有怪，在此遊走：別惹它。",
		["Head to {zone:1453}. It has no shaman trainer: take the {area:2257} from the {object:28027} to {zone:1455}, train with {npc:258098}, then ride the tram back for the boat."] = "前往{zone:1453}。那裡沒有薩滿祭司訓練師：從{object:28027}乘{area:2257}前往{zone:1455}，在{npc:258098}處學習技能，然後乘地鐵返回坐船。",
		["It lies by the river north-west of the logging camp."] = "它躺在伐木場西北方的河邊。",
		["Kobold Diggers"] = "狗頭人掘地工",
		["Level 12, 14 and 16 spells"] = "12、14和16級法術",
		["Longshore Murloc Gills"] = "長灘魚人鰓",
		["Murloc Coastrunners and Raiders line the north coast from above the mine east toward the {area:916}: work along the beach eastward. They flee at low health: pull one at a time."] = "灘行魚人和魚人襲擊者散布在北海岸，從礦坑上方向東一直到{area:916}：沿著海灘往東推進。牠們血量低時會逃跑：一次只拉一隻。",
		["North along the road from {area:87} to {zone:1453}: {npc:6122} waits in the cellar of the {object:2164}, in the {object:2101}. Use the {item:6928} at the summoning circle there and defeat the voidwalker it calls, then back south through {area:87} to {zone:1436}."] = "沿著道路從{area:87}向北前往{zone:1453}：{npc:6122}在{object:2101}的{object:2164}地下室等著。在那裡的召喚法陣使用{item:6928}，擊敗它召喚出的虛無行者，然後向南經過{area:87}返回{zone:1436}。",
		["Only if you looted a {item:1972} in Elwynn: right-click it"] = "只有在艾爾文森林拾取了{item:1972}時：右鍵點擊它",
		["Red Linen Bandanas"] = "紅色亞麻面罩",
		["Ride the tram back from {object:171524} to {zone:1453}'s {object:28027}."] = "從{object:171524}搭地鐵回到{zone:1453}的{object:28027}。",
		["Riverpaw Miners"] = "河爪礦工",
		["Riverpaw gnolls camp in the hills west of {area:86}; the {quest:91725} lie in their camps."] = "河爪豺狼人在{area:86}西邊的山丘紮營；{quest:91725}就在他們的營地裡。",
		["Shaman training"] = "薩滿訓練",
		["South along the road, past the fork. {npc:233} stands outside, {npc:235} in the house, {npc:253395} in the barn to the west. Young Goretusks and Fleshrippers roam the fields around the farm: start on livers and the stew's meat on the way."] = "沿路向南，過了岔路口。{npc:233}站在屋外，{npc:235}在屋裡，{npc:253395}在西邊的穀倉裡。幼年怖牙和撕皮鳥在農場周圍的田野遊蕩：順路收集肝臟和燉肉用的肉。",
		["South-west to the coast, west of {area:918}. Riverpaw Miners work the quarry."] = "向西南前往海岸，在{area:918}西邊。河爪礦工在採石場工作。",
		["The bridge"] = "橋",
		["The camp is north-east of the bridge. Bundles of Wood lie around the camp and in the woods north of it."] = "營地在橋的東北方。一捆木柴散落在營地周圍及其北邊的樹林裡。",
		["The gnoll camps"] = "豺狼人營地",
		["The gnoll hills"] = "豺狼人丘陵",
		["The {area:113}"] = "{area:113}",
		["The {area:88}"] = "{area:88}",
		["The {area:91}"] = "{area:91}",
		["Trainers: {object:2100} (Warriors, Rogues), the Cathedral (Paladins, Priests), the {object:2101} (Mages, Warlocks), the {object:28027} (Hunters), the Park (Druids)."] = "訓練師：{object:2100}（戰士、盜賊）、大教堂（聖騎士、牧師）、{object:2101}（法師、術士）、{object:28027}（獵人）、公園（德魯伊）。",
		["Tram to {zone:1453}"] = "搭地鐵前往{zone:1453}",
		["While you're in the city: Warriors and Rogues train in {object:2100}, Paladins and Priests in the Cathedral of Light across {object:2098}, Mages and Warlocks in the {object:2101}, Hunters in the {object:28027}."] = "趁你在城裡時：戰士和盜賊在{object:2100}訓練，聖騎士和牧師在{object:2098}對面的光明大教堂，法師和術士在{object:2101}，獵人在{object:28027}。",
		["{area:16919} is a dungeon for a group of five at about level 15 to 16, under {zone:1455}. Its door is on the west side of the city, a short walk west of {npc:264943}.\nInside: the Enraged Apparitions and Tormented Souls are {npc:264943}'s, the Dwarven Heirlooms Thom's, and {npc:261319}, the {object:147516} commander deep in the vaults, carries the head King Magni wants. A {npc:265002} inside gives An Ancient Grudge, for {npc:261306}, and takes it back there; a {item:281030} found inside starts a quest for King Magni."] = "{area:16919}是{zone:1455}地底下的五人地城，約15到16級。它的門在城市西側，從{npc:264943}往西走一小段就到。\n裡面：狂怒的幽影和受折磨的靈魂是{npc:264943}要的，矮人傳家寶是湯姆要的；而深處墓穴裡的{object:147516}指揮官{npc:261319}身上帶著國王麥格尼要的首級。裡面的一名{npc:265002}會給你「古老的宿怨」，要交給{npc:261306}，並在那裡交回；在裡面找到的{item:281030}會開啟一個給國王麥格尼的任務。",
		["{item:2449} for Gathering the Cure (6123) in {zone:1439}: {npc:1313}, Alchemy Supplies; herbalists pick it there instead"] = "{zone:1439}「收集解藥」（6123）所需的{item:2449}：向鍊金術供應商{npc:1313}購買；草藥學家可改在那裡採集",
		["{item:6529}, from {npc:5494}"] = "{item:6529}，向{npc:5494}購買",
		["{item:729}: Fleshrippers"] = "{item:729}：碎屍鳥",
		["{item:814}: keep five for {npc:392} at the {area:115}, later on the route"] = "{item:814}：留五個，路線後面要交給{area:115}的{npc:392}",
		["{npc:1416}: his package for {npc:1343} in {zone:1432}, later on the route"] = "{npc:1416}：他要交給{zone:1432}的{npc:1343}的包裹，路線稍後會經過",
		["{npc:234} and {npc:821} stand at the top of the stone tower. {npc:491} is in the tower, {npc:878} on the south side of the hill, next to the inn and {npc:523} the gryphon master."] = "{npc:234}和{npc:821}站在石塔頂端。{npc:491}在塔內，{npc:878}在山丘南側，旅店和獅鷲管理員{npc:523}旁邊。",
		["{npc:237}: Humans may have it already from {npc:963} in Elwynn"] = "{npc:237}：人類可能已經在艾爾文從{npc:963}那裡接過了",
		["{npc:253092}, beside {npc:878}"] = "{npc:253092}，在{npc:878}旁邊",
		["{npc:265003} and {npc:264943}"] = "{npc:265003}和{npc:264943}",
		["{npc:376} is in the Cathedral of Light."] = "{npc:376}在光明大教堂內。",
		["{npc:523}, on the south side of the hill"] = "{npc:523}，在山丘南側",
		["{npc:523}: the free flight he offers goes to {zone:1453}"] = "{npc:523}：他提供的免費飛行會飛往{zone:1453}",
		["{npc:5480} trains warriors in {object:2100}, near {npc:1323}'s shop; the tram from {zone:1455} arrives in the {object:28027}, north of it. {npc:6089} and {npc:6090} stand together by the {object:2152} there. {npc:6090} fights you for his mug. If {npc:5480} doesn't offer {quest:1638}, go straight to {npc:6089}: he gives {quest:1639} without it."] = "{npc:5480}在{object:2100}訓練戰士，就在{npc:1323}的商店附近；從{zone:1455}來的地鐵抵達它北邊的{object:28027}。{npc:6089}和{npc:6090}一起站在那裡的{object:2152}旁。{npc:6090}會為了他的杯子和你打一架。如果{npc:5480}沒有提供{quest:1638}，直接去找{npc:6089}：沒有該任務他也會給你{quest:1639}。",
		["{npc:5494} sells fishing supplies along the canal just west of the {object:2096}; {npc:267118} fishes at the harbor, on the way to the boat."] = "{npc:5494}在{object:2096}西側的運河邊出售釣魚用品；{npc:267118}在港口釣魚，就在前往船的路上。",
		["{npc:5497}, Wizard's Sanctum: {quest:1861}"] = "{npc:5497}，巫師聖所：{quest:1861}",
		["{npc:5676}: use the {item:6928} at the circle"] = "{npc:5676}：在法陣使用{item:6928}",
		["{npc:6122}'s {quest:1689} needs {item:6810}: {npc:881} (level 9) stands by the farmhouse of the {area:62}, just south of the river."] = "{npc:6122}的{quest:1689}需要{item:6810}：{npc:881}（9級）站在{area:62}的農舍旁，就在河的南邊。",
		["{quest:96393}: King Magni sits on the {object:171709}, east of the hall's door."] = "{quest:96393}：國王麥格尼坐在{object:171709}上，在大廳門的東邊。",
		["{quest:96393}: {npc:261319}, inside"] = "{quest:96393}：{npc:261319}，在裡面",
		["{quest:96394}, inside"] = "{quest:96394}，在裡面",
		["{quest:96403}: the heirlooms, inside"] = "{quest:96403}：傳家寶，在裡面",
} end)()
t.guides["forever/alliance/03-darkshore"] = (function() return {
		["After using the {item:12347}, kill Xabraxxis, then click his Demon Bag on the ground to collect the talisman. If Xabraxxis despawns before you get it, retake the quest for a new bowl."] = "使用{item:12347}後，擊殺薩巴克希斯，然後點擊他掉在地上的惡魔之袋取得護符。如果你拿到之前薩巴克希斯就消失了，重新接取任務以取得新的碗。",
		["At the {area:2362}"] = "在{area:2362}",
		["Back north-east into the mountains to the crystal."] = "向東北回到山中的水晶那裡。",
		["Bears and the Blackwood camp"] = "熊與黑木營地",
		["Blackwood Pathfinders and Windtalkers hold the camp south-east of {area:442}."] = "黑木探路者和黑木風語者佔據{area:442}東南方的營地。",
		["Blackwood furbolgs"] = "黑木熊怪",
		["Climb the eastern mountains east of {area:447}; the {object:175524} sits on a ledge."] = "爬上{area:447}東邊的山脈；{object:175524}在一處岩架上。",
		["Crawler Legs"] = "蟹腿",
		["East of Buzzbox 323, {npc:3661} hides at the foot of the tower among the Dark Strand Fanatics. Keep his letter for Delgren in {zone:1440}.\nCareful: Dark Strand Voidcallers (28-29) with their voidwalkers and {npc:3660} (31) stand in the tower itself: take the parchments from the Fanatics south of it and keep away from the tower."] = "傳聲盒323號東邊，{npc:3661}躲在塔腳下的暗灘狂熱者之間。留著他的信，交給{zone:1440}的淨化者德爾葛蘭。\n小心：暗灘喚魔師（28-29級）帶著虛空行者，和{npc:3660}（31級）一起待在塔裡：從塔南邊的狂熱者身上拿羊皮紙，遠離那座塔。",
		["Fill the tube at the moonwell in the village"] = "在村子的月井裝滿試管",
		["Follow the hills north to the {area:456} and up to the falls. Two more beached remains lie on the north shore: near the {area:443} and north of {quest:954}."] = "沿丘陵向北到{area:456}，再往上到瀑布。北岸還有兩具擱淺的骨骸：在{area:443}附近和{quest:954}北邊。",
		["Grell Earrings"] = "劣魔耳環",
		["Highborne Relics"] = "精靈貴族的聖物",
		["Kill Rabid Thistle Bears in the hills east of {area:442}, then walk up to the furbolg camp south-east of them: nothing to kill yet."] = "在{area:442}東邊的丘陵擊殺狂暴薊熊，然後走到牠們東南方的熊怪營地：目前還不用殺任何東西。",
		["Moonstalker Fangs"] = "月夜猛虎的牙齒",
		["Moonstalkers prowl the hills between {quest:954} and the tower. {quest:1002} stands on the hill west of the tower."] = "月夜猛虎在{quest:954}與高塔之間的丘陵徘徊。{quest:1002}站在高塔西邊的山丘上。",
		["Night Elves fly from {area:442} to {area:702}; Skyborne take the boat from the {area:442} dock and learn the Rut'theran flight path. Then take the portal up to {npc:4217} in the {area:1658}."] = "暗夜精靈從{area:442}飛往{area:702}；天裔精靈從{area:442}碼頭搭船，並學會魯瑟蘭村的飛行路線。接著搭傳送門上到{area:1658}找{npc:4217}。",
		["North along the hills. {npc:3650} waits in the ruins of {quest:954}; Wild Grells and Vile Sprites fill them, Deth'ryll Satyrs the eastern edge. {quest:1001} stands by the road west of the ruins; a {quest:4723} lies on the shore on the way to him."] = "沿丘陵向北。{npc:3650}在{quest:954}的廢墟中等著；野生劣魔和惡靈劣魔遍布廢墟，戴瑟雷薩特在東緣。{quest:1001}站在廢墟西邊的路旁；前往它的路上，岸邊有一個{quest:4723}。",
		["Plagued bears"] = "染病的熊",
		["Rabid Thistle Bears roam the hills just east of {area:442}. Use {quest:2139} on one and lead it back to him."] = "狂暴薊熊在{area:442}東邊不遠的丘陵遊蕩。對一隻使用{quest:2139}，把牠帶回給他。",
		["Read the {object:17188}"] = "閱讀{object:17188}",
		["Read the {object:17189}"] = "閱讀{object:17189}",
		["The WANTED poster outside the inn"] = "旅店外的通緝海報",
		["The bay wrecks"] = "海灣沉船",
		["The beach"] = "海灘",
		["The cave and the {npc:6788}"] = "洞穴與{npc:6788}",
		["The cave lies south of the falls: Scaber Stalks grow all through it, the {item:5270} at the very back. The {npc:6788} lairs in the hills south of the falls."] = "洞穴在瀑布南邊：粗柄蘑菇長滿整個洞穴，{item:5270}在最深處。{npc:6788}的巢穴在瀑布南邊的丘陵中。",
		["The flame burns in the south of {area:447}."] = "火焰在{area:447}南部燃燒。",
		["The half pendants lie in {zone:1439} and {zone:1436}: later on the route"] = "兩半墜飾在{zone:1439}和{zone:1436}：之後的路線",
		["The red crystal"] = "紅色水晶",
		["The skeletal turtle"] = "海龜骨骸",
		["The {object:16393}"] = "{object:16393}",
		["Tide Crawlers scuttle along the shore below the village; {quest:983} stands on the beach just south of the docks. Darkshore Threshers swim in the shallows. The {object:175207} lies on the shore just south of the village."] = "潮行蟹在村子下方的海岸爬行；{quest:983}站在碼頭南邊不遠的海灘上。黑海岸蛇頸龍在淺水中游動。{object:175207}在村子南邊不遠的岸上。",
		["Two wrecks lie on the sea floor in the bay north of {area:442}; each holds a lockbox. Reef Crawlers and Encrusted Tide Crawlers line this shore.\nCareful: The murlocs inside the wrecks are close together and fast. They often swim through the hull walls and holes, so you will usually pull extra murlocs."] = "兩艘沉船在{area:442}北邊的海灣海底；每艘都有一個鎖箱。暗礁蟹和硬殼潮行蟹散布在這片海岸。\n小心：沉船裡的魚人彼此靠得很近，而且速度很快。牠們常常穿過船殼的牆壁和破洞游過來，所以通常會多拉到幾隻魚人。",
		["{item:12238}: fish from the pier"] = "{item:12238}：在碼頭釣魚",
		["{item:12289}, on the beach west of the docks; underwater"] = "{item:12289}，在碼頭西邊的海灘上；在水下",
		["{item:12349}, at the waterfall"] = "{item:12349}，在瀑布",
		["{item:15845}: at the mouth of the cave by the falls"] = "{item:15845}：在瀑布旁的洞口",
		["{item:15877}, from a {object:177785} in the lake"] = "{item:15877}，從湖中的{object:177785}取得",
		["{item:5338}: Deth'ryll Satyrs"] = "{item:5338}：戴瑟雷薩特",
		["{item:5348}: Dark Strand Fanatics"] = "{item:5348}：暗灘狂熱者",
		["{npc:11802} stands upstairs in his building in {area:2361}: go up inside, the arrow cannot tell the floors apart. Shrine Baubles lie in the containers on the floor of {area:656}, below {area:2361}: take one to the {area:2362} in the north-west, use it there and speak to {npc:11799}. {quest:29} runs on a timer: no teleport or Hearthstone until {npc:11799} has it. Then fly back to {area:442} from {area:2361}."] = "{npc:11802}站在{area:2361}他建築的樓上：從裡面走上去，箭頭無法分辨樓層。神殿靈珠在{area:2361}下方{area:656}湖底的容器裡：拿一個到西北方的{area:2362}，在那裡使用並與{npc:11799}交談。{quest:29}有時間限制：在交給{npc:11799}之前，不要傳送或使用爐石。然後從{area:2361}飛回{area:442}。",
		["{npc:3639} stands at the north edge of the ruins. Cursed, Writhing and {npc:2178} haunt them; {npc:3667}'s ghost walks among them, {npc:270196} the owl circles east of them. The two tablets lie in the ruins; a {quest:4722} lies on the shore west of them."] = "{npc:3639}站在廢墟北緣。被詛咒的精靈貴族、悲苦的精靈貴族和{npc:2178}在廢墟中出沒；{npc:3667}的鬼魂在它們之間走動，貓頭鷹{npc:270196}在它們東邊盤旋。兩塊石板在廢墟中；一個{quest:4722}在廢墟西邊的岸上。",
		["{npc:3644}, on the pier"] = "{npc:3644}，在碼頭上",
		["{npc:3649}, north end of the village"] = "{npc:3649}，在村子北端",
		["{npc:3649}: for {npc:1646} in {zone:1453}"] = "{npc:3649}：給{zone:1453}的{npc:1646}",
		["{npc:3666}, upstairs in the inn"] = "{npc:3666}，在旅店樓上",
		["{quest:6122}: fill the sampler at {area:445}"] = "{quest:6122}：在{area:445}裝滿採樣器",
} end)()
t.guides["forever/alliance/03-darkshore-return"] = (function() return {
		["Back south"] = "往南回去",
		["Back to {npc:11802}"] = "返回{npc:11802}處",
		["Both half pendants in your bags (the {zone:1436} half from your last {zone:1436} visit, the {zone:1439} half from the north coast): stand by the {area:2362} on the north-west shore of the lake and use a half to join them, then take the pendant to {npc:11802} with the {spell:499} hand-in. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "兩半墜飾都在你的背包裡（{zone:1436}那一半來自你上次造訪{zone:1436}，{zone:1439}那一半來自北海岸）：站在湖西北岸的{area:2362}旁，使用其中一半把它們合起來，然後把墜飾連同{spell:499}的任務一起交給{npc:11802}。{npc:11802}站在他建築的樓上：從裡面走上去，箭頭無法分辨樓層。",
		["Escort her out of the glaive; Therysil takes the turn-in in {zone:1440}"] = "護送她離開月刃；瑟瑞希爾在{zone:1440}接受繳交",
		["Fine Moonstalker Pelts"] = "優質月夜猛虎毛皮",
		["Follow the coast north-east to the {area:443}. {quest:951} lie among the ruins; Stormscale Myrmidons, Sorceresses and Warriors hold them, and Stormscale Beastmistresses walk the shore. Careful: {npc:270294}, an elite naga (21), walks the ruins among them: pull the naga away from him, or fight him at full health."] = "沿海岸向東北前往{area:443}。{quest:951}散落在廢墟中；雷鱗侍從、雷鱗巫師和雷鱗戰士佔據著廢墟，雷鱗獸王在岸邊走動。小心：精英納迦{npc:270294}（21級）在牠們之間的廢墟中走動：把納迦從他身邊拉開，或滿血再跟他打。",
		["Follow the road north."] = "沿道路向北。",
		["For your {area:2797} run, on the {area:414} in the next guide: {npc:8997} stands a short walk west of {npc:3693}."] = "為了你的{area:2797}之行，在下一份指南的{area:414}上：{npc:8997}站在{npc:3693}西邊不遠處。",
		["Grizzled Scalps"] = "灰色頭皮",
		["Grizzled Thistle Bears roam the hills around the Grove; {quest:1003} stands west of it among them."] = "灰斑薊熊在林地周圍的丘陵遊蕩；{quest:1003}就在林地西邊的熊群之中。",
		["Moonstalker Sires prowl the woods around the glaive. The {object:12666} sits at the bottom of the crater; {npc:3584} stands on its north side. For {quest:948}'s quest, use the {item:5251} at the bottom of the crater: it makes the {object:10076}, and you hand the quest in to the bowl."] = "月夜雄虎在月刃周圍的樹林中徘徊。{object:12666}在坑底；{npc:3584}站在北側。進行{quest:948}的任務時，在坑底使用{item:5251}：它會變出{object:10076}，然後把任務交給這個碗。",
		["Night Elves fly from {area:442} to {area:702}; Skyborne take the boat from the {area:442} dock and learn the Rut'theran flight path there. Take the portal up to {npc:4217} in the {area:1658}."] = "夜精靈從{area:442}飛往{area:702}；天裔精靈從{area:442}碼頭搭船，並在那裡學習魯瑟蘭村的飛行路線。搭傳送門上到{area:1658}找{npc:4217}。",
		["On the way south to the Grove: the Lunar Fungal Blooms grow in the moonkin caves in the hills just east of {area:442}, a short way off the road; the moonkin there are irritable. {item:2449} needs {skill:182}: herbalists pick it all over {zone:1439}, anyone else brings it from {zone:1453} ({npc:1313}) or the Auction House."] = "往南前往林地的途中：月光蘑菇花生長在{area:442}東邊丘陵中的梟獸洞穴裡，離道路不遠；那裡的梟獸脾氣暴躁。{item:2449}需要{skill:182}：草藥學家在{zone:1439}各處都能採到，其他人從{zone:1453}（{npc:1313}）或拍賣場帶來。",
		["Only if a Disciple or Thug dropped {item:5352}: right-click it"] = "只有在暮光信徒或暮光暴徒掉落{item:5352}時：右鍵點擊它",
		["She gives you the {item:15826}"] = "她會給你{item:15826}",
		["The WANTED poster"] = "通緝海報",
		["The naga"] = "納迦",
		["The relics of the Barrow Dens"] = "怒風獸穴的遺物",
		["The {area:443}"] = "{area:443}",
		["The {object:10076}"] = "{object:10076}",
		["The {object:12666}"] = "{object:12666}",
		["Underwater"] = "在水下",
		["{item:15851} and {item:2449}"] = "{item:15851}與{item:2449}",
		["{item:15883}: the {object:177792} under the water off the north coast, west of the ruins"] = "{item:15883}：廢墟西邊、北海岸外水下的{object:177792}",
		["{item:15885}: join the halves at the {area:2362}"] = "{item:15885}：在{area:2362}把兩半合起來",
		["{item:279279}: Twilight Disciples and Thugs"] = "{item:279279}：暮光信徒和暮光暴徒",
		["{npc:10323}'s beach"] = "{npc:10323}的海灘",
		["{npc:11802}: the welcome from {npc:5504}"] = "{npc:11802}：{npc:5504}的歡迎",
		["{npc:11802}: {quest:5061}, for {npc:4217}"] = "{npc:11802}：{quest:5061}，交給{npc:4217}",
		["{npc:12298}: use the {item:15826} on them; they roam all of {zone:1439}"] = "{npc:12298}：對牠們使用{item:15826}；牠們遍布整個{zone:1439}",
		["{npc:3616}, at the Grove"] = "{npc:3616}，在古樹之林",
		["{npc:6667} hides on the little island off the ruins. The key pieces drop from Giant Foreststriders (top), Greymist murlocs (middle) and Raging Reef Crawlers (bottom)."] = "{npc:6667}躲在廢墟外的小島上。鑰匙碎片由兇猛的森林陸行鳥（上段）、灰霧魚人（中段）和狂暴暗礁蟹（下段）掉落。",
		["{quest:87760}: {npc:10219} offers it once all nine beached remains are handed in"] = "{quest:87760}：交齊全部九具擱淺的骨骸後，{npc:10219}會提供這個任務",
		["{quest:98394} (Night Elves) and the {npc:272054} (Skyborne) wait in southern {area:493}. The three relics lie in the {area:2363}, east of them. Reports from the first weeks say a relic gives no loot while another player is looting it: wait a moment and try again."] = "{quest:98394}（夜精靈）和{npc:272054}（天裔精靈）在{area:493}南部等著。三件聖物在它們東邊的{area:2363}。最初幾週的回報指出，當另一名玩家正在拾取時，聖物不會給你任何東西：稍等一下再試。",
} end)()
t.guides["forever/alliance/03-loch-modan"] = (function() return {
		["Back down to the east shore below the boars' hills: {npc:270693}, a crocolisk, patrols it among the Loch Crocolisks."] = "回到野豬丘陵下方的東岸：{npc:270693}，一隻鱷魚，在湖鱷之間巡邏。",
		["Back north to {npc:234}. For your {area:1581} run he then sends you after {npc:639}, and {npc:820}, beside him at the top of the tower, wants {quest:214}. Look for a group now if you have none yet."] = "向北回到{npc:234}處。為了你的{area:1581}之行，他接著會派你去找{npc:639}；而在塔頂他身旁的{npc:820}需要{quest:214}。如果你還沒有隊伍，現在就開始找。",
		["Boat to {area:150}"] = "搭船前往{area:150}",
		["Cathedral of Light"] = "光明大教堂",
		["Class trainer"] = "職業訓練師",
		["Druids on Trial of the Sea Lion: from the {area:113}, west to the shore and north along it. The {object:177790} lies on the sea floor off the coast (about 18,33); then back south along the coast to the lighthouse."] = "進行海獅試煉的德魯伊：從{area:113}向西到海岸，再沿海岸向北。{object:177790}在近海的海底（約18,33）；然後沿海岸向南回到燈塔。",
		["Elder Mountain Boars"] = "老山豬",
		["Fly to {area:1537}"] = "飛往{area:1537}",
		["Fly to {area:69}"] = "飛往{area:69}",
		["Fly to {zone:1453}"] = "飛往{zone:1453}",
		["For your {area:717} run, later in {zone:1453}: keep it until then."] = "為了你稍後在{zone:1453}的{area:717}之行：在那之前先留著它。",
		["Out of the mine and north up the road to {area:108}: {npc:234} stands at the top of the tower."] = "出了礦坑，沿道路向北前往{area:108}：{npc:234}站在塔頂。",
		["Through the South Gate tunnel and west along the road to {zone:1455}. Know the {zone:1455} flight path already? Fly from {area:144} instead: these two waypoints drop once you are in the city."] = "穿過南門隧道，沿著道路往西前往{zone:1455}。已經有{zone:1455}的飛行路線了嗎？那就改從{area:144}飛過去：一進城，這兩個路徑點就會自動消失。",
		["Train on the way to the harbour: {object:2100} (Warriors, Rogues), the Cathedral of Light (Paladins, Priests), the {object:2101} (Mages, Warlocks), the {object:28027} (Hunters)."] = "前往港口的路上順便訓練：{object:2100}（戰士、盜賊）、光明大教堂（聖騎士、牧師）、{object:2101}（法師、術士）、{object:28027}（獵人）。",
		["Tram to {zone:1453}"] = "搭地鐵前往{zone:1453}",
		["Use the {item:6866} on {npc:6172}"] = "對{npc:6172}使用{item:6866}",
		["You have the {area:1537} flight path: back north to {area:144}'s gryphons, quicker than walking through the tunnel and across {zone:1426}."] = "你已取得{area:1537}的飛行路線：往北回到{area:144}的獅鷲獸處，比穿過隧道再橫越{zone:1426}步行還快。",
		["{area:144} flight master"] = "{area:144}飛行管理員",
		["{area:1581} is a dungeon for a group of five, about levels 17 to 24, and a full run takes about an hour. Its door is the mine below {area:20}, where the traitor led you: the portal is at the far end of the mine's tunnels.\nInside: the Defias drop the {quest:214}, and {npc:639} waits on the ship at the end. Open the Unsent Letter he drops: its quest goes to {zone:1453}, where this guide hands it in."] = "{area:1581}是五人地城，約17到24級，完整打一次約需一小時。入口是{area:20}下方的礦坑，也就是叛徒帶你去的地方：傳送門在礦坑隧道的最深處。\n裡面：迪菲亞成員會掉落{quest:214}，{npc:639}在盡頭的船上等著。打開他掉落的未寄出的信：它的任務要交到{zone:1453}，本指南會在那裡繳交。",
		["{area:20} and the Defias hills"] = "{area:20}與迪菲亞丘陵",
		["{item:15882}: the {object:177790}"] = "{item:15882}：{object:177790}",
		["{item:254676}, from the crates around {area:20}"] = "{item:254676}，來自{area:20}周圍的箱子",
		["{item:280911}: Redridge Thrashers"] = "{item:280911}：赤脊山鞭笞者",
		["{item:6846}: Defias Rogue Wizards"] = "{item:6846}：迪菲亞流浪巫師",
		["{item:915}: the Defias"] = "{item:915}：迪菲亞成員",
		["{npc:1092} is inside the bunker at the tunnel post: go in by its door on the south-east side."] = "{npc:1092}在隧道哨站的碉堡裡：從東南側的門進去。",
		["{npc:1092}, inside"] = "{npc:1092}，在裡面",
		["{npc:1343}: {npc:1416}'s package"] = "{npc:1343}：{npc:1416}的包裹",
		["{npc:1573}, in the {object:32372}"] = "{npc:1573}，在{object:32372}",
		["{npc:1646}, the city architect, is on your way west to the harbour. His next errand, {quest:389}, leads into the {area:717}: it is for a {area:717} run at about 29, so leave it unless you chose that dungeon."] = "城市建築師{npc:1646}就在你向西前往港口的路上。他的下一個差事{quest:389}會帶你進入{area:717}：那是約29級{area:717}之行的任務，除非你選了那個地城，否則先別接。",
		["{npc:1646}: Thundris' letter from {area:442}"] = "{npc:1646}：來自{area:442}的桑迪斯的信",
		["{npc:1646}: for {npc:1719}, at the {area:717}'s gate"] = "{npc:1646}：交給{area:717}大門的{npc:1719}",
		["{npc:344}, in the town hall"] = "{npc:344}，在市政廳",
		["{npc:6171}: Redemption"] = "{npc:6171}：救贖",
		["{npc:820} keeps watch at the top of the {area:108} tower."] = "{npc:820}在{area:108}的塔頂站哨。",
		["{npc:820}, at the top of the tower"] = "{npc:820}，在塔頂",
} end)()
t.guides["forever/alliance/04-redridge-mountains"] = (function() return {
		["Back to {area:69}"] = "返回{area:69}",
		["Cross the long bridge north into town: {npc:381} on the docks, {npc:900} in the town hall, {npc:342} in her garden at the west end. {npc:382} and {npc:341} stand at the north end of the bridge: the Blackrock camps' quests and {quest:98386} are worked on this visit's loop east of the lake."] = "向北走過長橋進入城鎮：{npc:381}在碼頭，{npc:900}在市政廳，{npc:342}在西端她的花園裡。{npc:382}和{npc:341}站在橋的北端：黑石營地的任務和{quest:98386}要在這次湖東邊的環線中完成。",
		["Fly to {area:108} and head north-west to the coast: the {object:177790} lies on the sea floor off the shore. Then head east along the road through Elwynn."] = "飛往{area:108}，向西北前往海岸：{object:177790}在岸外的海底。然後沿著道路向東穿過艾爾文森林。",
		["Follow the road along the south shore of {area:68} to the gryphon master. {npc:903} stands by the road next to her."] = "沿著{area:68}南岸的道路前往獅鷲管理員處。{npc:903}站在她旁邊的路旁。",
		["Follow the road north-west past the cemetery to {npc:311}'s camp on the far west edge of the forest. {npc:893} stands beside {npc:311}."] = "沿著道路向西北經過墓地，前往森林最西緣的{npc:311}營地。{npc:893}站在{npc:311}旁邊。",
		["Follow the road south from {area:1002} into {zone:1431}; {area:42} lies on the east side of the forest."] = "沿著道路從{area:1002}向南進入{zone:1431}；{area:42}位於森林東側。",
		["For your {area:717} run, in {zone:1453} at about 29: {npc:270} is in the town hall. Keep it until then."] = "為了你約29級時在{zone:1453}的{area:717}之行：{npc:270}在市政廳。在那之前先留著它。",
		["Greater Tarantulas crawl on the slopes around {quest:98386}, north-east of the lake; their Tarantula Eggs lie on the ground among them: click six."] = "巨型狼蛛在湖東北方{quest:98386}周圍的山坡上爬行；牠們的狼蛛卵散落在牠們之間的地上：點擊六顆。",
		["Keeshan hides at the very north end of the valley, by the {zone:1428} border. Escort him down to {area:69}; Blackrock orcs ambush you on the way."] = "基沙恩躲在山谷最北端、{zone:1428}邊界旁。護送他下到{area:69}；途中黑石獸人會伏擊你。",
		["Level 18 and 20 spells"] = "18級和20級法術",
		["Murloc Flesheaters and Tidecallers line the south shore of {area:68}, just east of the gryphons and the bridge. Any of them can carry a fin."] = "魚人食腐者和魚人招潮者分布在{area:68}的南岸，就在獅鷲和橋的東邊。他們每一個都可能帶著魚鰭。",
		["The Wanted poster by the inn"] = "旅店旁的通緝告示",
		["The cemetery lies north of the village. Skeletal Horrors and Skeletal Fiends walk its southern half. {npc:522}, an elite, wanders the graves: keep away from him."] = "墓地在村莊北邊。恐怖骸骨和骸骨魔在墓地南半部走動。精英{npc:522}在墓地之間遊蕩：遠離他。",
		["The hermit's shack stands in the woods north-east of the {area:492}."] = "隱士的小屋在{area:492}東北方的樹林裡。",
		["The mound of loose dirt lies south of the farmhouse, by the old stump."] = "鬆土堆在農舍南邊的老樹樁旁。",
		["The road east through Elwynn crosses into Redridge at {area:1002}, where the roads to Redridge, {zone:1431} and Elwynn meet: south to {zone:1431} first."] = "向東穿過艾爾文森林的道路在{area:1002}進入赤脊山，通往赤脊山、{zone:1431}和艾爾文森林的道路在那裡交會：先往南前往{zone:1431}。",
		["The {area:91}"] = "{area:91}",
		["Use the {item:6866} on {npc:6172}"] = "對{npc:6172}使用{item:6866}",
		["{item:1075}: any Shadowhide gnoll"] = "{item:1075}：任何暗皮豺狼人",
		["{item:15882}: the {object:177790}"] = "{item:15882}：{object:177790}",
		["{item:281046}, from the {object:673515}"] = "{item:281046}，來自{object:673515}",
		["{item:6846}: Defias Rogue Wizards"] = "{item:6846}：迪菲亞流浪巫師",
		["{npc:2409}, at the north end of town"] = "{npc:2409}，在城鎮北端",
		["{npc:264}, in the town hall"] = "{npc:264}，在市政廳裡",
		["{npc:267}, in the town hall"] = "{npc:267}，在市政廳裡",
		["{npc:268}, in the house behind the town hall"] = "{npc:268}，在市政廳後面的房子裡",
		["{npc:276} is in her house at the east end of town. {quest:174} needs a {item:4371}, so this step shows only while you carry one: without a tube the guide passes {npc:276} and her chain."] = "{npc:276}在城鎮東端她的房子裡。{quest:174}需要一個{item:4371}，所以只有你身上帶著一個時才會顯示這個步驟：沒有銅管的話，指南會略過{npc:276}和她的任務鏈。",
		["{npc:341}, beside him"] = "{npc:341}，在他旁邊",
		["{npc:344}, in the town hall"] = "{npc:344}，在市政廳",
		["{npc:345} (level 24) roots around the pen just west of {area:69}, beside {npc:342}'s garden. Pull him away from the other boars and fight at full health."] = "{npc:345}（24級）在{area:69}西邊不遠處的豬圈裡拱土，就在{npc:342}的花園旁。把牠從其他野豬旁拉開，滿血再戰。",
		["{npc:382}, at the north end of the bridge"] = "{npc:382}，在橋的北端",
		["{npc:663}, by the town hall"] = "{npc:663}，在市政廳旁",
		["{npc:6790}, Scarlet Raven Tavern"] = "{npc:6790}，在旅店",
		["{npc:888} stands south of the road, at the {area:245}."] = "{npc:888}站在道路南邊的{area:245}。",
		["{npc:903}, by the gryphons south of the bridge"] = "{npc:903}，在橋南邊的獅鷲旁",
} end)()
t.guides["forever/alliance/05-duskwood"] = (function() return {
		["/lay down beside {npc:7207}"] = "在{npc:7207}旁邊/lay down",
		["Back to {area:42}"] = "回到{area:42}",
		["Cathedral of Light"] = "光明大教堂",
		["Class trainer"] = "職業訓練師",
		["Every ghoul of the {area:492}'s northern half can drop a rib: Flesh Eaters, Bone Chewers, Plague Spreaders and Brain Eaters.\nCareful: A {npc:948} casts {spell:3428} as it dies, which brings extra adds."] = "{area:492}北半部的每個食屍鬼都可能掉落肋骨：食腐者、噬骨者、瘟疫食屍鬼和食腦者。\n小心：{npc:948}死亡時會施放{spell:3428}，引來額外的怪。",
		["Fly to {area:42}"] = "飛往{area:42}",
		["Ghoul Ribs"] = "食屍鬼的肋骨",
		["Head north through Elwynn to {zone:1453}; Mathias Shaw is at SI:7 in {object:2100}."] = "向北穿過艾爾文森林前往{zone:1453}；馬迪亞斯·肖爾在{object:2100}的軍情七處。",
		["Head south through the cemetery towards {area:94}. Skeletal Fiends and Skeletal Horrors walk its southern half. {npc:522}, an elite, wanders the graves: keep away from him."] = "向南穿過墓地前往{area:94}。骸骨魔和恐怖骸骨在墓地南半部走動。精英{npc:522}在墓地之間遊蕩：遠離他。",
		["Head west along the road once more."] = "再次沿著道路向西走。",
		["Head west along the road out of {area:94} into {zone:1436}. {npc:7024} watches {npc:7053}'s tower from the hills just inside the border. The {npc:7051} (level 23) guarding the tower carries its key; Klaven's journal is in the chest at the top."] = "沿著道路向西離開{area:94}進入{zone:1436}。{npc:7024}在邊界內側的山丘上監視{npc:7053}的塔。守衛塔的{npc:7051}（等級23）身上帶著塔的鑰匙；克拉文的日記在塔頂的箱子裡。",
		["Head west to the hermit once more."] = "再次向西去找隱士。",
		["Her house stands on the hill south-east of {area:42}, above the {area:121}."] = "她的房子在{area:42}東南方的山丘上，位於{area:121}上方。",
		["Level 22 and 24 spells"] = "22和24級法術",
		["Next: training, then the flight from {zone:1453} to {area:150} for the {zone:1437}."] = "接下來：訓練，然後從{zone:1453}飛往{area:150}，前往{zone:1437}。",
		["Rot Blossoms"] = "腐敗之花",
		["Shaman training"] = "薩滿訓練",
		["Skeletal Horrors walk the hillside between {area:42} and the {area:121}, south-east of town; they drop the Rot Blossoms."] = "恐怖骸骨在城鎮東南方、{area:42}與{area:121}之間的山坡上走動；牠們會掉落腐敗之花。",
		["{item:3372}: {npc:1313}, Alchemy Supplies"] = "{item:3372}：鍊金術供應商{npc:1313}",
		["{item:7908}, in the chest"] = "{item:7908}，在箱子裡",
		["{npc:267}, in the town hall"] = "{npc:267}，在市政廳裡",
		["{npc:272} is in the Scarlet Raven Tavern too."] = "{npc:272}也在血鴉旅店裡。",
		["{npc:273}, in the tavern"] = "{npc:273}，在旅店裡",
		["{npc:288} hides in the house at the west end of {area:94}."] = "{npc:288}躲在{area:94}西端的房子裡。",
		["{npc:332}: Poisons, and {item:18160}"] = "{npc:332}：毒藥，以及{item:18160}",
		["{npc:6171}: Redemption"] = "{npc:6171}：救贖",
		["{quest:2607}: {npc:7207}, in the cellar of the Barracks"] = "{quest:2607}：{npc:7207}，在兵營地下室",
		["{quest:337}: a rare drop from {zone:1431}'s mobs"] = "{quest:337}：{zone:1431}怪物的稀有掉落",
		["{zone:1453} has no shaman trainer: take the {area:2257} from the {object:28027} to {zone:1455}, train with {npc:258098}, then ride the tram back."] = "{zone:1453}沒有薩滿訓練師：從{object:28027}搭乘{area:2257}前往{zone:1455}，向{npc:258098}學習，然後搭地鐵回來。",
} end)()
t.guides["forever/alliance/06-ashenvale"] = (function() return {
		["Back north from the glaive (Druids: south along the road from {area:442}) to the {area:448}, where {npc:11218} sleeps beside Arbal. Take his quest: it gives you the {item:13536}. Use the horn to wake him and lead him south along the road to his bag at the southern edge of {zone:1439}; blow it again whenever he falls asleep. Then go on to {npc:11219} at {area:413}.\nCareful: Scripted ambushes of three mobs each attack along the road."] = "從戰刃處往北返回（德魯伊：從{area:442}沿道路向南）到{area:448}，{npc:11218}睡在阿爾巴旁邊。接下他的任務：會給你{item:13536}。使用號角叫醒他，沿道路向南帶他到{zone:1439}南緣他的袋子處；每當他睡著就再吹一次號角。然後繼續前往{area:413}找{npc:11219}。\n注意：沿路會有固定劇情的伏擊，每次三隻怪。",
		["Back north through the {area:1276}: west of {area:421}, the stardust bushes grow among the ruins."] = "向北穿過{area:1276}回去：在{area:421}西邊，星塵灌木生長在廢墟之間。",
		["Below ground"] = "地下",
		["Boat to {area:150}"] = "搭船前往{area:150}",
		["Cave Stalkers and Leech Stalkers fill {area:1021}, the cave south-east of the excavation site. Careful: Highland Lurkers and Horrors, level 28 elites, walk the same cave among them: pull the stalkers one at a time and keep clear of the elites."] = "洞穴捕獵者和吸血捕獵者遍布挖掘場東南方的洞穴{area:1021}。小心：28級精英高地潛伏者和高地恐魔也在同一個洞穴裡走動：一次拉一隻捕獵者，遠離精英。",
		["Fly to {area:1537}"] = "飛往{area:1537}",
		["Fly to {area:442}"] = "飛往{area:442}",
		["Follow the coast north out of Menethil. Bluegill Murlocs fill the marsh; {npc:1259} walks with a pack in the middle of it."] = "沿海岸向北離開米奈希爾港。藍腮魚人遍布沼澤；{npc:1259}帶著一群魚人在中間走動。",
		["Follow the coast north to the {area:414}. {npc:3846} camps on the beach; Wrathtail nagas fill the shore."] = "沿海岸向北前往{area:414}。{npc:3846}在海灘上紮營；怒尾納迦遍布海岸。",
		["Follow the road east to the {area:419}; {npc:3916} stands by the moonwell."] = "沿道路向東前往{area:419}；{npc:3916}站在月井旁。",
		["From the marsh head east across the {zone:1437}. Young Wetlands Crocolisks lurk in the pools north of the excavation site."] = "從沼澤向東穿過{zone:1437}。小濕地鱷魚潛伏在挖掘場北邊的水池中。",
		["Head south past {area:421} into the {area:1276} tunnel; it comes out in Stonetalon's {area:461}, north of the {area:2160}."] = "向南經過{area:421}進入{area:1276}隧道；出口在石爪山脈的{area:461}，位於{area:2160}北邊。",
		["Head west to the shore of {area:441}. Teronis lies among the Saltspittle murlocs; any murloc can drop the {item:5463}."] = "向西前往{area:441}的岸邊。泰洛尼斯的屍體躺在鹽沫魚人之間；任何魚人都可能掉落{item:5463}。",
		["Kill the elementals for 5 Intact Elemental Bracers, then use the {item:5456}"] = "擊殺元素取得5個完整的元素護腕，然後使用{item:5456}",
		["Mosshide Gnolls and Mongrels hold the hills south-east of the {area:1025}."] = "蘚皮豺狼人和混血蘚皮豺狼人佔據{area:1025}東南方的丘陵。",
		["North of Maestra's Post, plant bundles lie around the ruins of {area:411}. Dark Strand cultists hold the ruins just south of them: any of them can drop the {item:5366}."] = "在邁斯特拉崗哨北邊，植物束散落在{area:411}廢墟周圍。暗灘祭司佔據其南邊不遠的廢墟：任何一個都可能掉落{item:5366}。",
		["Only with {item:5352} from {zone:1439}: {npc:2786}, the {object:32383}"] = "只有在持有{zone:1439}的{item:5352}時：{npc:2786}，{object:32383}",
		["South of the murlocs, {npc:3585} waits at the {area:416}."] = "在魚人南邊，{npc:3585}在{area:416}等著。",
		["Still carrying {quest:92748} (you used your Hearthstone at the end of {zone:1432})? The tram comes in at the {object:28027}, where {npc:11026} stands."] = "還帶著{quest:92748}嗎（你在{zone:1432}結束時用了爐石）？地鐵抵達{object:28027}，{npc:11026}就站在那裡。",
		["The Foulweald"] = "汙林熊怪",
		["The Foulweald furbolgs live in the woods south of the road, south-east of {area:415}. The Den Watcher and the Ursas guard the den."] = "汙林熊怪住在道路南邊、{area:415}東南方的樹林中。汙林衛兵和汙林巨熊怪守護巢穴。",
		["The Mosshide gnolls"] = "蘚皮豺狼人",
		["The Venture Co. clear the forest of {area:461}. Loggers and Deforesters work all over it; the Operators run the shredders and one carries the blueprints."] = "風險投資公司正在砍伐{area:461}的森林。樵夫和砍樹工到處工作；操作員駕駛伐木機，其中一人帶著藍圖。",
		["The excavation site sits on the hill south of the road."] = "挖掘場在道路南邊的山丘上。",
		["The raptor hills"] = "迅猛龍丘陵",
		["The tears glow on the small isle east of {area:415}."] = "淚珠在{area:415}東邊的小島上發光。",
		["Timber and iron piles lie around the keep and along the harbor's walls. Careful: {npc:270589}, a level 31 elite, roams the {zone:1437}' shores and roads: if it comes by, give it room."] = "木材和鐵堆放在城堡周圍和港口的城牆邊。小心：31級精英{npc:270589}在{zone:1437}的海岸和道路上遊蕩：如果牠經過，就讓開。",
		["To {area:150}"] = "前往{area:150}",
		["Tram to {zone:1453}"] = "搭地鐵前往{zone:1453}",
		["Underwater"] = "在水下",
		["Young crocolisks"] = "小鱷魚",
		["{area:2797} is a dungeon for a group of five, about levels 22 to 30, and a full run takes about an hour. The way in is the sunken ruins at the north end of the strand: go down the stairs into the pit, swim through the tunnels under the wall, past the blue crystals, to the portal.\nInside: the naga and the satyrs drop the Corrupted Brain Stems for Gershala. {npc:4787}, by a campfire in an underwater side room off Ghamoo-ra's room, has a quest for {zone:1457}, which this route leaves to the Dungeons page."] = "{area:2797}是五人地城，約22到30級，完整打一次約需一小時。入口是海灘北端的沉沒廢墟：走下樓梯進入深坑，游過牆下的隧道，經過藍色水晶，到達傳送門。\n裡面：納迦和薩特會掉落給葛沙拉的腐化的腦幹。{npc:4787}在迦莫拉房間旁一間水下側室的營火邊，有一個前往{zone:1457}的任務，本路線把它留給地城頁面。",
		["{item:5424}, in the ruins on the shore"] = "{item:5424}，在海岸上的廢墟裡",
		["{npc:1021}; careful: {npc:270589}, a level 31 elite, roams these hills"] = "{npc:1021}；小心：{npc:270589}，31級精英，在這些丘陵間遊蕩",
		["{npc:1239}, in the inn"] = "{npc:1239}，在旅店裡",
		["{npc:1242}, on the pier north of the inn"] = "{npc:1242}，在旅店北邊的碼頭上",
		["{npc:1646}: Thundris' letter from {area:442}"] = "{npc:1646}：來自{area:442}的桑迪斯的信",
		["{npc:2086}, in the keep"] = "{npc:2086}，在城堡裡",
		["{npc:2093} camps by the road; {npc:1244} stands farther east, by the river."] = "{npc:2093}在路邊紮營；{npc:1244}站在更東邊的河邊。",
		["{npc:2096}, by the north gate"] = "{npc:2096}，在北門旁",
		["{npc:3691}, in the inn"] = "{npc:3691}，在旅店裡",
		["{npc:3693} stands by the flight master, at the east end of the main street; then back west to the dock."] = "{npc:3693}站在飛行管理員旁，在主街東端；然後向西回到碼頭。",
		["{npc:3693}: Volcor's escort from the end of {zone:1439}"] = "{npc:3693}：{zone:1439}結尾的沃爾科護送任務",
		["{npc:376}: {npc:11401} in {zone:1457} takes it, later"] = "{npc:376}：由{zone:1457}的{npc:11401}接收，稍後",
		["{npc:376}: {npc:11406} in {zone:1455} takes it, later"] = "{npc:376}：由{zone:1455}的{npc:11406}接收，稍後",
		["{npc:376}: {npc:258785} in {zone:1455} takes it, later"] = "{npc:376}：由{zone:1455}的{npc:258785}接收，稍後",
		["{npc:3885} stands at the {area:420} on the east shore of {area:421}. Befouled Water Elementals wade in the lake. Careful: {npc:12759}, a level 27 water elemental, walks the lake among them; she drops the bracers too, but the small elementals are the safer kills at this level."] = "{npc:3885}站在{area:421}東岸的{area:420}。污濁的水元素在湖中涉水。小心：27級水元素{npc:12759}在牠們之間的湖中走動；她也會掉落護腕，但以你現在的等級，打小元素比較安全。",
		["{npc:3987} (25) leads the Thistlefur furbolgs at the camp north of {area:415}. Clear his guards first, one at a time.\nCareful: The furbolgs near him usually join in when he is pulled. Killing the ones along his path first lets you fight him alone."] = "{npc:3987}（25級）率領{area:415}北邊營地的薊皮熊怪。先一個一個清掉他的守衛。\n小心：拉他的時候，附近的熊怪通常會一起加入。先殺掉他巡邏路線上的熊怪，就能單獨和他打。",
		["{npc:4201}, inside"] = "{npc:4201}，在裡面",
		["{npc:6122}: {npc:6244} in the {zone:1413} takes it, later"] = "{npc:6122}：由{zone:1413}的{npc:6244}接收，稍後",
		["{object:2164} is in the {object:2101}. Warlocks: {npc:6122} is in its cellar."] = "{object:2164}在{object:2101}。術士：{npc:6122}在它的地下室。",
		["{quest:1009} walks the northern tip of the {area:414} with Wrathtail guards."] = "{quest:1009}帶著怒尾守衛在{area:414}的北端走動。",
		["{quest:1010}, from the plant bundles"] = "{quest:1010}，從植物束取得",
		["{quest:1275}: Corrupted Brain Stems"] = "{quest:1275}：腐化的腦幹",
		["{quest:1483}, inside"] = "{quest:1483}，在裡面",
} end)()
t.guides["forever/alliance/06-wetlands"] = (function() return {
		["Back to the Cathedral of Light: {npc:928} stands inside."] = "回到光明大教堂：{npc:928}站在裡面。",
		["Below ground"] = "地下",
		["Boat to {area:150}"] = "搭船前往{area:150}",
		["Cathedral of Light"] = "光明大教堂",
		["Dartol's Rod"] = "達圖爾的變形魔棒",
		["Fly to {area:150}"] = "飛往{area:150}",
		["Fly to {area:1537}"] = "飛往{area:1537}",
		["Fly to {area:442}"] = "飛往{area:442}",
		["Follow the road east to the satyr camps of {area:429}; {npc:3920} hides at their edge."] = "沿著道路向東前往{area:429}的薩特營地；{npc:3920}躲在營地邊緣。",
		["Follow the road east to the {area:419}; {npc:3916} stands by the moonwell."] = "沿道路向東前往{area:419}；{npc:3916}站在月井旁。",
		["For Bolvar Fordragon in {object:2117}: keep it"] = "給{object:2117}的伯瓦爾·弗塔根公爵：先留著",
		["For your {area:17732} run, later in this guide: {npc:2094}, by the docks, wants hides from the raptors inside."] = "為了你稍後在本指南中的{area:17732}之行：碼頭邊的{npc:2094}想要裡面迅猛龍的皮。",
		["For your {area:17732} run, on the way back west: {npc:1244} wants the root core of a {npc:260808} inside."] = "為了你的{area:17732}之行，在向西返回的路上：{npc:1244}想要裡面一隻{npc:260808}的根核。",
		["For your {area:717} run: {npc:1719} keeps the {area:717}'s gate, south of the {object:2098}."] = "為了你的{area:717}之行：{npc:1719}看守{area:717}的大門，在{object:2098}南邊。",
		["For {npc:2228} in {area:271}: keep it"] = "給{area:271}的{npc:2228}：先留著",
		["For {npc:3649} in {area:442}, on this guide's boat trip: keep it"] = "給{area:442}的{npc:3649}，在本指南的搭船行程中交付：先留著",
		["Insane druids"] = "發狂的德魯伊",
		["Level 28"] = "28級",
		["Melyria and {npc:3901}"] = "梅麗瑞亞與{npc:3901}",
		["Next: fly to {area:42}."] = "下一步：飛往{area:42}。",
		["North from the lake to the satyr camp of {area:430}, just west of {area:2358}: the {object:19901} stands in it, and {object:673431} lies beside it with the {item:281014}.\nCareful: The Felmusk Rogues in {area:428} often go stealthed, and {area:430} has satyr casters."] = "從湖泊向北前往{area:2358}西邊的{area:430}薩特營地：{object:19901}就在營地裡，{object:673431}放在它旁邊，裡面有{item:281014}。\n小心：{area:428}的魔麝盜賊經常處於潛行狀態，而{area:430}有薩特施法者。",
		["Only if you looted {quest:337} in {zone:1431}"] = "只有在{zone:1431}拾取了{quest:337}時",
		["Raptor valley"] = "迅猛龍山谷",
		["Still below level 28? That happens when you start this guide here without the {zone:1437} and {zone:1440} quests of the guides before it: top up on the Bluegill Raiders along the coast just south of Menethil before the boat, so {zone:1440}'s level 28-32 quests aren't too hard."] = "還不到28級？如果你直接從這份指南開始，沒做前面指南的{zone:1437}和{zone:1440}任務，就會這樣：上船前先在米奈希爾港南邊海岸的藍腮突襲者身上練一下，這樣{zone:1440}的28-32級任務就不會太難。",
		["Take the tunnel into the {area:419}; the tome lies in the ruins at its west end. Careful: Terrowulf Fleshrippers and Shadow Weavers (28-30) stand in tight packs around the tome, and the {npc:3792}, a level 32 rare, walks the vale. Pull the wolves one at a time from the tunnel and let the Packlord pass first."] = "穿過隧道進入{area:419}；書在山谷西端的廢墟裡。小心：恐狼撕裂者和恐狼影法師（28-30級）在書周圍緊密成群，32級的稀有怪{npc:3792}在山谷中走動。從隧道一次拉一隻狼，並先讓族長走過去。",
		["Take the {area:2257} from {object:171524} to {zone:1453}'s {object:28027}, then walk to the {object:2098}."] = "從{object:171524}搭乘{area:2257}前往{zone:1453}的{object:28027}，然後走到{object:2098}。",
		["The Bluegill hovels"] = "藍腮魚人小屋",
		["The Crazed and Withered Ancients north of the moonwell carry the {item:5475}; the worn chest it opens stands among them."] = "月井北邊的瘋狂的古樹和乾枯的古樹帶著{item:5475}；它能打開的破舊箱子就在它們之間。",
		["The captain walks the deck of the wrecked ship; his strongbox sits in the hold."] = "船長在沉船的甲板上走動；他的保險箱在貨艙裡。",
		["The relics lie in the dig itself. {npc:1353}, a big Razormaw, prowls the raptor valley just west of it.\nGoaz Warders (elite, 32) stand among the relics and the {object:331}: pull them away one at a time, or work around them."] = "文物就在挖掘場裡。{npc:1353}是一隻大型刺喉龍，在挖掘場西邊的迅猛龍山谷徘徊。\n戈阿茲守衛者（精英，32級）站在文物和{object:331}之間：一次拉一隻出來，或繞開牠們。",
		["The second {object:19901} lies in the valley of {area:428}, on the way west."] = "第二個{object:19901}在{area:428}的山谷裡，在往西的路上。",
		["The shrine sits on the hill just south-east of the moonwell; follow the winding path up."] = "神龕在月井東南方的山丘上；沿著蜿蜒的小路往上走。",
		["The {item:270865} from your {area:17732} run: {npc:1077} is below ground in his dig, west of the entrance on the way back west."] = "你{area:17732}之行取得的{item:270865}：{npc:1077}在他挖掘場的地下，位於入口西邊，就在向西返回的路上。",
		["Tram to {zone:1453}"] = "搭地鐵前往{zone:1453}",
		["Your Excavation Site hides: {npc:2094}, by the docks."] = "你的挖掘場獸皮：{npc:2094}，在碼頭邊。",
		["Your {area:2797} brain stems: {npc:8997} stands a short walk west of {npc:3693}."] = "你{area:2797}的腦幹：{npc:8997}站在{npc:3693}西邊不遠處。",
		["grind on {npc:1418}"] = "刷{npc:1418}",
		["{area:17732} is a dungeon for a group of five at about level 28 to 31. Its entrance lies just south of the road west, east of Whelgar's dig.\nInside: the Thicket raptors and Shadetooth drop the hides for Halloran, a {npc:260808} the root core for {npc:1244}. Saltspine, Shadetooth and the {npc:260326} are the bosses; the {npc:260326} drops a {item:270865}, which starts a quest for {npc:1077}."] = "{area:17732}是五人地城，約28到31級。入口就在往西道路的南邊，維爾加挖掘場的東邊。\n裡面：灌木迅猛龍和影牙會掉落給哈洛蘭的獸皮，{npc:260808}會掉落給{npc:1244}的根核。鹽脊、影牙和{npc:260326}是首領；{npc:260326}會掉落{item:270865}，可開啟一個給{npc:1077}的任務。",
		["{area:2358}, the Night Elf outpost at the eastern end of the road: {npc:3848} stands there, {npc:221269} a few steps east of her."] = "{area:2358}是道路東端的夜精靈前哨：{npc:3848}站在那裡，{npc:221269}在她東邊幾步之處。",
		["{area:717} is a dungeon for a group of five, about levels 23 to 29, and a run takes under an hour. Its gate is {npc:1719}'s, south of the {object:2098}.\nInside: the Defias prisoners, convicts and insurgents for Thelwater, {npc:1663}'s hand for Millstipe, and {quest:389} at the far end."] = "{area:717}是五人地城，約23到29級，打一次不到一小時。它的大門由{npc:1719}看守，在{object:2098}南邊。\n裡面：給塞爾沃特的迪菲亞囚犯、罪犯和叛亂者，給米爾斯迪普的{npc:1663}的手，以及最深處的{quest:389}。",
		["{item:15885}: join the halves at the {area:2362}"] = "{item:15885}：在{area:2362}合成兩半",
		["{item:2594}, from {npc:1464}"] = "{item:2594}，向{npc:1464}購買",
		["{item:2661}: the {object:331}"] = "{item:2661}：{object:331}",
		["{item:279915} lies on the shore just south of {area:150}, a short walk past the town's south end. Then follow the coast north out of town to the hovels."] = "{item:279915}在{area:150}南邊的岸上，過了城鎮南端走一小段就到。然後沿著海岸向北出城，前往小屋。",
		["{item:279915}, from {npc:270844} in {area:150}"] = "{item:279915}，來自{area:150}的{npc:270844}",
		["{item:281014}, from {object:673431}"] = "{item:281014}，來自{object:673431}",
		["{npc:1077}, below ground"] = "{npc:1077}，在地下",
		["{npc:1077}: for {npc:5387} in {zone:1455}, at the end of this guide"] = "{npc:1077}：給{zone:1455}的{npc:5387}，在本指南結尾",
		["{npc:1078} and Whelgar"] = "{npc:1078}與維爾加",
		["{npc:11406} and {npc:258785} are in the {object:32386}, in the {object:32362}."] = "{npc:11406}和{npc:258785}在{object:32362}的{object:32386}。",
		["{npc:1158}; careful: {npc:270589}, a level 31 elite, roams this coast"] = "{npc:1158}；小心：{npc:270589}，31級精英，在這片海岸遊蕩",
		["{npc:1239}, in the inn"] = "{npc:1239}，在旅店裡",
