		["{npc:4078}: the Saltstone Basilisks at the {area:2240} drop the scales, in the next guide"] = "{npc:4078}：鱗片由{area:2240}的鹽石蜥蜴掉落，在下一份指南",
		["{npc:4961} waits in the Pig and Whistle tavern in {object:2100}; he and his two thugs fight you, but stop once beaten."] = "{npc:4961}在{object:2100}的酒館裡等候；他和他的兩個打手會跟你打，但被打敗後就會停手。",
		["{npc:5479} trains warriors in {object:2100}, beside the Pig and Whistle. {npc:6236} waits on {area:720} in the {zone:1413}, on the way to {area:392} much later (40-50/01)."] = "{npc:5479}在{object:2100}的酒館旁訓練戰士。{npc:6236}在{zone:1413}的{area:720}等候，要很久以後前往{area:392}的途中才會經過（40-50/01）。",
		["{object:671518}: for {npc:2104}"] = "{object:671518}：給{npc:2104}",
		["{zone:1455} has no druid trainer: {npc:5504} stands in {zone:1453}, north-west of the {object:2101}."] = "{zone:1455}沒有德魯伊訓練師：{npc:5504}在{zone:1453}，位於{object:2101}西北方。",
} end)()
t.guides["forever/alliance/30-40/02-desolace"] = (function() return {
		["Escort {npc:5644}"] = "護送{npc:5644}",
		["Fly to {area:442}"] = "飛往{area:442}",
		["Follow the road west past {area:460} (Horde) and south-west through the {area:465} into {zone:1443}; {area:608} stands at the top of the pass."] = "沿著道路向西經過{area:460}（部落），再向西南穿過{area:465}進入{zone:1443}；{area:608}位於山口頂端。",
		["For {npc:5638}, at the end of this guide"] = "給{npc:5638}的，在本指南結尾",
		["Her brother {npc:5643} (36) walks the fortress with the Burning Blade cultists (30-33): pull him alone. The {npc:13019} keeps the sceptre in the fortress's main building. {npc:5642} wants four of each kind of cultist on the way."] = "她的哥哥{npc:5643}（36級）和燃刃氏族教徒（30-33級）一起在要塞裡走動：單獨把他拉出來。{npc:13019}把權杖放在要塞的主建築裡。{npc:5642}要你在途中每種教徒各殺四個。",
		["Lead {npc:5644} out of the fortress; she walks off once you are clear of it. {npc:5642} takes the turn-in at {area:608} at the end of the guide."] = "帶{npc:5644}走出要塞；離開要塞後她就會自行離去。指南結尾時在{area:608}向{npc:5642}繳交。",
		["Malem chest"] = "瑪雷姆的箱子",
		["Out of Thunder Axe Fortress"] = "離開雷斧堡壘",
		["The Kolkar roam the plains around {area:609}; their ears are for {npc:5752}."] = "科卡爾半人馬在{area:609}周圍的平原上遊蕩；牠們的耳朵是給{npc:5752}的。",
		["The chest lies in the ruins south-west of {area:608}."] = "箱子在{area:608}西南方的廢墟中。",
		["The wrecked ship lies just south-west of {npc:11863}'s tower; its chest sits beside {object:177787}."] = "沉船就在{npc:11863}的塔西南方不遠處；它的箱子在{object:177787}旁邊。",
		["{npc:11596}'s camp is on the road south of {area:609}, by the {area:596}."] = "{npc:11596}的營地在{area:609}南邊的路上，位於{area:596}旁。",
		["{npc:11863}'s tower stands on the hill west of {area:599}: take his quest first, the sceptre he wants is in the fortress."] = "{npc:11863}的塔位於{area:599}西邊的山丘上：先接他的任務，他要的權杖就在要塞裡。",
		["{npc:5396}, beside {npc:5752}"] = "{npc:5396}，在{npc:5752}旁邊",
		["{npc:5638}: the satchel lies off the north-west coast, on the south loop at the end of 30-40 (06-badlands): keep it"] = "{npc:5638}：背包在西北海岸外，位於30-40（06-荒蕪之地）結尾的南線上：先留著",
		["{npc:5638}: the wreck's chest lies below {npc:11863}'s tower, on the way to {area:599}"] = "{npc:5638}：沉船的箱子在{npc:11863}的塔下方，位於前往{area:599}的路上",
		["{npc:5643} and the Seer"] = "{npc:5643}與先知",
		["{npc:5644} hides inside the Burning Blade's fortress south-west of {area:608}."] = "{npc:5644}躲在{area:608}西南方火刃的要塞裡。",
} end)()
t.guides["forever/alliance/30-40/03-ashenvale"] = (function() return {
		["Boat to {area:150}"] = "搭船前往{area:150}",
		["East through the canyons. {area:484}, a Horde camp with guards, sits on the mesa here: keep to the canyon floor and give the foot of its lifts a wide berth."] = "向東穿過峽谷。{area:484}是部落的營地，有守衛，位於這裡的台地上：沿著峽谷底部走，離它的升降梯底部遠一點。",
		["Fly to Theramore"] = "飛往塞拉摩",
		["Fly to {area:150}"] = "飛往{area:150}",
		["Follow the canyons east to the salt flats. The goblins and gnomes of the {area:2240} are neutral and give quests to both factions."] = "沿著峽谷向東前往鹽湖。{area:2240}的哥布林和地精是中立的，兩個陣營都能接他們的任務。",
		["For {quest:1132} in Theramore's inn, where this guide's boat goes"] = "為了希拉摩旅店的{quest:1132}，本指南的船會開往那裡",
		["For {quest:5762} in Stranglethorn, later"] = "交給荊棘谷的{quest:5762}，稍後",
		["Lightforge Ingots"] = "光鑄鐵錠",
		["On the road south through the {zone:1413}, {npc:6244} camps east of the road, north-east of {area:378}; come in from the east and keep clear of the Horde guards."] = "在向南穿過{zone:1413}的道路上，{npc:6244}在道路東邊、{area:378}東北方紮營；從東邊過去，避開部落衛兵。",
		["The Bluegill murlocs on the beach south-west of Menethil carry the ingots."] = "米奈希爾西南方海灘上的藍腮魚人帶著鐵錠。",
		["The flight master stands by the gate of {area:514}; {npc:5083} and {npc:4964} are inside the citadel."] = "飛行管理員站在{area:514}的大門旁；{npc:5083}和{npc:4964}在要塞裡面。",
		["The wreck of the Flying Osprey lies in the shallows south of the keep."] = "沉船殘骸在城堡南邊的淺水處。",
		["Theramore"] = "塞拉摩",
		["{area:976} flight master"] = "{area:976}飛行管理員",
		["{npc:1217} stands in the {area:2104}, south of the keep, where {npc:4963} and {npc:5082} wait too."] = "{npc:1217}站在城堡南邊的{area:2104}裡，{npc:4963}和{npc:5082}也在那裡等著。",
		["{npc:4455} stands by {area:2103}'s door, just north of the flight master."] = "{npc:4455}站在{area:2103}門口，就在飛行管理員北邊。",
		["{quest:1132}, inside the inn in the north of town"] = "{quest:1132}，在鎮北的旅店內",
		["{quest:1738}: in {zone:1440}, on the way to {zone:1443}"] = "{quest:1738}：在{zone:1440}，前往{zone:1443}的路上",
		["{quest:65602}: the incubus, beside the succubus; the {item:190309} is near the {quest:1738}"] = "{quest:65602}：夢魔在魅魔旁邊；{item:190309}在{quest:1738}附近",
} end)()
t.guides["forever/alliance/30-40/04-stranglethorn-vale"] = (function() return {
		["Back south past Nesingwary: Panthers and Stranglethorn Raptors run in the clearings west of the camp toward the coast; the elder tigers hold the hills south-west."] = "往南經過赫米特·奈辛瓦里：黑豹和荊棘谷迅猛龍在營地西邊通往海岸的空地上奔跑；老年荊棘谷猛虎佔據西南方的丘陵。",
		["Both roam the grass around the camp and along the road north."] = "兩者都在營地周圍的草地和往北的道路沿線遊蕩。",
		["Class training"] = "職業訓練",
		["Down to {area:35}"] = "前往{area:35}",
		["Fly to {area:42}"] = "飛往{area:42}",
		["Fly to {zone:1453}"] = "飛往{zone:1453}",
		["Follow the main road south the length of the jungle, past the {object:3202} turn-off, to {area:35} on the southern cape."] = "沿主要道路向南穿過整片叢林，經過{object:3202}岔路，到達南端海角的{area:35}。",
		["From {zone:1431} take the road south into Stranglethorn; the hunters' tents stand just west of the road past the {area:99} turn-off."] = "從{zone:1431}沿道路向南進入荊棘谷；獵人的帳篷就在過了{area:99}岔路後的道路西邊。",
		["Gluggle, a rare murloc on the coast west of camp, drops the {item:4614}: take it if you meet him"] = "戈魯格爾是營地西邊海岸上的稀有魚人，會掉落{item:4614}：遇到就拿",
		["Panthers, raptors and elder tigers"] = "黑豹、迅猛龍與老年猛虎",
		["River Crocolisks swim the river by the {area:99}."] = "淡水鱷在{area:99}旁的河中游動。",
		["River crocolisks"] = "淡水鱷",
		["Stranglethorn Tigers"] = "荊棘谷猛虎",
		["Take the road north; the camp sits in the hills to the west.\n{npc:738} offers {quest:215} only while he is out of the camp: about every half hour he walks down the path to the road, where two Kurzen's Agents ambush him. Help him kill them and take the quest at once, before he walks back up. He isn't there? Leave it: the guide passes {quest:200}, which follows from it, as well."] = "沿道路向北；營地在西邊的丘陵中。\n{npc:738}只有在營地外時才會提供{quest:215}：他大約每半小時沿小徑走到大路上，兩名庫爾森的密探會在那裡伏擊他。幫他殺掉他們，並在他走回去之前立刻接下任務。他不在？那就算了：指南也會略過由此引出的{quest:200}。",
		["The Kurzen rebels hold the camp east of the {area:99}; work its outer edge, where Jungle Fighters and Medicine Men stand, and loot the supply crates by the tents. {quest:200}'s records lie in a hut on the compound's west side. Careful: Kurzen Elites and Witch Doctors (36) hold the compound's eastern half, by the cave: stay on its west side."] = "庫爾森叛軍佔據{area:99}東邊的營地；在外圍活動，那裡有庫爾森叢林戰士和庫爾森藥草師，並拾取帳篷旁的補給箱。{quest:200}的記錄在營地西側的一間小屋裡。小心：庫爾森精英和庫爾森巫醫（36級）佔據營地東半部的洞穴旁：待在營地西側。",
		["The adult tigers prowl the hills just south and west of the camp."] = "成年猛虎在營地南邊和西邊不遠的丘陵徘徊。",
		["The elder tigers come later, on the way back from the {area:99}"] = "老年荊棘谷猛虎之後再打，在從{area:99}回來的路上",
		["The haunted island"] = "鬧鬼的島",
		["Young tigers and panthers"] = "小荊棘谷猛虎與小獵豹",
		["{item:190309}, north of {area:413}"] = "{item:190309}，在{area:413}北邊",
		["{item:2634}, from a {object:263} crate"] = "{item:2634}，來自{object:263}箱子",
		["{npc:2495}, by the bank; inside"] = "{npc:2495}，在銀行旁；在裡面",
		["{npc:2496}, upstairs in the tavern"] = "{npc:2496}，在酒館樓上",
		["{npc:2832}, in the {object:56910}; upstairs"] = "{npc:2832}，在{object:56910}；在樓上",
		["{npc:469}, in the hut"] = "{npc:469}，在小屋裡",
		["{npc:715}, from {zone:1441}"] = "{npc:715}，來自{zone:1441}",
		["{npc:716} collects the {item:2755}: the pages drop from almost every humanoid in the jungle. Turn the pages into chapters as you go."] = "{npc:716}收集{item:2755}：叢林中幾乎每個人形生物都會掉落書頁。邊走邊把書頁整理成章節。",
		["{npc:729} and the Lashtail raptors"] = "{npc:729}與鞭尾迅猛龍",
		["{npc:729}, the great tiger, lairs on the hilltop south-west of the camp; Lashtail Raptors run south of it, along the way to {area:35}."] = "巨虎{npc:729}的巢穴在營地西南方的山頂；鞭尾迅猛龍在它南邊、前往{area:35}的路上奔跑。",
		["{npc:737}, in the tavern"] = "{npc:737}，在酒館裡",
		["{npc:738}, at the foot of the path"] = "{npc:738}，在小徑下端",
		["{npc:770}: for {npc:773} in {area:35}, later in this guide"] = "{npc:770}：給{area:35}的{npc:773}，在本指南稍後",
		["{npc:773}, in the tavern; upstairs"] = "{npc:773}，在酒館裡；在樓上",
		["{quest:201}: just look around the hunters' camp"] = "{quest:201}：只需在獵人營地四處看看",
} end)()
t.guides["forever/alliance/30-40/04b-stranglethorn-vale"] = (function() return {
		["East to the {area:99}, on the way back to Nesingwary's camp."] = "向東前往{area:99}，順路返回奈辛瓦里營地。",
		["East to {area:101}: Herod's records lie in a hut on its west side."] = "向東前往{area:101}：赫洛德的帳本放在營地西側的一間小屋裡。",
		["Fly to {area:42}"] = "飛往{area:42}",
		["For Archmage Ansirem in {zone:1416}"] = "給{zone:1416}的大法師安斯雷姆·魯因維沃爾",
		["For characters of 35 to 36, but several quests here are level 37-41: on purpose, for their experience. {quest:205}'s Skullsplitter trolls are 39-42, so pull them one at a time."] = "適合35到36級的角色，但這裡有幾個任務是37-41級：這是刻意安排的，為了它們的經驗值。{quest:205}的劈顱食人妖為39-42級，所以一次拉一隻。",
		["North along the coast to the ruins on the hill: the last two tablets lie there. Pick up Green Hills pages as they drop."] = "沿著海岸向北前往山丘上的廢墟：最後兩塊石板就在那裡。綠色山丘的書頁掉落時記得撿起來。",
		["Skullsplitter trolls"] = "劈顱食人妖",
		["Snapjaw Crocolisks"] = "鉗嘴鱷魚",
		["South from the compound to {area:37}: the Venture Co. Geologists in the camps on its shore carry the Tumbled Crystals, and the Shadowmaw Panthers prowl stealthed in the jungle south and east of it."] = "從營地向南前往{area:37}：湖岸營地中的風險投資公司地質學家身上帶著打磨過的水晶，深喉獵豹則潛行在湖泊南邊和東邊的叢林中。",
		["The Skullsplitter trolls hold the ruins east of the road between Nesingwary and {object:3202}."] = "劈顱食人妖佔據奈辛瓦里與{object:3202}之間道路東邊的廢墟。",
		["The haunted island lies just off the shore west of the second tablet: the Lesser Water Elementals rise from the water around it."] = "鬧鬼的小島就在第二塊石板西邊的岸外不遠處：次級水元素從小島周圍的水中冒出。",
		["The jungle ruins"] = "叢林廢墟",
		["The {area:102}"] = "{area:102}",
		["West across the jungle to the troll ruins: each holds one stone tablet of the troll legends, the first two in the ruins south-west of Nesingwary's camp, the last two on the hill in the north-west."] = "向西穿過叢林前往食人妖廢墟：每處都有一塊記載食人妖傳說的石板，前兩塊在奈辛瓦里營地西南方的廢墟中，後兩塊在西北方的山丘上。",
		["{npc:2496}, upstairs in the tavern"] = "{npc:2496}，在酒館樓上",
		["{npc:718}: the Shadowmaw Panthers prowl around {area:37}, after {area:101}"] = "{npc:718}：深喉獵豹在{area:37}周圍徘徊，先去{area:101}之後再來",
		["{npc:770}: for {npc:773} in {area:35}"] = "{npc:770}：給{area:35}的{npc:773}",
		["{npc:773}, upstairs: this optional quest needs four {item:4278}. Mine Lesser Bloodstone Deposits in {zone:1417} with {skill:186} 75, or buy the ore at the Auction House or ask a miner friend. The kobolds do not drop it; skip this quest if you cannot get the ore."] = "{npc:773}在樓上：這個可選任務需要四塊{item:4278}。在{zone:1417}用{skill:186} 75開採次級血石礦脈，或在拍賣場購買礦石，或請會採礦的朋友幫忙。狗頭人不會掉落它；拿不到礦石就跳過這個任務。",
} end)()
t.guides["forever/alliance/30-40/05-arathi-highlands"] = (function() return {
		["A {npc:2434} lurks stealthed on the edge of {area:271}, and few players find him. If you spot him, kill him and read the contract he carries: {npc:2276} takes it. Don't wait for him: the rest of this step doesn't need him."] = "一個{npc:2434}隱身潛伏在{area:271}邊緣，很少有玩家能找到他。如果發現他，殺死他並閱讀他身上的契約：{npc:2276}會收下它。不要專門等他：這一步的其餘部分不需要他。",
		["Back out of the grate to Modera's camp on the lake shore."] = "從柵欄出來，回到湖岸上摩德拉的營地。",
		["Back west through {zone:1430} to {area:42}."] = "向西穿過{zone:1430}回到{area:42}。",
		["Below ground"] = "地下",
		["City of Dalaran"] = "達拉然城",
		["Crushridge ogres"] = "破碎嶺巨魔",
		["Each key lies at one of the Highlands' standing-stone circles: east of the shards, near {area:320} and in the west. The {object:2702} stands west of {area:320}.\nCareful: Each center stone is guarded by around three elementals near level 39 that attack together if you click the stone without clearing them: Burning Exiles at West, Thundering Exiles at Outer, Cresting Exiles at East."] = "每把鑰匙都在高地的一處立石圈：碎片東邊、{area:320}附近，以及西部。{object:2702}在{area:320}西邊。\n小心：每塊中央石頭都有大約三隻接近39級的元素守護，如果沒先清掉就點擊石頭，牠們會一起攻擊：西側石圈是燃燒的流放者，外圍石圈是雷霆流放者，東側石圈是浪峰流放者。",
		["East along the road to the {area:76}. {npc:256028} mobs drop the crystals. {quest:1392} walks a long path through the ruins: if you meet him, kill him, his cudgel starts a quest for {npc:1776}. Don't wait for him."] = "沿道路向東前往{area:76}。{npc:256028}怪物會掉落水晶。{quest:1392}會沿一條很長的路線穿過廢墟走動：如果遇到他，就殺了他，他的木棒會開始一個交給{npc:1776}的任務。不要專門等他。",
		["East from {area:327} through the southern hills: {npc:2793}, an ogre mage, holds the cave at the southern end of the Witherbark valley."] = "從{area:327}向東穿過南部丘陵：巨魔法師{npc:2793}佔據枯木山谷南端的洞穴。",
		["East from {quest:681} across the north of the Highlands; the shards glitter on the hill by the {area:333}, north of {area:314}."] = "從{quest:681}向東橫越高地北部；碎片在{area:314}北邊、{area:333}旁的山丘上閃閃發光。",
		["Fly to {area:144}"] = "飛往{area:144}",
		["Fly to {area:271}"] = "飛往{area:271}",
		["Fly to {area:42}"] = "飛往{area:42}",
		["Fly to {zone:1453}"] = "飛往{zone:1453}",
		["Follow the road east out of {area:287} over {area:1057} to {area:320}."] = "沿道路從{area:287}向東越過{area:1057}前往{area:320}。",
		["Follow the road north out of {area:271} into the mountains. Mountain lions roam the slopes; the Syndicate in {area:280} wear the signet rings. {npc:2306} (40) turns up in one spot at a time: the cellar of {area:280}'s inn, or one of the Syndicate tent camps in the uplands north and north-west of the village."] = "沿道路從{area:271}向北進入山區。山地獅在山坡上遊蕩；{area:280}的辛迪加戴著圖章戒指。{npc:2306}（40）每次只會出現在一個地點：{area:280}旅店的地窖，或村莊北邊及西北邊高地上的某個辛迪加帳篷營地。",
		["Follow the road north to the draenei of the {area:657}."] = "沿道路向北前往{area:657}的德萊尼人那裡。",
		["For characters of 36 to 38, but {area:327} and the Alterac Syndicate quests are level 40: on purpose, for their experience. {npc:2768}'s two water elementals (40) are immune to frost, and {npc:2306} (40) waits among his Syndicate: pull them one at a time."] = "適合36到38級的角色，但{area:327}和奧特蘭克辛迪加的任務是40級：這是刻意安排的，為了它們的經驗值。{npc:2768}的兩個水元素（40級）免疫冰霜，{npc:2306}（40級）在他的辛迪加手下之間等著：一次拉一個。",
		["For your City of Dalaran run, next: the {npc:269127} wants the arcane remnants in the city thinned out and a mote from the heart of the disruption. {quest:92458} brings the {item:277507}, which opens the grate."] = "為了你接下來的達拉然城之行：{npc:269127}要你削減城裡的奧術殘影，並從混亂之心取得一顆微粒。{quest:92458}會給你{item:277507}，用來打開柵欄。",
		["For {npc:1440} in {zone:1453}: keep it"] = "給{zone:1453}的{npc:1440}：先留著",
		["For {npc:2487} in {area:35}: keep it"] = "給{area:35}的{npc:2487}：先留著",
		["For {npc:2542} in {area:35}: keep it"] = "給{area:35}的{npc:2542}：先留著",
		["For {npc:2711} in {area:271}"] = "給{area:271}的{npc:2711}",
		["From {zone:1455} take the tunnel east through {zone:1426} into {zone:1432} and follow the road to {area:144}."] = "從{zone:1455}走隧道向東穿過{zone:1426}進入{zone:1432}，沿道路前往{area:144}。",
		["North-west out of the Witherbark valley; {npc:2712} and {npc:2713} camp in the hills just north of {area:314}."] = "向西北離開枯木山谷；{npc:2712}和{npc:2713}在{area:314}北邊不遠的丘陵紮營。",
		["Only if Gluggle gave you the pendant in Stranglethorn"] = "只有在荊棘谷的戈魯格爾給了你墜飾時",
		["Phizzlethorpe"] = "菲茲索普教授",
		["South along the west coast to the goblins' cove; Lolo keeps watch on the rocks above it."] = "沿西海岸向南前往哥布林的海灣；哨兵魯魯在上方的岩石上守望。",
		["South from the {object:2691}, past {area:314}, to {area:317} in the hills: the Witch Doctors stand among the huts and the Shadow Hunters guard the far end of the valley. Every troll can drop a tusk."] = "從{object:2691}向南，經過{area:314}，前往丘陵中的{area:317}：枯木巫醫站在小屋之間，枯木暗影獵手守在山谷遠端。每個食人妖都可能掉落獠牙。",
		["South-east along the loch to the dig site."] = "沿湖向東南前往挖掘場。",
		["South-west to the Kirin Tor camp on the lake shore west of {area:279}, just over the border into {zone:1421}: the {npc:269127} stands there. Archmage Ansirem stands south-east of it, by the dome."] = "向西南前往{area:279}西邊湖岸的祈倫托營地，就在越過邊界進入{zone:1421}之處：{npc:269127}站在那裡。大法師安斯雷姆·魯因維沃爾站在它東南方的穹頂旁。",
		["Stay with {npc:2713} while she sneaks into {area:314} and back; Horde orcs jump you on the way.\nCareful: Orcs that drop to low health run away. {npc:2713} follows them and can pull more mobs, so kill or slow runners fast."] = "跟著{npc:2713}潛入{area:314}再回來；途中部落獸人會突襲你。\n小心：血量低的獸人會逃跑。{npc:2713}會追上去，可能引來更多怪，所以要盡快殺掉或減速逃跑的敵人。",
		["The City of Dalaran is a dungeon for a group of five at about level 28 to 33: at your level it goes quickly. Its way in is the sewer grate in the city's western wall, by the lake, 30 yards from Modera's camp.\nInside: the Seeking Remnants, Saturated Remnants and Mana Echoes are Modera's {quest:92457}; the {item:251961} for {quest:92458} drops inside too."] = "達拉然城是五人地城，約28到33級：以你的等級會打得很快。入口是城市西牆的下水道柵欄，在湖邊，距離摩德拉的營地30碼。\n裡面：搜尋殘影、飽和殘影和法力回音是摩德拉的{quest:92457}；{quest:92458}的{item:251961}也在裡面掉落。",
		["The Crushridge ogres hold the hills north of {area:280}. Farther north, a worn wooden chest holds the {item:3706}; {npc:2320} of the {quest:537} stands right by it.\nThe Crushridge Maulers, Mages, Enforcers and Warmongers (36-39) are elite; the Crushridge Ogres and Brutes (34-35) are not and drop the knucklebones too: pull one at a time, or group up."] = "破碎嶺巨魔佔據{area:280}北邊的丘陵。再往北，一個破舊的木箱裡有{item:3706}；{quest:537}的{npc:2320}就站在旁邊。\n破碎嶺搗毀者、法師、執行者和戰爭販子（36-39級）是精英；破碎嶺巨魔和蠻兵（34-35級）不是精英，也會掉落指節骨：一次拉一隻，或組隊。",
		["The Drywhisker kobolds dig in the gorge east of {area:321} (Horde); skirt the town to the north. They drop the Motes of Myzrael, not Krazek's ore. Lesser Bloodstone Deposits need {skill:186} 75: mine four ore, buy them at the Auction House, or ask a miner friend. The ore goal is optional; continue with Myzrael if you cannot get it. Careful: Every kobold type runs off for help when low on health (Kobolds at 30%, Surveyors and Diggers at 15%), which can pull more of them."] = "枯鬚狗頭人在部落城鎮{area:321}以東的峽谷裡採掘，從城鎮北側繞過去。牠們掉落密斯賴爾之塵，不掉克拉茲克要的礦石。次級血石礦脈需要{skill:186} 75：開採四塊礦石、在拍賣場購買，或請會採礦的朋友幫忙。礦石目標是可選的；拿不到就繼續做密斯賴爾的任務。小心：每種狗頭人在低血量時都會逃跑求援（枯鬚狗頭人30%，勘探員和掘地工15%），可能引來更多敵人。",
		["The courier walks the road from {area:314} west across the Highlands, as far as about 24,45, and back, with two guards: the arrow follows the road west until you meet him. Pull them off the road."] = "被遺忘者信差帶著兩名守衛，沿道路從{area:314}向西橫越高地，最遠約到24,45，再走回來：箭頭會沿道路向西指引，直到你遇見他。把他們拉離道路。",
		["The shards lie at the far end of {area:318}."] = "碎片在{area:318}的最深處。",
		["The two wrecks lie in the bay west of the cove. The charts and logs are inside them; the gems lie on the sea floor around them. Daggerspine naga swim the whole bay."] = "兩艘沉船在海灣西邊的海灣裡。海圖和航海日誌在船內；寶石散落在周圍的海床上。刺脊納迦在整個海灣游動。",
		["The western swamp"] = "西部沼澤",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:2417} is a level 40 elite: most classes solo it at level 42, but you may need help. Skip it if you are alone: the route has you grind the XP back.\n{npc:2417} walks from the arrow north-east through the ruins to about 40,47 and back: if he isn't at the arrow, follow his path."] = "這些是精英怪物：建議組隊，找人一起打。{npc:2417}是40級精英：大多數職業在42級時可以單刷，但你可能需要幫忙。如果你是獨自一人就跳過：路線會讓你把經驗值練回來。\n{npc:2417}會從箭頭處向東北穿過廢墟走到約40,47再走回來：如果他不在箭頭處，就沿著他的路線找。",
		["Young crocolisks, Sorrow Spinners and Swamp Jaguars all roam the swamp around the road."] = "小鹽齒鱷魚、沼澤紡絲蛛和沼澤虎都在道路周圍的沼澤遊蕩。",
		["from {quest:1392}: he walks a path through the ruins"] = "來自{quest:1392}：他沿一條路線穿過廢墟走動",
		["{item:3658}: Crushridge ogres"] = "{item:3658}：破碎嶺巨魔",
		["{item:3659}: the {object:1760}, beside Muckrake (40, elite): get it with a group, or abandon {quest:540}; inside"] = "{item:3659}：{object:1760}，在泥耙（40級，精英）旁邊：組隊去拿，或放棄{quest:540}；在裡面",
		["{npc:1141}, {area:17203} road"] = "{npc:1141}，{area:17203}的路上",
		["{npc:12336}, Cathedral of Light"] = "{npc:12336}，光明大教堂",
		["{npc:1440}, the Royal Library in the keep"] = "{npc:1440}，城堡裡的皇家圖書館",
		["{npc:185335}, at the same circle"] = "{npc:185335}，在同一個法陣",
		["{npc:217412}: three critters to catch in Arathi, {zone:1443} and Stranglethorn"] = "{npc:217412}：在阿拉希高地、{zone:1443}和荊棘谷各抓一隻小動物",
		["{npc:2434}, if you spot him"] = "{npc:2434}，如果你發現他",
		["{npc:2712} and {npc:2713}"] = "{npc:2712}與{npc:2713}",
		["{npc:2713}'s errand"] = "{npc:2713}的差事",
		["{npc:5391} is caged at the north end of the sanctuary. Free him and keep him alive on the walk out; his strongbox waits by the road afterwards. Careful: on the walk out the camp's Lost One Riftseekers (37-38) and their pets, with the Lost Ones around them, turn on {npc:5391}: clear the cage and the start of his path first, stay beside him and pull every attacker onto yourself. Many players lose him the first time; if he dies, abandon the quest and take it again at his cage."] = "{npc:5391}被關在聖所北端的籠子裡。釋放他並在走出去的路上保護他；之後他的保險箱就在路邊。小心：走出去的路上，營地裡的失落尋隙者（37-38級）和牠們的寵物，連同周圍的失落者，會攻擊{npc:5391}：先清掉籠子和他路線的起點，緊跟在他身邊，把所有攻擊者都拉到自己身上。很多玩家第一次會讓他死掉；如果他死了，就放棄任務，再到他的籠子重新接。",
		["{npc:6122} binds the incubus to you"] = "{npc:6122}會把夢魘束縛給你",
		["{npc:6122} waits in the {object:2164}'s cellar, in the {object:2101}. Use the {item:6913} at the summoning circle there and defeat the succubus it calls. If you took {quest:65602}, hand him the {item:190309} too, place it at the same circle and defeat the incubus."] = "{npc:6122}在{object:2101}{object:2164}的地窖裡等著。在那裡的召喚法陣使用{item:6913}，擊敗召喚出的魅魔。如果你接了{quest:65602}，也把{item:190309}交給他，放在同一個法陣並擊敗夢魘。",
		["{quest:65602}, if you took it"] = "{quest:65602}，如果你有接",
		["{quest:92457}: the remnants and echoes, inside"] = "{quest:92457}：殘影和回音，在裡面",
} end)()
t.guides["forever/alliance/30-40/06-badlands"] = (function() return {
		["East from the {area:1877} to {area:346}: {npc:2860} takes the scrap metal."] = "從{area:1877}向東前往{area:346}：{npc:2860}收廢金屬。",
		["For {npc:4454} at the {area:2240}: the {zone:1446} guide passes him at 45, keep it"] = "給{area:2240}的{npc:4454}：{zone:1446}指南會在45級時經過他，保留此任務",
		["Head back west to the road and follow it south out of {zone:1432} through the pass into the {zone:1418}. {npc:2910} and {npc:2860} camp side by side at the dig."] = "向西回到道路，沿路向南離開{zone:1432}，穿過山口進入{zone:1418}。{npc:2910}和{npc:2860}在挖掘場並肩紮營。",
		["Head north to {area:1517}'s entrance, in the north of the {zone:1418}: the chest lies just inside the cave mouth. {npc:2932} and the Obsidian Golems (38) stand beside it and Shadowforge Diggers (35-36) work the tunnel, all elite: keep your group together."] = "向北前往{zone:1418}北部的{area:1517}入口：箱子就在洞口內。{npc:2932}和黑曜石魔像（38級）站在旁邊，暗爐挖掘者（35-36級）在隧道裡工作，全都是精英：讓隊伍待在一起。",
		["Head north-east to the abandoned dig; the supply crate lies there among the Dustbelcher ogres."] = "向東北前往廢棄的挖掘場；補給箱就在那裡的火煙巨魔之間。",
		["Head south to {area:345}."] = "向南前往{area:345}。",
		["Head west into the {area:1878}; {npc:2921} works by his machines in the middle of it."] = "向西進入{area:1878}；{npc:2921}在中央的機器旁工作。",
		["Lesser Rock Elementals"] = "次級石元素",
		["Rock Elementals"] = "石元素",
		["Ryedol's next errand goes into {area:1517}: skip it."] = "雷杜爾的下一個任務要進入{area:1517}：跳過。",
		["The Lesser Rock Elementals wander the {area:1878} west of {npc:2921}; every rock elemental can drop {npc:1470}'s Rock Elemental Shards."] = "次級石元素在{npc:2921}西邊的{area:1878}遊蕩；每個石元素都可能掉落{npc:1470}要的石元素碎片。",
		["The Rock Elementals roam south-east of {npc:2921}; Giant Buzzards and Elder Crag Coyotes share the plain to their west."] = "石元素在{npc:2921}東南方遊蕩；巨型禿鷲和老峭壁山狗則在牠們西邊的平原上。",
		["The Shadowforge dwarves camp just north of the digsite; the crumpled map lies among their tents. Tunnelers and Darkweavers carry Ryedol's pick. Crag Coyotes roam the slopes around it."] = "暗爐矮人在挖掘場北邊紮營；揉皺的地圖在他們的帳篷之間。暗爐隧道工和暗爐巫師身上帶著雷杜爾的鋤頭。峭壁山狗在周圍的山坡上遊蕩。",
		["The battered skeleton lies just east of the ogres, at the edge of the Stonevault trogg camp; the Bonesnappers and Shamans around it drop the flakes. Theldurin sits by the ruined camp further south."] = "破損的骷髏就在巨魔東邊、石窟穴居人營地的邊緣；周圍的石窟斷骨者和石窟薩滿會掉落碎片。塞爾杜林坐在更南邊的廢棄營地旁。",
		["The clams lie on Stranglethorn's north-west coast, in the next guide: keep it"] = "蚌殼在荊棘谷的西北海岸，在下一份指南中：保留此任務",
		["The excavation crate"] = "挖掘箱",
		["The {object:126260}"] = "{object:126260}",
		["Theldurin sits by the ruined camp south of the trogg camp. His tablet lies just inside {area:1517}'s cave mouth, beside level 38 elites: a quest for a group."] = "塞爾杜林坐在穴居人營地南邊的廢棄營地旁。他的石板就在{area:1517}的洞口內，旁邊是38級精英：這是組隊任務。",
		["To {area:2101}"] = "前往{area:2101}",
		["for {npc:2786} in {zone:1455}: keep it"] = "給{zone:1455}的{npc:2786}：保留此任務",
		["{npc:2920}, beside {npc:2921}"] = "{npc:2920}，在{npc:2921}旁邊",
		["{npc:4618} and {npc:2817} camp in the {area:1877}, on the road between {area:1517} and {area:345}."] = "{npc:4618}和{npc:2817}在{area:1877}紮營，就在{area:1517}和{area:345}之間的道路上。",
		["{npc:4618} and {npc:2817} camp together in the {area:1877}, in the middle of the {zone:1418}."] = "{npc:4618}和{npc:2817}一起在{zone:1418}中部的{area:1877}紮營。",
} end)()
t.guides["forever/alliance/30-40/06b-desolace"] = (function() return {
		["A {npc:217590} crawls about the {area:596}: catch one with the tool from {npc:217412}'s {item:213565}."] = "一隻{npc:217590}在{area:596}爬來爬去：用{npc:217412}給的{item:213565}裡的工具抓一隻。",
		["Fly to Theramore"] = "飛往塞拉摩",
		["Fly to {area:150}"] = "飛往{area:150}",
		["Follow the road north to {area:608}: {npc:5396} stands at its south end, {npc:5638} in the middle, {npc:1182} to the north."] = "沿著道路向北前往{area:608}：{npc:5396}站在南端，{npc:5638}在中間，{npc:1182}在北邊。",
		["Follow the road south to {area:2407}."] = "沿著道路向南前往{area:2407}。",
		["Follow the road west across the north of {zone:1443} to the ruins of {area:2405}. {npc:11863}'s tower stands on the hill there, on the way to the wreck."] = "沿著道路向西穿過{zone:1443}北部，前往{area:2405}的廢墟。{npc:11863}的塔就在那裡的山丘上，在前往沉船的路上。",
		["Maraudine centaurs"] = "瑪勞登半人馬",
		["Off the boat, walk up the pier to Baldruc, the flight master by the gate of {area:514}."] = "下船後沿碼頭往上走，到{area:514}大門旁的飛行管理員巴德拉克那裡。",
		["Rackmore's chest lies just south-east of the {object:177673}."] = "拉克摩的箱子就在{object:177673}東南方不遠處。",
		["The Maraudine centaurs hold the {area:607} west of the graveyard; every kind drops the totems."] = "瑪勞登半人馬佔據墓地西邊的{area:607}；每一種都會掉落圖騰。",
		["The Slitherblade naga hold the north-west coast north of {npc:11863}'s tower; Karnitol's satchel lies on the sea floor off it, and any naga can drop Rackmore's golden key. Swim out to {area:2406} off the far northern tip and use the {item:15766} on the {object:177673}: {npc:12369} (38) rises; kill him for the {quest:6027}."] = "滑刃納迦佔據{npc:11863}塔北邊的西北海岸；卡尼托的背包在外海的海底，任何納迦都可能掉落拉克摩的金鑰匙。游到最北端外海的{area:2406}，對{object:177673}使用{item:15766}：{npc:12369}（38級）會出現；擊殺他取得{quest:6027}。",
		["The demons gather at the {area:602} in southern {zone:1443}: felhounds (Mana Eaters, Mage and Ley Hunters), Nether Maidens and Sisters, and Doomwarder Captains around the pit.\nCareful: Most of the mobs here walk patrol routes, so you can easily pull extra mobs."] = "惡魔聚集在{zone:1443}南部的{area:602}：坑洞周圍有地獄犬（法力吞噬者、法師獵手和魔網獵手）、虛空少女和虛空姐妹，以及末日守衛隊長。\n小心：這裡大部分的怪都有巡邏路線，很容易多拉到怪。",
		["The next guide starts in Theramore."] = "下一份指南從塞拉摩開始。",
		["The wrecked ship's chest lies just south-west of {npc:11863}'s tower."] = "沉船的箱子就在{npc:11863}塔西南方不遠處。",
		["The {area:2657}"] = "{area:2657}",
		["Theramore flight master"] = "塞拉摩飛行管理員",
		["Undead Ravagers roam the bone fields south of the Magram village, east of the Coven: the arrow leads to their western edge. Then use the {item:15848} at its arrow, on the fields' eastern side, to draw the Magrami Spectres. Careful: Magram Necrokhans and Corpsefeeders (45, elite) walk the bone fields between the two arrows, with Magram Necromancers (42): pull the Ravagers and the spectres to you, away from them."] = "不死掠奪者在瑪格拉姆村莊南邊、巫團東邊的骨原上遊蕩：箭頭會帶你到它們的西緣。然後在骨原東側的箭頭處使用{item:15848}，引來瑪格拉姆幽靈。小心：瑪格拉姆死靈可汗和食屍者（45級，精英）與瑪格拉姆死靈法師（42級）在兩個箭頭之間的骨原上走動：把掠奪者和幽靈拉到你這裡，遠離它們。",
		["Underwater"] = "在水下",
		["escort {npc:12277} back toward the graveyard"] = "護送{npc:12277}回墓地",
		["for {npc:3980} in {area:271}: keep it"] = "給{area:271}的{npc:3980}：先留著",
		["for {npc:5637} in {zone:1455}: keep it"] = "給{zone:1455}的{npc:5637}：先留著",
		["{area:144} flight master"] = "{area:144}飛行管理員",
		["{area:598}: kill these as you meet them"] = "{area:598}：遇到就殺",
		["{item:15766}, on the {object:177673}"] = "{item:15766}，對{object:177673}使用",
		["{item:15881}, from the Slitherblade naga"] = "{item:15881}，來自滑刃納迦",
		["{npc:12277} is held in the centaur camp west of the graveyard. Free her and keep her alive on the walk out; she stops by the graveyard.\nCareful: The scripted groups are linked and only appear during the escort, so you cannot clear them in advance or pull them one at a time. Clearing the normal centaurs on the path before you start does help."] = "{npc:12277}被關在墓地西邊的半人馬營地。救出她，在走出去的路上保護她存活；她會在墓地旁停下。\n小心：劇本中出現的敵人群彼此連動，只會在護送期間出現，所以無法事先清掉，也無法一次拉一隻。不過開始前先清掉路上一般的半人馬會有幫助。",
		["{npc:5638}, if 30-40/02 didn't take it: the wreck lies below {npc:11863}'s tower"] = "{npc:5638}，如果30-40/02沒接過：沉船在{npc:11863}的塔下方",
		["{npc:6019} stands at the edge of the {area:596}, south-west of {area:2407}; {object:176751} lie among the skeletons."] = "{npc:6019}站在{area:596}邊緣，{area:2407}西南方；{object:176751}散落在骨架之間。",
		["{object:177787} lies beside {object:35251}. His silver key drops from the Drysnap crabs around the wreck; the golden one comes from the Slitherblade naga on the north-west coast, next."] = "{object:177787}放在{object:35251}旁邊。他的銀鑰匙由沉船周圍的乾鉗螃蟹掉落；金鑰匙則來自西北海岸的滑刃納迦，接下來就去。",
} end)()
t.guides["forever/alliance/40-50/01-stranglethorn-vale"] = (function() return {
		["\"Stinky\" Ignatz"] = "伊格納茲",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4732} teaches Humans at {area:88} in eastern {zone:1429}, beside {npc:384}'s horses. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "40級且有100金幣時就能學騎術，學會後會得到一匹坐騎。{npc:4732}在{zone:1429}東部的{area:88}教導人類，旁邊是{npc:384}的馬匹。Forever 可能允許任何種族向任何騎術訓練師學習（未確認）。收藏品的「坐騎 · 40級」列出所有顏色。",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4753} teaches Night Elves in {zone:1457}, beside {npc:4730}'s sabers: the boat from {area:17203} to {area:442}, then the flight to {area:702}. Forever may let any race learn from any riding trainer (unconfirmed), such as {npc:4732} at {area:88} in {zone:1429}. Collectibles, Mounts · Level 40 lists every colour."] = "40級且有100金幣時就能學騎術，學會後會得到一匹坐騎。{npc:4753}在{zone:1457}教導夜精靈，旁邊是{npc:4730}的豹：從{area:17203}搭船到{area:442}，再飛往{area:702}。Forever 可能允許任何種族向任何騎術訓練師學習（未確認），例如{zone:1429}{area:88}的{npc:4732}。收藏品的「坐騎 · 40級」列出所有顏色。",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4772} teaches Dwarves at {area:803}, east of {area:131} on the road to {zone:1432}, beside {npc:1261}'s rams. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "40級且有100金幣時就能學騎術，學會後會得到一匹坐騎。{npc:4772}在{area:803}教導矮人，位於{area:131}東邊通往{zone:1432}的路上，旁邊是{npc:1261}的山羊。Forever 可能允許任何種族向任何騎術訓練師學習（未確認）。收藏品的「坐騎 · 40級」列出所有顏色。",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:7954} teaches Gnomes at {area:189}, just east of {area:131}, beside {npc:7955}'s mechanostriders. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "40級且有100金幣時就能學騎術，學會後會得到一匹坐騎。{npc:7954}在{area:189}教導地精，就在{area:131}東邊，旁邊是{npc:7955}的機械陸行鳥。Forever 可能允許任何種族向任何騎術訓練師學習（未確認）。收藏品的「坐騎 · 40級」列出所有顏色。",
		["Bloodsail camp"] = "血帆營地",
		["Boat to {area:150}"] = "搭船前往{area:150}",
		["Boat to {area:35}"] = "搭船前往{area:35}",
		["Cortello's scroll"] = "科泰羅的卷軸",
		["Defeat the challengers and {npc:6238}"] = "擊敗挑戰者和{npc:6238}",
		["Every Bloodsail drops Snuff and one of them carries {npc:2493}'s eye; the Swashbucklers walk the shore just north of town. The charts and orders lie in the pirate camp on the {area:43}, south of {area:35}.\nCareful: the {area:43} camp's Warlocks and Swashbucklers are level 41-43, a level or more above you, and stand close together: pull them singly from the edge."] = "每個血帆海盜都會掉落鼻煙，其中一個帶著{npc:2493}的眼睛；血帆流氓在城鎮北邊的岸上走動。海圖和命令在{area:35}南邊{area:43}的海盜營地裡。\n小心：{area:43}營地的血帆術士和血帆流氓是41-43級，比你高一級以上，而且站得很近：從邊緣一隻一隻拉。",
		["Every Zanzil follower can drop the mixture; {npc:2537} walks the south of the camp."] = "每個贊吉爾信徒都可能掉落混合物；{npc:2537}在營地南部走動。",
		["Fly to {area:144}"] = "飛往{area:144}",
		["Fly to {area:35}"] = "飛往{area:35}",
		["Fly to {area:42}"] = "飛往{area:42}",
		["Fly to {area:442}"] = "飛往{area:442}",
		["Fly to {zone:1453}"] = "飛往{zone:1453}",
		["Follow the road east back to Theramore. The officers are in {area:514}."] = "沿著道路向東回到塞拉摩。軍官們都在{area:514}。",
		["Follow the road north-west out of Theramore to the watchtower at {area:503}. Mudrock Burrowers roam the marsh around it.\n{npc:4967} waits at the foot of the tower: once you have looked around, hand the quest in to him there, not in Theramore."] = "沿著道路從塞拉摩向西北前往{area:503}的瞭望塔。泥石穴居龜在周圍的沼澤中遊蕩。\n{npc:4967}在塔下等候：四處查看過後，就在那裡把任務交給他，而不是在塞拉摩。",
		["Gorilla hills"] = "猩猩山丘",
		["Hand in the fangs and stay: three waves of gorillas come, {npc:1514} last. Fight at full health."] = "交出獠牙後留下來：會來三波猩猩，最後是{npc:1514}。滿血再戰。",
		["Jungle Stalkers"] = "叢林捕獵者",
		["Leave town by the tunnel and follow the coast north; the letter lies in the Bloodsail camp on the beach, where \"Pretty Boy\" Duncan walks.\nCareful: the Bloodsail Mages and Warlocks here are level 40-43 and cast from range: pull one at a time and fight with your back to the open beach."] = "從隧道離開城鎮，沿著海岸向北走；信件在海灘上的血帆營地裡，「帥小子」鄧肯在那裡走動。\n小心：這裡的血帆法師和血帆術士是40-43級，會遠程施法：一次拉一隻，背對開闊的沙灘戰鬥。",
		["Level 40 with 100 gold later on? {npc:4732} teaches riding at {area:88} in {zone:1429}: Collectibles, Mounts · Level 40 has the trip."] = "之後到了40級且有100金幣？{npc:4732}在{zone:1429}的{area:88}教授騎術：收藏品的「坐騎 · 40級」有這趟行程。",
		["MacKinley's next task sends you after elite ogres: skip it."] = "馬克基雷的下一個任務要你去打精英巨魔：跳過。",
		["Mirefin murlocs"] = "黑鰭魚人",
		["Naga Explorers"] = "納迦探險者",
		["No flight path to {area:144} yet: ride out of {zone:1455}'s gates, east through {zone:1426} and the tunnel into {zone:1432}, and on along the road to {area:144}."] = "還沒有{area:144}的飛行路線：騎出{zone:1455}的大門，向東穿過{zone:1426}和隧道進入{zone:1432}，再沿道路前往{area:144}。",
		["On the ride north to {area:392}, {area:720} lies off the {area:391} south of the town: wade over the sand bar shallows. {npc:6236} sends four challengers and then {npc:6238} (level 33) at you, one at a time."] = "往北騎向{area:392}的途中，{area:720}位於城鎮南邊的{area:391}外海：涉水走過沙洲淺灘。{npc:6236}會派出四名挑戰者，然後是{npc:6238}（33級），一次一個。",
		["Optional: Cortello's scroll lies inside one of the three Bloodsail ships anchored off the coast just south of {area:35}, on a middle or lower deck, and is not always on the same ship. Their crews are 42-45 pirates: clear your way from the edge, one at a time, and leave the captains (45-48), whom the route comes back for at 48."] = "可選：科泰羅的卷軸在{area:35}南邊不遠、停泊在外海的三艘血帆海盜船之一裡，位於中層或下層甲板，而且不一定每次都在同一艘船上。船員是42-45級的海盜：從邊緣一隻一隻清出路來，並避開船長（45-48），路線會在48級時回來對付他們。",
		["Paladin: {quest:1661}"] = "聖騎士：{quest:1661}",
		["Ride back down to town; Shaky stands at the tunnel mouth."] = "騎回城鎮；病鬼站在隧道口。",
		["Ride east; the Tangled Horrors along the way also drop the essays. Search the edge of the {area:74}, where the temple's ruins break the water."] = "向東騎；沿途的糾纏恐獸也會掉落研究筆記。在{area:74}邊緣搜尋，神廟遺跡就在那裡露出水面。",
		["Ride inland to the Mistvale gorilla hills. Elder Mistvale Gorillas drop the giblets; {npc:1449} sits among them."] = "向內陸騎往迷霧谷猩猩的山丘。老邁的迷霧谷猩猩會掉落內臟；{npc:1449}坐在牠們之間。",
		["Ride north to the hills west of the road. {npc:2535} and {npc:2536} stand together just north of Zanzil's village."] = "向北騎往道路西邊的山丘。{npc:2535}和{npc:2536}一起站在贊吉爾村莊北邊。",
		["Ride north-west from the mine to the bay on the north-west coast. The Giant Clams lie on its floor and hold the pearls; {npc:2624} swims among them and drops the {item:4034}."] = "從礦坑向西北騎往西北海岸的海灣。巨型蚌殼躺在海底，裡面有珍珠；{npc:2624}在牠們之間游動，會掉落{item:4034}。",
		["Ride north-west into the {zone:1413} and up the coast to {area:392}: the boat to {area:35} leaves from its dock, and {area:392}'s gryphon master stands just above it."] = "向西北騎進{zone:1413}，沿海岸北上到{area:392}：前往{area:35}的船從那裡的碼頭出發，{area:392}的獅鷲管理員就在碼頭上方。",
		["Ride south out of {zone:1432} through the pass into the {zone:1418}; {npc:2860} camps at the dig."] = "從{zone:1432}向南騎，穿過山口進入{zone:1418}；{npc:2860}在挖掘場紮營。",
		["Ride south to the giant's hut in the middle of the marsh."] = "向南騎往沼澤中央巨人的小屋。",
		["Riding and Galestriders: {npc:265756}, at the {area:17684} in {area:16638} on Zephras Isle."] = "騎術與逐風者：{npc:265756}，在微風島{area:16638}的{area:17684}。",
		["Riding at 40"] = "40級騎術",
		["Seahorn's next errand goes back to Arathi: skip it."] = "海角的下一個任務會回到阿拉希：跳過。",
		["Stinky waits west of the manor, in the marsh below {area:504}. Lead him to his Bogbean leaves and keep the swamp creatures off him."] = "伊格納茲在莊園西邊、{area:504}下方的沼澤裡等候。帶他去找他的藥草葉子，別讓沼澤生物靠近他。",
		["Take the road north to the ruined manor; Jarl lives in the shack beside it and the loose dirt is at the corner of the house. Jarl wants three {quest:1218}: if you passed {npc:4897}, buy them from her in Theramore first."] = "沿著道路向北前往毀壞的莊園；加爾住在旁邊的棚屋裡，鬆動的泥土在房子的轉角處。加爾要三個{quest:1218}：如果你經過了{npc:4897}，先在塞拉摩向她買。",
		["The Jungle Stalkers roam the slopes west of the mine."] = "叢林潛獵者在礦坑西邊的山坡上遊蕩。",
		["The Mirefin murlocs crowd the north coast past {area:497}."] = "黑鰭魚人聚集在{area:497}以北的海岸。",
		["The burned inn stands on the road west, toward the {zone:1413}; the guard's badge lies in the ashes."] = "燒毀的旅店位於西邊通往{zone:1413}的道路上；衛兵的徽章就在灰燼中。",
		["The deserters camp south of the road, west of {npc:4503}'s hut."] = "逃兵在道路南邊、{npc:4503}小屋西邊紮營。",
		["The driftwood washes up along the eastern shore."] = "浮木沖上東岸。",
		["The naga comb the beaches north of the Bloodsail camp; they drop the reeds."] = "納迦在血帆營地北邊的海灘上搜尋；牠們會掉落蘆葦。",
		["The north-west coast"] = "西北海岸",
		["The scroll lies in the marsh north of Biggs. The Swampwalkers north of it can drop Khadgar's essays."] = "卷軸在比格斯北邊的沼澤裡。它北邊的沼澤漫步者可能會掉落卡德加的空間收斂研究筆記。",
		["The sunken temple"] = "沉沒的神廟",
		["Theramore"] = "塞拉摩",
		["Unbagwa's ritual"] = "安巴格瓦的儀式",
		["Upstairs"] = "樓上",
		["Warlock: {quest:4488}"] = "術士：{quest:4488}",
		["Zanzil's village"] = "贊吉爾的村莊",
		["for Stoley in {zone:1446}: keep it; on the top floor"] = "給{zone:1446}的斯杜雷：保留此任務；在頂樓",
		["for the {zone:1435} later"] = "稍後用於{zone:1435}",
		["for {area:1438}: keep it"] = "給{area:1438}：保留此任務",
		["for {npc:2616} in Theramore: keep it"] = "給塞拉摩的{npc:2616}：保留此任務",
		["for {npc:5635} at {area:348}: keep it"] = "給{area:348}的{npc:5635}：保留此任務",
		["for {npc:770} at the {area:99}, on the northern loop"] = "給{area:99}的{npc:770}，在北部環線上",
		["only if you carry a {item:3853} (a blacksmith's craft)"] = "只有在你帶著{item:3853}（鐵匠製作）時",
		["with the spices from Theramore"] = "帶著從塞拉摩買來的香料",
		["{area:702} flight master"] = "{area:702}飛行管理員",
		["{item:3713}, for \"Swamp Eye\" Jarl"] = "{item:3713}，給「沼澤之眼」加爾",
		["{npc:1141} cooks in the {object:2169}; {npc:5384} is in the {object:28027}."] = "{npc:1141}在{object:2169}烹飪；{npc:5384}在{object:28027}。",
		["{npc:1261}: other colours, 20g"] = "{npc:1261}：其他顏色，20金",
		["{npc:1440}, the Royal Library in {object:2117}"] = "{npc:1440}，在{object:2117}的皇家圖書館",
		["{npc:217412}: {quest:93176}, from 30-40/05-arathi-highlands"] = "{npc:217412}：{quest:93176}，來自30-40級的阿拉希高地指南",
		["{npc:2487}, top floor"] = "{npc:2487}，頂樓",
		["{npc:2498}'s next Zanzil errand starts in {zone:1441}: skip it."] = "{npc:2498}的下一個贊吉爾任務從{zone:1441}開始：跳過。",
		["{npc:2535} and {npc:2536}"] = "{npc:2535}與{npc:2536}",
		["{npc:2624} swims off the north-west coast, on the northern loop"] = "{npc:2624}在西北海岸外游動，在北部環線上",
		["{npc:2888} camps by himself in {area:1898}, south-east of the digsite."] = "{npc:2888}獨自在挖掘場東南方的{area:1898}紮營。",
		["{npc:384}: other colours, 20g"] = "{npc:384}：其他顏色，20金",
		["{npc:461}, in the {object:2164}: {npc:6251} in {area:392} takes it at the end of the next guide"] = "{npc:461}，在{object:2164}：由{area:392}的{npc:6251}在下一份指南結尾接收",
		["{npc:4730}: other colours, 20g"] = "{npc:4730}：其他顏色，20金",
		["{npc:4966} holds the tower with a few deserters. He turns on you: beat him until he yields.\nCareful: Hendel has two guards who join the fight when he turns hostile. The guards flee once he surrenders.\n{npc:4967} and {npc:4968} wait beside the tower: once he yields, hand in to both on the spot."] = "{npc:4966}和幾個逃兵佔據著塔樓。他會攻擊你：把他打到投降為止。\n小心：亨德爾有兩名衛兵，會在他轉為敵對時加入戰鬥。他投降後衛兵就會逃走。\n{npc:4967}和{npc:4968}在塔旁等候：他投降後，當場向兩人交付任務。",
		["{npc:4967}, at the tower"] = "{npc:4967}，在塔旁",
		["{npc:5637} is in the Reclaimers' hall by the {object:32356}, {npc:2786} in the {object:32383}."] = "{npc:5637}在{object:32356}旁的尋物公司大廳裡，{npc:2786}在{object:32383}。",
		["{npc:6171}, in the Cathedral of Light"] = "{npc:6171}，在光明大教堂裡",
		["{npc:6236} offers The Windwatcher next (1791): the Whirlwind weapon chain, with an elite at the end, is in the Warrior class guide Whirlwind Weapon."] = "{npc:6236}接著會提供捕風者（1791）：旋風斬武器任務線的最後有一個精英，收錄在戰士職業指南「旋風斬武器」中。",
		["{npc:773}: for {quest:2864} in {zone:1446}, keep it"] = "{npc:773}：給{zone:1446}的{quest:2864}，保留此任務",
		["{npc:7955}: other colours, 20g"] = "{npc:7955}：其他顏色，20金",
		["{quest:1260} stands near the inn; {npc:4897}, a trade supplier a few steps south, sells the spices Jarl wants."] = "{quest:1260}站在旅店附近；往南幾步的商業用品供應商{npc:4897}販售加爾要的香料。",
		["{quest:706}: its {item:4612} is a rare drop, so the work and hand-in are optional too"] = "{quest:706}：它的{item:4612}是稀有掉落，所以收集和繳交也都是可選的",
		["{zone:1453} has no shaman trainer"] = "{zone:1453}沒有薩滿訓練師",
} end)()
t.guides["forever/alliance/40-50/02-badlands"] = (function() return {
		["Fly to {area:150}"] = "飛往{area:150}",
		["Fly to {area:271}"] = "飛往{area:271}",
		["Raleigh's next errand is in the {area:796}: skip it."] = "虔誠的萊雷恩的下一個差事在{area:796}：跳過它。",
		["Ride back east to {area:1898}."] = "向東騎回{area:1898}。",
		["Ride back north to Ironband's camp."] = "向北騎回鐵環挖掘場的營地。",
		["Ride north-east out of {area:271} on the road into the {zone:1425}; {area:348} sits just past the border. {npc:5635} holds court at the top, {quest:1450} tends the aviary and {npc:7884} stands by the inn."] = "沿道路從{area:271}往東北騎進{zone:1425}；{area:348}就在邊界後方。{npc:5635}在頂層主持，{quest:1450}照料獅鷲棲所，{npc:7884}站在旅店旁。",
		["Talonaxe's next task waits for a later {zone:1425} guide."] = "沙拉克·鷹斧的下一個任務留到之後的{zone:1425}指南。",
		["The Scalding Whelps nest in the ravine east of {npc:2888}; leave the Scorched Guardians (elite) alone. The {item:4612} drops rarely: take it if it comes while you grind."] = "滾燙的雛龍在{npc:2888}東邊的峽谷中築巢；別惹烈焰守護者（精英）。{item:4612}很少掉落：刷怪時掉了就拿著。",
		["The first two cages stand together in the Witherbark village south of {npc:5634}; the third is in the next village to the east. Every Witherbark troll can drop a necklace.\nCareful: {npc:270772} (49) and his Hexed Larvae (45) keep to the huts of the western village, around 25,64: take the necklaces from the trolls outside."] = "前兩個籠子一起放在{npc:5634}南邊的枯木村落；第三個在東邊的下一個村落。每隻枯木食人妖都可能掉落項鍊。\n小心：{npc:270772}（49級）和他的妖術幼蟲（45級）待在西邊村落的小屋附近，約在25,64：從外面的食人妖身上拿項鍊。",
		["The {area:1517} dig"] = "{area:1517}挖掘場",
		["Theramore"] = "塞拉摩島",
		["Theramore flight master"] = "塞拉摩飛行管理員",
		["Warlock: {quest:3631}"] = "術士：{quest:3631}",
		["Witherbark villages"] = "枯木食人妖村落",
		["{area:144} flight master"] = "{area:144}飛行管理員",
		["{npc:2616} stands on the docks where the boat lands."] = "{npc:2616}站在船靠岸的碼頭上。",
		["{npc:2817}'s next quest pays no experience: skip it."] = "{npc:2817}的下一個任務不給經驗值：跳過它。",
		["{npc:2817}: Blue Pearls from Stranglethorn"] = "{npc:2817}：來自荊棘谷的藍珍珠",
		["{npc:2888}'s next task is an elite hunt: skip it."] = "{npc:2888}的下一個任務是精英狩獵：跳過它。",
		["{npc:2944} does not stay at {area:342}: he walks a long loop around the {zone:1418} with his guards, from the camp in the west along the south of the zone to about 61,69, north to about 49,49 and back west to the camp. The arrow follows his loop west from here until you meet him."] = "{npc:2944}不會待在{area:342}：他會帶著護衛在{zone:1418}繞一大圈巡邏，從西邊的營地沿著區域南部走到約61,69，再向北到約49,49，然後向西回到營地。箭頭會從這裡沿著他的路線向西指引，直到你遇到他。",
		["{npc:5634} camps on the road east of {area:348}."] = "{npc:5634}在{area:348}東邊的路上紮營。",
		["{npc:5636}, beside the flight master at the top; inside"] = "{npc:5636}，在頂層的飛行管理員旁邊；在裡面",
} end)()
t.guides["forever/alliance/40-50/03-feralas"] = (function() return {
		["Back to the {area:1117}. Every Hatecrest naga there can drop scales."] = "回到{area:1117}。那裡的每個憎世納迦都可能掉落鱗片。",
		["Careful: {npc:222286}, an elite of level 43, stands at the camp's north-east edge, around 67,39: pull the Naturalists, Raiders and Shamans away from her."] = "小心：{npc:222286}，43級精英，站在營地東北邊，約67,39：把博學者、襲擊者和薩滿從她身邊拉開。",
		["From {area:489} ride west along the road to the Grimtotem camp north of it. {npc:7956} waits outside it; free the Sprite Darters from the pen in the middle and keep {npc:7956} and at least six of them alive."] = "從{area:489}沿道路向西騎，前往北邊的恐怖圖騰營地。{npc:7956}在營地外等候；放出中央圍欄裡的小精龍，保護{npc:7956}和至少六隻小精龍存活。",
		["Gordunni ogres"] = "戈杜尼巨魔",
		["Grimtotem camp"] = "恐怖圖騰營地",
		["Grimtotem tauren"] = "恐怖圖騰牛頭人",
		["Grind to 45"] = "練到45級",
		["Hatecrest naga"] = "憎世納迦",
		["Ride back to the {area:1108}; the goblin stands by the dock."] = "騎回{area:1108}；那個哥布林站在碼頭旁。",
		["Ride east to the Gordunni camp in the hills south-east of the yeti valley: Warlocks and Shaman hold the camp, Brutes wander the slopes around it and further north."] = "向東騎往雪人山谷東南方山丘上的戈杜尼營地：戈杜尼術士和薩滿佔據營地，戈杜尼蠻兵在周圍和更北邊的山坡上遊蕩。",
		["Ride north into the yeti valley. Every Feral Scar yeti can drop a thick hide; {npc:5346} (level 48) prowls the middle."] = "向北騎進雪人山谷。每隻深痕雪人都可能掉落厚毛皮；{npc:5346}（48級）在中央徘徊。",
		["Ride north-east to the night elf outpost on the {zone:1441} border."] = "向東北騎往{zone:1441}邊界上的夜精靈前哨站。",
		["Ride south-east to the Woodpaw gnolls; the courier's backpacks lie in their southern camp, and a parcel inside them starts a delivery to {area:489}. The Zukk'ash hive is just south: fight down to the pod that holds Raschal, free him and keep him alive on the way out."] = "向東南騎往木爪豺狼人處；信使的背包在他們南邊的營地裡，裡面的一個包裹會開始一個送往{area:489}的任務。祖卡什蟲巢就在南邊：一路殺到關著拉斯卡爾的繭，救出他並在離開途中保護他存活。",
		["Shore Striders, Deep Striders and Wave Striders (elite giants) wade along the coast north of the dock: zap one with {item:18904} and kill the shrunken giant. Sea Elementals and Sea Sprays drift in the same surf."] = "海岸巨人、深海巨人和波濤巨人（精英巨人）在碼頭北邊的海岸涉水：用{item:18904}電擊一隻，然後殺死縮小後的巨人。海元素和巨型海元素在同一片浪中漂浮。",
		["Take the boat to the {area:1108} and follow the shore south to the wrecked row boat on the beach."] = "搭船前往{area:1108}，沿著海岸向南走到海灘上失事的划艇。",
		["The courier's boat"] = "信使的船",
		["The {area:1121} is the island just south of {area:1120}: swim over. Hatecrest Serpent Guards and Sorceresses hold it; {npc:8136} (level 47) waits in the cave at its south end. Pull his guards first."] = "{area:1121}是{area:1120}南邊不遠的小島：游過去。憎世毒蛇守衛和憎世巫師佔據那裡；{npc:8136}（47級）在南端的洞穴裡等著。先拉他的守衛。",
		["The {zone:1446} guide starts with the trip east, past {area:489}."] = "{zone:1446}指南從向東的行程開始，途經{area:489}。",
		["Walk south along the island to the naga ruins; the gazebo stands among them."] = "沿著島嶼向南走到納迦遺跡；涼亭就在遺跡之間。",
		["for Tyrande in {zone:1457}: the route takes you there at 47"] = "給{zone:1457}的泰蘭妲：路線會在47級時帶你去那裡",
		["grind on {npc:5292} at {area:1105}, {zone:1444}"] = "在{zone:1444}的{area:1105}擊殺{npc:5292}練等",
		["{item:11463}, from the backpacks"] = "{item:11463}，來自背包",
		["{npc:14637}'s refills are level 55: skip them."] = "{npc:14637}的補充任務是55級：跳過。",
		["{npc:3936} then asks you to carry news to {zone:1457}: skip it, {area:976} sends you there instead."] = "{npc:3936}接著會要你把消息帶到{zone:1457}：跳過，{area:976}會改派你去那裡。",
		["{npc:3936}, beside him"] = "{npc:3936}，在他旁邊",
		["{npc:7764}: his answer waits in {area:702}, later"] = "{npc:7764}：他的回覆稍後在{area:702}等你",
		["{npc:7877}, at the top of the stronghold"] = "{npc:7877}，在要塞頂端",
		["{npc:8136} waits for the end of the mainland loop."] = "{npc:8136}留到大陸環線結束時再打。",
} end)()
t.guides["forever/alliance/40-50/04-tanaris"] = (function() return {
		["Boat to {area:150}"] = "搭船前往{area:150}",
		["Class trainer"] = "職業訓練師",
		["Fly to {area:271}"] = "飛往{area:271}",
		["Fly to {area:442}"] = "飛往{area:442}",
		["Follow the coast south to the pirate cove. Southsea pirates crowd the beach and the boats: work along the edge and pull one at a time. {npc:7883} stands on the far side; {npc:7881}'s stolen cargo lies in the camp.\nCareful: Two or three pirates stand with {npc:7883}, and many more pirates from the town join the fight once it starts."] = "沿著海岸向南前往海盜灣。南海海盜擠滿了海灘和船隻：沿著邊緣推進，一次拉一隻。{npc:7883}站在另一頭；{npc:7881}被偷的貨物在營地裡。\n小心：{npc:7883}身邊站著兩三個海盜，戰鬥一開始，城裡還會有更多海盜加入。",
		["For your {area:978} run, later in this guide: {quest:2864} wants scarab shells, {npc:7407}, by the water tower, his {quest:2768} back, and Trenton Lighthammer Troll Temper from the Sandfury trolls."] = "為了你稍後在本指南中的{area:978}之行：{quest:2864}要聖甲蟲殼，水塔旁的{npc:7407}要拿回他的{quest:2768}，特倫頓·輕錘要沙怒食人妖身上的食人妖回火劑。",
		["Gives the {item:8585}"] = "會給你{item:8585}",
		["No flight path to {area:348} yet: ride north-east out of {area:271} on the road into the {zone:1425}; {area:348} sits just past the border."] = "還沒有{area:348}的飛行路線：沿道路從{area:271}向東北騎進{zone:1425}；{area:348}就在邊界過去不遠。",
		["Pool by {area:979}"] = "{area:979}旁的水池",
		["Portal to {zone:1438}"] = "前往{zone:1438}的傳送門",
		["Ride back west toward {area:976}. The Wastewander bandits and thieves hold the dunes on the way; any of them can carry a water pouch.\nCareful: Wastewander Rogues (level 43-44) move stealthed, so they can approach unseen."] = "向西騎回{area:976}。廢土強盜和廢土竊賊佔據沿途的沙丘；他們都可能帶著水袋。\n小心：廢土遊蕩者（43-44級）會潛行移動，可能在你沒察覺時接近。",
		["Ride east across the dunes to the goblin harbour on the north-east coast."] = "向東騎過沙丘，前往東北海岸的哥布林港口。",
		["Ride north-west to the Sandfury troll camp at {area:979}. Use the {item:8584} at the edge of its pool; the trolls stand close, so pull the nearest first."] = "向西北騎往{area:979}的沙怒食人妖營地。在水池邊緣使用{item:8584}；食人妖站得很近，先拉最近的。",
		["Ride south into {quest:3362}. The Dew Collectors drop the glands; only some are full, so keep the Laden one. Gnarled Thistleshrubs and Rootshapers share the valley. The Thistleshrubs are 48-50, above you: pull one at a time.\nCareful: The other thistleshrub mobs in the area are level 49-50 and wander a lot, so you can easily pull extra mobs."] = "向南騎進{quest:3362}。灌木露水收集者會掉落腺體；只有一部分是飽滿的，所以保留飽滿的露水腺。長瘤的灌木獸和灌木塑根者也在山谷裡。灌木獸是48-50級，比你高：一次拉一隻。\n小心：這一帶其他的灌木怪是49-50級，而且到處遊蕩，很容易多拉到怪。",
		["Ride south past the {area:1938} to the {area:981}, the Hazzali tunnels; Scrimshank's gear lies deep inside.\nCareful: One bug guards the gear. Many bugs patrol the tunnels, some of them level 50, so fights often pull extra adds."] = "向南騎過{area:1938}前往{area:981}，也就是哈札里的隧道；謝申克的設備在深處。\n小心：有一隻蟲子守著設備。許多蟲子在隧道裡巡邏，有些是50級，所以戰鬥常常會引來額外的怪。",
		["Ride south to the dig camp at the {area:1938}. {npc:7771} hands you a detector helm: wear it to see the {quest:3161} mounds, which lie thick in the sand around the camp and south-west toward the ogres."] = "向南騎往{area:1938}的挖掘營地。{npc:7771}會給你一頂探測頭盔：戴上它就能看見{quest:3161}土堆，它們密集分布在營地周圍的沙地上，以及往西南方巨魔那邊。",
		["Ride south-east off the {area:439} into {zone:1446}. {area:976} is just inside the border."] = "向東南騎離{area:439}進入{zone:1446}。{area:976}就在邊界內側。",
		["Ride south-west to the ogre compound. Brutes and Enforcers (46-48) fill it; {npc:12046} (49) stands in the middle with guards around him: clear them first.\nWhy the grind to 47: the {quest:3362} comes next, with mobs of 48-50 and quests of level 50. Grind it on the Dunemaul Ogres (45-46) at the compound's south end, the safer camp, not on the Brutes."] = "向西南騎往巨魔營地。裡面滿是砂槌蠻兵和砂槌執行者（46-48級）；{npc:12046}（49級）站在中央，周圍有守衛：先清掉守衛。\n為什麼要刷到47級：接下來是{quest:3362}，那裡的怪是48-50級，任務是50級。在營地南端較安全的營地刷砂槌巨魔（45-46級），不要刷砂槌蠻兵。",
		["Step through the portal into {zone:1457}. The Temple of the Moon is in the south of the city."] = "穿過傳送門進入{zone:1457}。月神殿在城市南部。",
		["Take the boat from {area:442}'s dock to {area:702}; {npc:3838}, the hippogryph master, stands on the rise just east of the landing: learn the flight path on the way up to the village."] = "從{area:442}的碼頭搭船前往{area:702}；角鷹獸管理員{npc:3838}站在碼頭東邊不遠的坡上：上坡前往村莊的路上學會飛行路線。",
		["Temple of the Moon"] = "月神殿",
		["The Wanted poster beside him"] = "他旁邊的通緝告示",
		["The little turtle {npc:5955} hides at the north end of the valley. Lead him home to his wife {npc:6015}, by the water just east of {area:977}: he walks slowly and the desert's beasts go for him, so keep him alive."] = "小烏龜{npc:5955}躲在山谷北端。帶他回家找他的妻子{npc:6015}，她在{area:977}東邊的水邊：他走得很慢，沙漠的野獸會攻擊他，所以要保住他的性命。",
		["The pool by {area:979}"] = "{area:979}旁的水池",
		["The same poster: {npc:7847} comes much later, after {area:976}"] = "同一張告示：{npc:7847}要很久以後才會出現，在{area:976}之後",
		["The tougher Wastewander rogues, shadow mages and assassins camp south-east of {area:976}, south of the bandits. Leave {npc:7847} in the middle of the southern camp for later.\nCareful: Wastewander Rogues keep Sneak up while out of combat, so hidden rogues can join a fight you start at a camp."] = "更強的廢土遊蕩者、廢土暗法師和廢土刺客在{area:976}東南方、強盜的南邊紮營。南方營地中央的{npc:7847}留到之後再處理。\n小心：廢土遊蕩者在戰鬥外會一直保持潛行，所以你在營地開打時，隱藏的遊蕩者可能會加入。",
		["The {area:1938}"] = "{area:1938}",
		["The {area:2240} lies on the {area:439} in south-east {zone:1441}: {npc:4454} is in the gnomes' camp beside the track, Zamek by the goblin camp."] = "{area:2240}位於{zone:1441}東南部的{area:439}：{npc:4454}在賽道旁的地精營地內，札米克在哥布林營地旁。",
		["The {quest:2768}: {npc:7407}, by the water tower."] = "{quest:2768}：{npc:7407}，在水塔旁。",
		["The {quest:3042}: {npc:7804}, in town."] = "{quest:3042}：{npc:7804}，在城裡。",
		["Underwater"] = "在水下",
		["Your {area:978} scarab shells: {npc:7876}, on the north side of town."] = "你{area:978}的聖甲蟲殼：{npc:7876}，在城鎮北側。",
		["for {zone:1457}, next"] = "給{zone:1457}，接下來",
		["grind on {npc:5471}, at the compound's south end"] = "刷{npc:5471}，在營地南端",
		["the book on her table"] = "她桌上的書",
		["the soil comes from {zone:1449}, later"] = "土壤來自{zone:1449}，稍後",
		["{area:702} flight master"] = "{area:702}飛行管理員",
		["{area:976} flight master"] = "{area:976}飛行管理員",
		["{area:978} is a dungeon for a group of five; its quests here are level 45 to 47. Its gate lies about 400 yards north of the pool.\nInside: the Scarabs drop the shells, every Sandfury troll can drop {quest:3042}, and {npc:7604} carries the {quest:2768}."] = "{area:978}是五人地城；這裡的相關任務是45到47級。它的大門在水池北邊約400碼處。\n裡面：聖甲蟲會掉落甲殼，每個沙怒食人妖都可能掉落{quest:3042}，{npc:7604}身上帶著{quest:2768}。",
		["{npc:3516}, at the top of the tree"] = "{npc:3516}，在樹頂",
		["{npc:5955}'s escort"] = "護送{npc:5955}",
		["{npc:7407}, by the water tower"] = "{npc:7407}，在水塔旁",
		["{npc:7408}, next to him"] = "{npc:7408}，在他旁邊",
		["{npc:7740}, beside her"] = "{npc:7740}，在她旁邊",
		["{npc:7763}: his crate goes to {area:702}, later"] = "{npc:7763}：他的箱子要送到{area:702}，稍後",
		["{npc:7881}, in the port's tavern; inside"] = "{npc:7881}，在港口的旅店裡；在裡面",
		["{npc:7907} stands upstairs, above {npc:7916}: go up inside, the arrow cannot tell the floors apart."] = "{npc:7907}站在樓上，在{npc:7916}上方：從裡面走上去，箭頭無法分辨樓層。",
		["{npc:7907}'s next errand goes to {zone:1446}: skip it."] = "{npc:7907}的下一個差事要去{zone:1446}：跳過它。",
		["{npc:7916}: the feathers lie in the {zone:1425}, next"] = "{npc:7916}：羽毛在{zone:1425}，接下來",
		["{quest:2768}: {npc:7604}, inside"] = "{quest:2768}：{npc:7604}，在裡面",
		["{quest:2864}, north side of town"] = "{quest:2864}，在城鎮北側",
		["{quest:2865}: the Scarabs, inside"] = "{quest:2865}：聖甲蟲，在裡面",
		["{quest:3042}: the Sandfury trolls, inside"] = "{quest:3042}：沙怒食人妖，在裡面",
		["{zone:1457} first, while you are on this side of the sea: Troyas' answer, {npc:7763}'s crate, Tyrande and the soil errand, then the boat from {area:442} to {area:150} and the gryphon to {area:348}."] = "趁你還在海的這一側，先去{zone:1457}：特洛亞斯的回覆、{npc:7763}的箱子、泰蘭妲和土壤的差事，然後從{area:442}搭船到{area:150}，再搭獅鷲前往{area:348}。",
} end)()
t.guides["forever/alliance/40-50/05-the-hinterlands"] = (function() return {
		["Class trainer"] = "職業訓練師",
		["Fly to {area:1537}"] = "飛往{area:1537}",
		["Fly to {area:35}"] = "飛往{area:35}",
		["Fly to {area:42}"] = "飛往{area:42}",
		["Ride north to {area:351} in the middle of the {zone:1425}. Green Sludges and Jade Oozes crawl all around it.\nCareful: Panthers move around the area in stealth."] = "向北騎到{zone:1425}中部的{area:351}。綠色淤泥怪和玉石軟泥怪在周圍到處爬行。\n小心：這一帶有豹子潛行走動。",
		["Ride on east along the road to the keep first: the {item:6091} expires an hour after {area:42}, and the bloodmages' beasts take longer than that."] = "先沿道路繼續向東前往要塞：{item:6091}在離開{area:42}一小時後過期，而血法師要的野獸會花更久。",
		["Ride south-east to the {area:355}, the stepped Vilebranch temple in the south of the {zone:1425}, and climb to the top. Qiaga and {npc:8636} (elite, 50) stand up there: touch the top and come straight back down.\nCareful: Elite trolls guard the top platform, including {npc:7996} and {npc:8636}, along with several Vilebranch Soothsayers. The soothsayers cast spells and are linked to the rest of the group."] = "向東南騎到{zone:1425}南部的{area:355}（邪枝食人妖的階梯神廟），爬到頂端。守護者奇爾加和{npc:8636}（精英，50級）站在上面：碰到頂端就立刻下來。\n小心：頂層平台由精英食人妖守衛，包括{npc:7996}和{npc:8636}，還有幾名邪枝預言者。預言者會施法，而且與其他成員連動。",
		["The Bloodsail captains"] = "血帆船長",
		["The bloodmages"] = "血法師",
		["The bloodmages' second tier pays for the same parts with a buff item and no experience: skip it."] = "血法師的第二階段用增益物品換取同樣的材料，不給經驗值：跳過它。",
		["Tram to {zone:1453}"] = "搭地鐵前往{zone:1453}",
		["Wildkin feathers"] = "梟獸羽毛",
		["for {quest:2990} at {area:1438}, later"] = "之後給{area:1438}的{quest:2990}",
		["{area:1537} inn"] = "{area:1537}旅店",
		["{npc:2487}, top floor"] = "{npc:2487}，頂樓",
		["{npc:7916}'s Wildkin Feathers lie on the ground across the {zone:1425}, south and east of {area:348}, where the owlbeasts roam: pick them up as you ride between the altar and {area:351}."] = "{npc:7916}要的梟獸羽毛散落在{zone:1425}各處的地上，在{area:348}的南邊和東邊，也就是梟獸遊蕩的地方：在祭壇和{area:351}之間騎行時順手撿起來。",
		["{npc:8022}' next task, {item:9471}, is a {area:978} quest: skip it."] = "{npc:8022}的下一個任務{item:9471}是{area:978}的任務：跳過它。",
		["{quest:2990}, at the top of the keep"] = "{quest:2990}，在要塞頂端",
} end)()
t.guides["forever/alliance/40-50/06-searing-gorge"] = (function() return {
		["Below ground"] = "地下",
		["Carry the {object:149047} south along the rim of the Cauldron and light the four Sentry Braziers, from the south-west round to the south-east."] = "帶著{object:149047}沿大熔爐邊緣向南走，從西南方繞到東南方，點燃四座哨兵火盆。",
		["Class trainer"] = "職業訓練師",
		["Dorius stands by the road beside the {area:247}. Escort him north-east to {area:1959} and keep him alive; when it is over, read the {object:175704} he leaves on the road."] = "杜里奧斯站在{area:247}旁的道路邊。護送他向東北前往{area:1959}，並讓他活著；結束後，閱讀他留在道路上的{object:175704}。",
		["Fly to {area:144}"] = "飛往{area:144}",
		["Fly to {area:1537}"] = "飛往{area:1537}",
		["For {npc:8256} in {zone:1455}, at the end of this guide"] = "在本指南的最後，交給{zone:1455}的{npc:8256}",
		["Four rune rubbings in {zone:1447}: keep it"] = "{zone:1447}的四份符文拓印：留著它",
		["From {area:144} ride south into the {zone:1418}, then west past the Horde town of {area:340} (give it room) and up the trail into {zone:1427}: the {area:247} is just inside, in the south-east. The prisoner in the wooden outhouse wants 15 {item:4306} and eight dead Dark Iron Geologists from the dig site around it. The outhouse also opens with the key, if you found one."] = "從{area:144}向南騎進{zone:1418}，然後向西經過部落城鎮{area:340}（離它遠一點），再沿小徑上到{zone:1427}：{area:247}就在入口內的東南方。木製廁所裡的囚犯要15塊{item:4306}，以及擊殺周圍挖掘場的八名黑鐵地質學家。如果你找到了鑰匙，也能用它打開廁所。",
		["Golems and elementals"] = "傀儡與元素",
		["Ride west along the north of the Gorge to {area:1446}, the scaffolded camp on the north-west rim."] = "沿著峽谷北側向西騎往{area:1446}，也就是西北邊緣搭著鷹架的營地。",
		["Searing Lava Spiders"] = "巨型熔岩蜘蛛",
		["Sentry Braziers"] = "哨兵火盆",
		["Taskmasters and Slavers drive the slaves all over the Cauldron, and any of them can carry a {item:10551}. The Steamsmiths work at the furnaces in the middle (the {item:18959}), the Lookouts stand on the southern ridges (the Spyglass). Any {object:147516} may drop the {item:11818}: keep it.\nCareful: Dark Iron Slavers (level 45-46) call for help from allies within 15 yd when pulled, cast Net from up to 15 yd, and use Rend in melee."] = "黑鐵工頭和黑鐵奴隸販子在大熔爐各處驅趕奴隸，任何一個都可能帶著{item:10551}。黑鐵鍛造師在中央的熔爐工作（{item:18959}），黑鐵哨兵站在南邊的山脊上（偵查員的望遠鏡）。任何{object:147516}都可能掉落{item:11818}：留著它。\n小心：黑鐵奴隸販子（45-46級）被拉時會向15碼內的同伴求援，會在15碼內施放網，近戰時會使用撕裂。",
		["The Grimesilt outhouse"] = "煤渣挖掘場的庫房",
		["The prisoner's next task, Ledger from {zone:1446}, sends you to the {zone:1435} and {zone:1445}: skip it."] = "囚犯的下一個任務「{zone:1446}的帳本」會派你去{zone:1435}和{zone:1445}：跳過它。",
		["The {object:149502} it gives holds a {item:10575}: keep it for {npc:9459} in the {zone:1428}"] = "它給你的{object:149502}裡有一個{item:10575}：留著它，之後交給{zone:1428}的{npc:9459}",
		["The {object:179827} board"] = "{object:179827}告示板",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:8436} stands inside the Twilight camp at {area:1442}, west of {area:1446}, among Twilight Fire Guards, Idolaters and Geomancers (level 48-49 elites), with {npc:8282} (level 51, rare elite) beside him: {quest:3377} needs a group of 4. Skip it if you are alone."] = "這些是精英怪物：建議組隊，找人一起完成。{npc:8436}站在{area:1446}西邊{area:1442}的暮光營地裡，周圍是暮光火焰衛士、暮光崇拜者和暮光地占師（48-49級精英），旁邊還有{npc:8282}（51級稀有精英）：{quest:3377}需要4人隊伍。如果你是獨自一人就跳過。",
		["To {zone:1455}"] = "前往{zone:1455}",
		["Xiggs waits in the {object:32359}."] = "希克斯在{object:32359}等你。",
		["{area:1443} opens in the north of the Cauldron. The Secret Plans lie on its upper ledge; Incendosaurs swim in the lava pools further in, so pull them to the edge. Stay clear of {npc:14621} and his elite guards deep inside."] = "{area:1443}的入口在大熔爐北部。秘密設計圖：熾熱助熔劑在上層平台；燻火龍在更深處的熔岩池中游動，把牠們拉到邊緣。遠離深處的{npc:14621}和他的精英守衛。",
		["{area:1446} flight master"] = "{area:1446}飛行管理員",
		["{npc:9616}: the oozes are in {zone:1448}, keep it"] = "{npc:9616}：軟泥怪在{zone:1448}，留著它",
		["{quest:3462}: hand it in on the way back to {area:1446}"] = "{quest:3462}：在返回{area:1446}的路上交付",
		["{zone:1455} flight master"] = "{zone:1455}飛行管理員",
} end)()
t.guides["forever/alliance/40-50/07-un-goro-crater"] = (function() return {
		["Below ground"] = "地下",
		["Bones and equipment"] = "骨頭與裝備",
		["Dinosaur Bones lie on the ground in the south-west, among the stegodons: those are elite, pick the bones up around them and take the rest from Diemetradons. The expedition's {item:11112} lies in the south-west jungle."] = "恐龍骨頭散落在西南部的劍龍群中：劍龍是精英，在牠們周圍撿骨頭，其餘的從雙帆龍身上取得。探險隊的{item:11112}在西南部叢林。",
		["Eastern Pylon"] = "東部水晶塔",
		["Ends with {npc:9298} in {zone:1452}: keep it"] = "在{zone:1452}的{npc:9298}處完成：保留此任務",
		["Fly to {area:150}"] = "飛往{area:150}",
		["Fly to {area:976}"] = "飛往{area:976}",
		["For characters of 49 to 50, but most quests here are level 51-53: on purpose, for their experience. The crater's beasts are 48-55 and the Gorishi silithids 51-54, so pull them one at a time."] = "適合49到50級的角色，但這裡的大多數任務是51-53級：這是刻意安排的，為了它們的經驗值。環形山的野獸為48-55級，格里什異種蟲為51-54級，所以一次拉一隻。",
		["For {npc:7775} in {zone:1444}: keep it"] = "交給{zone:1444}的{npc:7775}：保留此任務",
		["Lar'korwi Mates and the raft"] = "拉克維的配偶與木筏",
		["Northern Pylon"] = "北部水晶塔",
		["Pterrordax"] = "翼手龍",
		["Ride east to {area:1943}, where the robot stands among the gorillas. Stay out of the deep cave there."] = "向東騎往{area:1943}，機器人站在猩猩群中。不要進入那裡的深洞。",
		["Ride north along the western jungle back to the refuge."] = "沿西部叢林向北騎回避難營。",
		["Ride south down the east side. Young Diemetradons graze the eastern jungle and {npc:9165} fly near the eastern cliffs; both drop {npc:9998}'s scales. The crate sits at the abandoned camp in the eastern jungle."] = "沿東側向南騎。幼雙帆龍在東部叢林覓食，{npc:9165}在東面懸崖附近飛行；兩者都會掉落{npc:9998}要的鱗片。箱子在東部叢林的廢棄營地裡。",
		["Ride south to {area:537} in the middle of the crater, then east into the eastern jungle. Crystal clusters stand all over the crater, many of them around {area:537}: take a few extra of each colour. Bloodpetal Lashers and Threshers drop the petals; the expedition's {item:11113} sits at an abandoned camp in the eastern jungle."] = "向南騎往環形山中央的{area:537}，然後向東進入東部叢林。水晶簇遍布整個環形山，許多在{area:537}周圍：每種顏色多拿幾個。血瓣花鞭笞者和血瓣花猛擊者會掉落花瓣；探險隊的{item:11113}在東部叢林中一處廢棄的營地裡。",
		["Ride west back to the refuge.\nGive the elite devilsaurs and stegodons a wide berth. Pick up every {npc:271301} and {object:157936} you pass from here on."] = "向西騎回避難營。\n遠離精英魔暴龍和劍龍。從現在起，拾取沿途經過的每一個{npc:271301}和{object:157936}。",
		["Ride west out of {area:976} to the long ramp down into {zone:1449}. {npc:9619} camps at the foot of the ramp, in the south-east corner of the crater."] = "從{area:976}向西出發，前往通往{zone:1449}的長坡道。{npc:9619}在坡道底部紮營，位於環形山東南角。",
		["Still short of level 49.79 after the refuge's hand-ins? Top up on the Pterrordax on the slopes east of {area:541} before you leave the crater."] = "交完避難營的任務後仍不到49.79級？離開火山口前，先在{area:541}東邊山坡上的翼手龍身上練一下。",
		["The Gorishi hive"] = "格里什蟲巢",
		["The Lar'korwi Mates prowl the jungle west of {npc:9619}. The wrecked raft lies on the shore of the lake there; the small pack sits in the water beside it. Keep the compass, map and key for {npc:8737}. Any beast in the crater may drop {item:11116}: right-click it."] = "拉克維的配偶在{npc:9619}西邊的叢林中徘徊。破碎的木筏在那裡的湖岸上；小包就在旁邊的水裡。把指南針、地圖和鑰匙留給{npc:8737}。環形山的任何野獸都可能掉落{item:11116}：右鍵點擊它。",
		["The dead Threshadon lies by the water north of {npc:9619}."] = "死去的蛇頸龍躺在{npc:9619}北邊的水邊。",
		["The gorillas on {area:1943} carry the pelts: keep it for the second Un'Goro visit, around 56"] = "{area:1943}的猩猩身上帶有毛皮：保留此任務，留待第二次來安戈洛時（約56級）完成",
		["The pylon stands on the eastern cliffs."] = "水晶塔位於東面懸崖上。",
		["The pylon stands on the slope east of the refuge. Pterrordax circle the slopes around it: they count for Spraggle and drop {npc:9998}'s scales."] = "水晶塔位於避難營東邊的山坡上。翼手龍在周圍山坡盤旋：擊殺牠們算入斯普拉格的任務，並會掉落{npc:9998}要的鱗片。",
		["The pylon stands on the western cliffs. {npc:9167} fly over the whole west side."] = "水晶塔位於西面懸崖上。{npc:9167}在整個西側上空飛行。",
		["The {zone:1455} quests were taken at the end of the {zone:1427} guide: fly straight on to {zone:1440} for {zone:1447}."] = "{zone:1455}的任務已在{zone:1427}指南結尾接取：直接飛往{zone:1440}，前往{zone:1447}。",
		["Theramore flight master"] = "塞拉摩飛行管理員",
		["To {zone:1455}"] = "前往{zone:1455}",
		["Western Pylon"] = "西部水晶塔",
		["{area:537} and the eastern jungle"] = "{area:537}與東部叢林",
		["{area:541} flight master"] = "{area:541}飛行管理員",
		["{npc:11406}: for Ogtinc in {zone:1447}, keep it"] = "{npc:11406}：交給{zone:1447}的奧汀克，保留此任務",
		["{npc:8737}, at the back of the refuge"] = "{npc:8737}，在避難營深處",
		["{npc:9117}, at the back of the cave; below ground"] = "{npc:9117}，在洞穴深處；在地下",
		["{npc:9618} stands just outside the refuge."] = "{npc:9618}就站在避難營外。",
		["{npc:9998}, at the refuge entrance"] = "{npc:9998}，在避難營入口",
		["{npc:9998}, at the refuge's entrance"] = "{npc:9998}，在避難營入口",
} end)()
t.guides["forever/alliance/50-60/01-burning-steppes"] = (function() return {
		["Archesonus stands beside King Magni in the {object:171709}."] = "阿克瑟努斯站在{object:171709}的國王麥格尼身旁。",
		["Archesonus stands beside King Magni in the {object:171709}: the relics you read in the Steppes are his."] = "阿克瑟努斯站在{object:171709}的國王麥格尼身旁：你在燃燒平原閱讀的聖物就是他要的。",
		["Ardalan is inside {area:1438}."] = "阿達藍在{area:1438}裡面。",
		["Below ground"] = "地下",
		["Climb to the top of {area:249} and plant the head in the soft dirt mound."] = "爬上{area:249}頂端，把頭顱插在鬆軟的土堆上。",
		["Ends with {quest:4808} in {area:2255}, {zone:1452}: keep it"] = "在{zone:1452}的{area:2255}交給{quest:4808}：保留此任務",
		["Fly to {area:1438}"] = "飛往{area:1438}",
		["Fly to {area:144}"] = "飛往{area:144}",
		["Fly to {area:150}"] = "飛往{area:150}",
		["Fly to {area:1537}"] = "飛往{area:1537}",
		["Fly to {area:271}"] = "飛往{area:271}",
		["Fly to {area:69}"] = "飛往{area:69}",
		["Follow the road west, then climb north to the goblin camp on {area:251}."] = "沿著道路向西走，然後向北爬上{area:251}的哥布林營地。",
		["For {zone:1453}: keep it"] = "給{zone:1453}：保留此任務",
		["Hearth back to {zone:1455}'s inn."] = "用爐石回到{zone:1455}的旅店。",
		["Listen to his tale, then ride back south to Kum'isha."] = "聽完他的故事，然後向南騎回庫米莎那裡。",
		["Mosshoof Coursers"] = "苔蹄快步者",
		["Open the {item:10569} from {zone:1427} for its {item:10575}, then tell {npc:9459} you bring proof of your deeds: no drake to fight."] = "打開來自{zone:1427}的{item:10569}取得{item:10575}，然後告訴{npc:9459}你帶來了功績的證明：不必與飛龍戰鬥。",
		["Portal to {zone:1438}"] = "傳送門前往{zone:1438}",
		["Ride back east along the road to the Vigil."] = "沿著道路向東騎回摩根的崗哨。",
		["Ride back south to the camp."] = "向南騎回營地。",
		["Ride east out of {area:69} and up the pass into the {zone:1428}: {area:2418} stands at the top."] = "向東騎出{area:69}，沿山口上行進入{zone:1428}：{area:2418}就在頂端。",
		["Ride north out of the {zone:1419} into the {zone:1435}: the {npc:10996} stands by the road from the {zone:1419}. Keep clear of {area:75}, the Horde town to the north-east."] = "向北騎出{zone:1419}進入{zone:1435}：{npc:10996}站在從{zone:1419}過來的道路旁。遠離東北方的部落城鎮{area:75}。",
		["Ride north-east from the shrine: {npc:8405} camps at the {area:1224}, in the hills above the road."] = "從神殿向東北騎：{npc:8405}在{area:1224}紮營，位於道路上方的山丘上。",
		["Swim to the small island off the southern tip of {zone:1447}. If {npc:8392} isn't there, fire your {item:10444} to signal him, and wait for him to land."] = "游到{zone:1447}南端外海的小島。如果{npc:8392}不在那裡，發射你的{item:10444}向他發出信號，然後等他降落。",
		["The Firegut ogres hold the great rock north of the Vigil, with the Brutes on its east side.\nCareful: Escaped Core Hounds (level 60) roam the Steppes, a few on the slopes west and south of {area:249}: pull the ogres on the rock itself and look around before each pull."] = "火腹巨魔佔據摩根的崗哨北邊的巨石，火腹蠻兵在它的東側。\n小心：逃脫的熔火惡犬（60級）在燃燒平原遊蕩，有幾隻在{area:249}西邊和南邊的山坡上：就在巨石上拉巨魔，每次拉怪前先看看四周。",
		["The Highborne ghosts haunt the ruins around the shrine; the Haldarr satyrs hold the camp just north of it."] = "精靈貴族的鬼魂在神殿周圍的遺跡中出沒；哈達爾薩特佔據神殿北邊不遠處的營地。",
		["The Spitelash naga of the {area:1221} carry {item:13815}. {npc:8507}'s four runes stand among the ruins: use his {item:10445} on each."] = "{area:1221}的惡鞭納迦身上帶著{item:13815}。{npc:8507}的四塊符文石立在遺跡之間：對每一塊使用他的{item:10445}。",
		["The nearest Mosshoof Coursers graze the hills north-east of the {area:1224}, toward the {area:1219}; a larger herd roams the open ground to the south."] = "最近的苔蹄快步者在{area:1224}東北方、往{area:1219}方向的山丘上覓食；更大的一群在南邊的空地上遊蕩。",
		["The portal in {area:702} leads up to {zone:1457}: {npc:9047} waits in the {area:1658}, in the north of the city."] = "{area:702}的傳送門通往上方的{zone:1457}：{npc:9047}在城市北邊的{area:1658}等候。",
		["The relics are in the {zone:1428}: keep it"] = "聖物在{zone:1428}：保留此任務",
		["The shrine lies in the south-west corner of {zone:1447}, south of {area:3137}."] = "神殿位於{zone:1447}西南角，在{area:3137}南邊。",
		["The wildkin are in {zone:1452}: keep it"] = "梟獸在{zone:1452}：保留此任務",
		["The {area:1221}"] = "{area:1221}",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:7977} (level 48 elite) needs a group of 2. Skip it if you are alone: the route has you grind the XP back.\n{npc:7977} walks the {zone:1425} shore below the {area:307}, from the arrow south to about 75,66 and north to about 82,52: if she isn't at the arrow, follow the shore."] = "這些是精英怪物：建議組隊，找人一起完成。{npc:7977}（48級精英）需要2人隊伍。如果你是單獨一人就跳過：路線會讓你練級把經驗值補回來。\n{npc:7977}在{area:307}下方的{zone:1425}海岸上走動，從箭頭處往南到約75,66，往北到約82,52：如果她不在箭頭處，就沿著海岸找。",
		["To {zone:1455}"] = "前往{zone:1455}",
		["Upstairs"] = "樓上",
		["Your Hearthstone is set at {zone:1455} (the {zone:1425} guide binds it there): hearth back to the inn."] = "你的爐石設定在{zone:1455}（{zone:1425}指南會綁定在那裡）：用爐石回到旅店。",
		["{area:144} flight master"] = "{area:144}飛行管理員",
		["{area:199} cauldron"] = "{area:199}的瘟疫之鍋",
		["{item:10575}, from the hoard"] = "{item:10575}，從寶藏中取得",
		["{item:7972}: the {npc:7864}, about 10%"] = "{item:7972}：{npc:7864}，約10%",
		["{npc:10778}'s ghost wanders by the farmhouse of {area:199}, west of {area:200}; her parcel lies inside."] = "{npc:10778}的鬼魂在{area:200}西邊{area:199}的農舍旁徘徊；她的包裹就在屋裡。",
		["{npc:11075} guards the cauldron in {area:199}, west of Andorhal."] = "{npc:11075}守護著安多哈爾西邊{area:199}的瘟疫之鍋。",
		["{npc:7907} stands upstairs, above {npc:7916}: go up inside, the arrow cannot tell the floors apart."] = "{npc:7907}站在樓上，在{npc:7916}上方：從裡面走上去，箭頭無法分辨樓層。",
		["{npc:8395} wants two Undamaged Hippogryph Feathers from the Thunderhead hippogryphs around his camp, the ones you top up on here: about one in three carries one."] = "{npc:8395}要兩根完整的角鷹獸羽毛，從他營地周圍的雷首角鷹獸身上取得，也就是你在這裡練級的那些：大約每三隻有一隻會帶著一根。",
		["{npc:8420} camps at the {area:1219} in the north; his equipment lies all over the {area:1220} just south-east of him."] = "{npc:8420}在北邊的{area:1219}紮營；他的裝備散落在他東南方不遠處的{area:1220}各處。",
		["{npc:9047}, in the {area:1658}"] = "{npc:9047}，在{area:1658}",
		["{npc:9176} and the Blackrock orcs hold the camps and the stronghold at the foot of {area:254}, west of {area:251}. Pull them one at a time; every orc and worg may drop a medallion, so kill them until you have fifty.\nCareful: {npc:9176} has a guard linked to him that joins the fight, and a second soldier patrols close by; clear the patrol before pulling.\nCareful: Firesworn, level 60 fire elementals, wander the Steppes, some between the Blackrock camps: look before each pull and let them pass."] = "{npc:9176}和黑石獸人佔據{area:251}西邊、{area:254}山腳下的營地和要塞。一次拉一隻；每個獸人和座狼都可能掉落徽章，所以一直殺到你有五十個為止。\n小心：{npc:9176}身邊有一名連動的守衛會一起參戰，附近還有第二名士兵在巡邏；拉怪前先清掉巡邏的士兵。\n小心：火誓者（60級火元素）在燃燒平原遊蕩，有些在黑石營地之間：每次拉怪前先看看，讓牠們走過去。",
		["{npc:9177}: the Blackrock orcs drop the medallions, keep it open all through the Steppes"] = "{npc:9177}：黑石獸人會掉落徽章，在整個燃燒平原期間保持此任務進行中",
		["{zone:1455} has no druid trainer"] = "{zone:1455}沒有德魯伊訓練師",
		["{zone:1455} inn"] = "{zone:1455}旅店",
} end)()
t.guides["forever/alliance/50-60/02-felwood"] = (function() return {
		["Below ground"] = "地下",
		["Ends in the {zone:1413}: keep it"] = "在{zone:1413}完成：保留此任務",
		["First crater"] = "第一個坑洞",
		["Follow the road north to the cratered vale and walk to each crater, killing the Entropic Beasts and Horrors between them."] = "沿著道路向北前往坑窪山谷，走到每個坑洞，並擊殺途中的熱能野獸和熱能恐獸。",
		["Ride north up the road from the Sanctuary, all the way to the cave mouth of {area:1769}; {npc:15395} guards it."] = "從聖地沿著道路向北騎，一路到{area:1769}的洞口；{npc:15395}守在那裡。",
		["Salfa stands at the {zone:1452} end of the tunnel: keep it"] = "薩爾法站在隧道的{zone:1452}那一端：保留此任務",
		["Second crater"] = "第二個坑洞",
		["Step into the cave: {npc:11558} stands just inside."] = "走進洞穴：{npc:11558}就站在入口內。",
		["Still short of level 52.9 after the {area:2479}'s hand-ins? Top up on the Entropic Beasts in {area:1766}, the next stop north."] = "交完{area:2479}的任務後仍不到52.9級？在北邊下一站{area:1766}的熱能野獸身上練一下。",
		["The Deadwood furbolgs live in the village just south-west of {npc:11554}; keep the Deadwood Headdress Feathers they drop."] = "死木熊怪住在{npc:11554}西南方的村莊裡；保留牠們掉落的死木頭飾羽毛。",
		["The Warpwood treants of {area:1767}, east of {area:2618}, carry the {item:11503}."] = "{area:2618}東邊{area:1767}的曲木樹人帶著{item:11503}。",
		["The vial is filled in {zone:1457}: keep it; inside"] = "瓶子在{zone:1457}裝滿：保留此任務；在裡面",
		["The {area:2479}"] = "{area:2479}",
		["Third crater"] = "第三個坑洞",
		["{area:1763} again"] = "再次前往{area:1763}",
		["{area:2618} is the satyr valley in the north-west, with {npc:10648} at its far end. He drops the {quest:939}; every Jadefire satyr can drop {item:11674}."] = "{area:2618}是西北方的薩特山谷，{npc:10648}在山谷盡頭。他會掉落{quest:939}；每個碧火薩特都可能掉落{item:11674}。",
		["{area:702} flight master"] = "{area:702}飛行管理員",
		["{npc:10924}: for {npc:11079} in {zone:1452}, keep it"] = "{npc:10924}：給{zone:1452}的{npc:11079}，先留著",
		["{npc:11554} the furbolg stands by the road just south of the {area:2479}."] = "熊怪{npc:11554}站在{area:2479}南邊的路旁。",
		["{npc:11558}: the Timbermaw speak to you only from Neutral; walks around here: look inside the circle on the map"] = "{npc:11558}：木喉熊怪只有在中立以上才會和你說話；會在這附近走動：在地圖上的圓圈內找他",
		["{npc:15395} waits at the north end of {zone:1448}"] = "{npc:15395}在{zone:1448}北端等候",
		["{npc:9528}, in the ruins just east of {npc:11554}"] = "{npc:9528}，在{npc:11554}東邊的廢墟裡",
} end)()
t.guides["forever/alliance/50-60/03-winterspring"] = (function() return {
		["Back to the hills: only the Ice Thistle Matriarchs and Patriarchs carry the horns."] = "回到山丘：只有冰薊雪人女王和冰薊雪人王身上帶著角。",
		["Boat to {area:150}"] = "搭船前往{area:150}",
		["Fly to Theramore"] = "飛往塞拉摩",
		["Fly to {area:3197}"] = "飛往{area:3197}",
		["Follow the road east across the zone to the chapel."] = "沿著道路向東穿過本區前往禮拜堂。",
		["Follow the road west to {npc:9298}'s camp beside the hot springs."] = "沿著道路向西前往溫泉旁{npc:9298}的營地。",
		["Follow the southern road east into the {zone:1423}; the ruins of {area:2262} lie south of it. {npc:10926}'s ghost plays by the ruined house at the south end."] = "沿著南邊的道路向東進入{zone:1423}；{area:2262}的廢墟在道路南邊。{npc:10926}的鬼魂在南端的廢屋旁玩耍。",
		["For Kernda in {area:1769}: keep it"] = "給{area:1769}的克爾達：保留此任務",
		["Free Darrowshire Spirits: talk to them"] = "解放達隆郡居民的靈魂：與他們交談",
		["Ice Thistle yetis live in the hills south of {area:2244}, Chillwind Chimaeras in the valley toward {area:2255}."] = "冰薊雪人住在{area:2244}南邊的山丘上，冰風奇美拉在往{area:2255}方向的山谷裡。",
		["Keep it: Gregan in {zone:1444} brews the elixir later"] = "保留此任務：{zone:1444}的格雷甘稍後會調製藥劑",
		["On {npc:10978}, by the inn"] = "在旅店旁的{npc:10978}處",
		["Pristine Yeti Horns"] = "完美的雪人角",
		["Pureheart, Dumah, Valorfist and MacDonnell stand around the middle of the camp, by the flight master."] = "純心、杜瑪、瓦洛菲斯特和麥克唐奈站在營地中央附近，飛行管理員旁邊。",
		["Scare {npc:10978} with {item:12928}"] = "用{item:12928}嚇唬{npc:10978}",
		["The Deadwood cauldron in {zone:1448}: keep it"] = "{zone:1448}的死木大鍋：保留此任務",
		["The Scourge around {area:2264}, west of the chapel, drop both kinds of Scourgestone; Darrowshire Spirits rise from them: talk to each one to free it.\nCareful: {npc:10411} goes invisible when out of combat and calls Rockwing Gargoyles once a fight starts. Only 3 exist and they respawn every 15 min."] = "禮拜堂西邊{area:2264}周圍的天譴軍會掉落兩種天譴石；達隆郡居民的靈魂會從牠們身上升起：與每一個交談以解放它。\n小心：{npc:10411}在戰鬥外會隱形，戰鬥一開始就會召來岩翼石像鬼。牠們只有3隻，每15分鐘重生一次。",
		["The Winterfall furbolg village lies east of {area:2255}: Shaman (56-57), Den Watchers (55-56) and Ursa (57-58), all above you. Kill the Shaman first, they heal, and pull from the edge. {npc:10738} in the cave at the back is elite: stay out."] = "冬泉熊怪的村莊位於{area:2255}東邊：冬泉薩滿（56-57級）、冬泉巢穴守衛（55-56級）和冬泉巨熊怪（57-58級），都比你高。先殺薩滿，他們會治療，並從邊緣開始拉。後方洞穴裡的{npc:10738}是精英：不要進去。",
		["The next guide starts here and flies to {area:3197}."] = "下一份指南從這裡開始，然後飛往{area:3197}。",
		["The ruins lie around the frozen lake south of {area:2253}. Pick up the four relic fragments lying in the ruins and the Moontouched Feathers on the ground where the wildkin roam."] = "遺跡位於{area:2253}南邊結冰湖泊的周圍。拾取散落在遺跡中的四塊遺物碎片，以及梟獸遊蕩處地上的月光羽毛。",
		["The three pieces of the doll lie in the ruined houses of {area:2262}; picking one up can call out ghosts. Combine them into the doll."] = "洋娃娃的三個部分在{area:2262}的廢屋裡；撿起其中一個可能會引出鬼魂。把它們組合成洋娃娃。",
		["To {zone:1455}"] = "前往{zone:1455}",
		["Your Hearthstone is not set at {zone:1455} (the {zone:1425} guide binds there at 47, and this guide leaves {zone:1452} through it): bind at {area:2255} instead, for the trips back to town."] = "你的爐石沒有設定在{zone:1455}（{zone:1425}指南在47級時於那裡綁定，而本指南會透過爐石離開{zone:1452}）：改為綁定在{area:2255}，方便往返城鎮。",
		["Your Hearthstone is still set at {zone:1455}: from there the gryphon to {area:3197} is about ten minutes quicker than {area:2255}'s flight to Theramore and the boat."] = "你的爐石仍設定在{zone:1455}：從那裡搭乘獅鷲飛往{area:3197}，比從{area:2255}飛往塞拉摩再搭船快大約十分鐘。",
		["Zaeldarr is elite: grouping up is advised. He waits at the bottom of the {area:2261}, the crypt in the south-west of the zone."] = "塞達爾是精英：建議組隊。他在本區西南部的地穴{area:2261}最底層等著。",
		["{area:2255}'s inn"] = "{area:2255}的旅店",
		["{npc:10431}: keep both for the Plaguelands; inside"] = "{npc:10431}：兩個都保留給瘟疫之地；在裡面",
		["{npc:10926}'s doll"] = "{npc:10926}的洋娃娃",
		["{npc:10978}: {npc:7583} and {npc:10977} come later"] = "{npc:10978}：{npc:7583}和{npc:10977}稍後再找",
		["{npc:11038}: Zaeldarr is a level 54 elite"] = "{npc:11038}：薩爾達爾是54級精英",
		["{npc:11556} stands right at the {zone:1452} exit of {area:1769}'s tunnel, where you come out."] = "{npc:11556}就站在{area:1769}隧道的{zone:1452}出口，也就是你出來的地方。",
		["{npc:11616}: the termites come later, in {area:2627}"] = "{npc:11616}：白蟻稍後在{area:2627}處理",
		["{npc:11629}: keep it for {area:2262}; inside"] = "{npc:11629}：保留給{area:2262}；在裡面",
		["{quest:5152}, in the {zone:1422}: keep it"] = "{zone:1422}的{quest:5152}：保留此任務",
		["{zone:1455} flight master"] = "{zone:1455}的飛行管理員",
		["{zone:1455} inn"] = "{zone:1455}旅店",
} end)()
t.guides["forever/alliance/50-60/04-western-plaguelands"] = (function() return {
		["After the farm's keys: the {object:177289} stands just south-west of the farmhouse, and its Cauldron Lord beside it carries the key."] = "拿到農場的鑰匙之後：{object:177289}就在農舍西南邊不遠處，旁邊的護鍋者身上帶著鑰匙。",
		["Andorhal"] = "安多哈爾",
		["Back to {npc:7775}'s camp, just south-east of {npc:7765}: the {item:11242} buys three Videre Elixirs. Keep them: {npc:9298} takes one, and {npc:9299} in {area:976} shows himself only to someone who has drunk one."] = "回到{npc:7765}東南邊不遠的{npc:7775}營地：{item:11242}可換三瓶維迪爾藥劑。留著它們：{npc:9298}要一瓶，而{area:976}的{npc:9299}只會現身給喝過藥劑的人看。",
		["Below ground"] = "地下",
		["Cross the river east to the {area:2261}, the crypt in the south-west of the zone. The {object:177667} lies inside: its key is on {npc:12248} in the far north-east, done in the next guide.\nCareful: About four non-elite adds come with Mercutio. They walk to the grave instead of appearing on the spot."] = "向東渡河前往{area:2261}，也就是本區西南部的地穴。{object:177667}就在裡面：它的鑰匙在遠處東北方的{npc:12248}身上，在下一份指南完成。\n小心：米庫提奧會帶來大約四隻非精英的幫手。牠們是走到墳墓那裡，而不是當場出現。",
		["Cross the river west to {npc:1855}'s hut."] = "向西渡河前往{npc:1855}的小屋。",
		["Cross the south of the crater to {npc:9619} by the ramp."] = "穿越環形山南部，前往坡道旁的{npc:9619}。",
		["Diseased Grizzlies"] = "生病的灰熊",
		["Dredge Crushers dig further west; Stonelash Pincers, Flayers and Rock Stalkers hunt the same sands."] = "掘泥摧毀者在更西邊挖掘；石鞭巨鉗蠍、石鞭掠奪者和石行蜘蛛在同一片沙地上狩獵。",
		["Dredge Strikers dig in the dunes north-west of the hold; Stonelash Scorpids and Sand Skitterers roam all around."] = "掘泥打擊者在要塞西北方的沙丘中挖掘；石鞭蠍和掠沙蜘蛛在四周遊蕩。",
		["Ends with {npc:9298} in {zone:1452}: keep it"] = "在{zone:1452}的{npc:9298}處完成：保留此任務",
		["Escort {npc:9999}"] = "護送{npc:9999}",
		["Fly from {area:976} to {area:541}. {npc:8737} stands at the back of the refuge; {npc:9117} is in the cave behind him.\n{npc:9997}'s friend {npc:9999} has gone missing."] = "從{area:976}飛往{area:541}。{npc:8737}站在避難所後方；{npc:9117}在他身後的洞穴裡。\n{npc:9997}的朋友{npc:9999}失蹤了。",
		["Fly to Theramore"] = "飛往塞拉摩",
		["Fly to {area:2268}"] = "飛往{area:2268}",
		["Fly to {area:271}"] = "飛往{area:271}",
		["Fly to {area:392}"] = "飛往{area:392}",
