		["Goblin Woodcarvers, inside"] = "哥布林木匠，副本內",
		["The Alliance paladin's rare two-handed mace for the 20s, with a shield and {spell:5502} on the way."] = "聯盟聖騎士20多級的稀有雙手錘，途中還能拿到一面盾牌和{spell:5502}。",
		["The {item:6995}"] = "{item:6995}",
		["The {item:7083}"] = "{item:7083}",
		["{area:1581} is a group of five under {area:20}; the instance portal is at the bottom of the {area:20} mine. The Goblin Woodcarvers (elite, level 18-19) in the mast room with Sneed drop the lumber every time."] = "{area:1581}是位於{area:20}地底的五人副本；副本傳送門在{area:20}礦坑底部。桅杆室裡與斯尼德在一起的哥布林木匠（精英，18-19級）每次都會掉落木材。",
		["{area:1581}, in the {area:20} mine"] = "{area:1581}，在{area:20}礦坑內",
