		["{npc:6181} works outside the gates of {zone:1455}, not inside. He gives you {item:6996}: four parts, in any order. Keep the notes."] = "{npc:6181}在{zone:1455}大門外工作，不是在城內。他會給你{item:6996}：四個部件，順序不限。留著這些筆記。",
		["{npc:6241} turns the ore into {item:6993}, the part Jordan wants."] = "{npc:6241}會把礦石做成{item:6993}，也就是喬丹要的部件。",
