		["Deathcharger"] = "死亡戰騎",
		["Journeyman {skill:762}"] = "中級{skill:762}",
		["Stratholme {object:175461}"] = "斯坦索姆{object:175461}",
		["{area:2279} is a group of five, level 58-60. The {object:175461} at {object:175440}, in north-western {zone:1423}, leads to the undead side; {npc:10440} waits in the Slaughter House at its end. Our data gives the reins a 0.02% drop chance (pfQuest, Era): one in about five thousand kills. Nothing shows Forever changing it."] = "{area:2279}是五人副本，58-60級。{zone:1423}西北部{object:175440}的{object:175461}通往亡靈區；{npc:10440}在盡頭的屠宰場等著。依我們的資料，韁繩的掉落率為0.02%（pfQuest，Era）：大約每五千次擊殺掉一次。沒有跡象顯示 Forever 更改了它。",
		["{item:13335} needs level 60 and Journeyman {skill:762} to ride (Forever client). Train it at your race's riding trainer; see the Level 60 mount guides."] = "{item:13335}需要60級和中級{skill:762}才能騎乘（Forever 用戶端）。向你種族的騎術訓練師學習；請見60級坐騎指南。",
} end)()
t.guides["forever/collectibles/mounts/neutral/galestrider"] = (function() return {
		["20g"] = "20金",
		["Galestrider"] = "逐風者",
		["Galestriders need level 40 and {skill:762}. Train it at your own race's riding trainer; see the Level 40 mount guides for where."] = "逐風者需要40級和{skill:762}。向你自己種族的騎術訓練師學習；地點請見40級坐騎指南。",
		["Learn to ride"] = "學習騎術",
		["Skyboat from {area:279}"] = "從{area:279}搭乘天空船",
		["Skyboat from {zone:1456}"] = "從{zone:1456}搭乘天空船",
		["Skyboat to {zone:2521}"] = "搭天空船前往{zone:2521}",
		["{npc:265756} is at the {area:17684} in {area:16638}, the island's harbour town, near the skyboat docks. The Forever client lists each Galestrider at 20g; choose one."] = "{npc:265756}在島上的港口城鎮{area:16638}的{area:17684}，靠近天空船碼頭。Forever 用戶端中每隻逐風者標價20金；選一隻。",
		["{zone:2521} is the Skyborne starting island; anyone may visit. A skyboat leaves the cliffs south of {area:17045}, north of {zone:1456}, about every five minutes (another flies from {area:279}; either faction may take either). Skip this if you are already on the island."] = "{zone:2521}是天裔精靈的起始島嶼；任何人都可以前往。天空船約每五分鐘從{zone:1456}北邊、{area:17045}南側的懸崖出發（另一艘從{area:279}起飛；兩個陣營都可搭乘任一艘）。如果你已在島上，跳過此步。",
		["{zone:2521} is the Skyborne starting island; anyone may visit. A skyboat leaves the north side of {area:279} about every five minutes (another flies from north of {zone:1456}; either faction may take either). Skip this if you are already on the island."] = "{zone:2521}是天裔精靈的起始島嶼；任何人都可以前往。天空船約每五分鐘從{area:279}北側出發（另一艘從{zone:1456}北邊起飛；兩個陣營都可搭乘任一艘）。如果你已在島上，跳過此步。",
} end)()
t.guides["forever/collectibles/mounts/neutral/spectral-bear"] = (function() return {
		["55 Legacy Points"] = "55傳承點數",
		["Journeyman {skill:762}"] = "中級{skill:762}",
		["Legacy Points are account-wide: each Legacy Challenge (a class reaching 25, 45 and 60, professions, PvP, exploring) is worth one, and every point the account earns counts here, spent or not. The Legacy Challenges guide plans them. The Progress Track gives the {item:281060} at 15, the {npc:268840} at 25, the {item:277717} at 40 and the reins at 55. Claim each one from {npc:6791} at the inn in {area:392}, on the {zone:1413} coast: he offers a \"Legacy Reward\" quest once you have the points."] = "傳承點數為帳號共用：每項傳承挑戰（職業達到25、45和60級、專業、PvP、探索）值1點，帳號獲得的每一點都算在這裡，不論是否已花掉。傳承挑戰指南會為它們做規劃。進度軌道在15點給{item:281060}，25點給{npc:268840}，40點給{item:277717}，55點給韁繩。每一項都要向{zone:1413}海岸{area:392}旅店的{npc:6791}領取：你的點數夠了之後，他會提供「傳承獎勵」任務。",
		["The bear runs at full speed: riding it needs level 60 and Journeyman {skill:762} (Forever client), from your race's riding trainer; see the Level 60 mount guides."] = "這頭熊以全速奔跑：騎乘需要60級和中級{skill:762}（Forever 用戶端），向你種族的騎術訓練師學習；請見60級坐騎指南。",
} end)()
