		["{zone:1448} is north of {zone:1440}."] = "{zone:1448}在{zone:1440}北邊。",
		["{zone:1451} is west of {zone:1449}, through the pass in its north-west. {area:3425} is neutral."] = "{zone:1451}在{zone:1449}西邊，穿過它西北部的山口。{area:3425}是中立的。",
		["{zone:2482} is reached from {zone:1452} through {area:2256} in the south. It is Forever's endgame leveling zone."] = "從{zone:1452}經由南部的{area:2256}前往{zone:2482}。這是Forever的終局升級區域。",
} end)()
t.guides["forever/exploration/zephras-isle"] = (function() return {
		["Exploration: {zone:2521}"] = "探索：{zone:2521}",
		["Skyborne start here. Everyone else takes a skyboat, about every five minutes; either faction may take either one."] = "天裔精靈從這裡開始。其他人搭乘天空船，約每五分鐘一班；兩個陣營都可搭乘任一艘。",
		["The skyboat leaves the cliffs south of {area:17045}, north of {zone:1456} (another flies from {area:279})."] = "天空船從{zone:1456}北邊、{area:17045}南側的懸崖出發（另一艘從{area:279}起飛）。",
		["The skyboat leaves the north side of {area:279} in the {zone:1416} (another flies from north of {zone:1456})."] = "天空船從{zone:1416}的{area:279}北側出發（另一艘從{zone:1456}北邊起飛）。",
		["any one of these names counts"] = "以下任一名稱皆算",
		["{zone:2521} is the Skyborne starting island, a world of its own in {area:17221}; anyone may visit. 20 areas to discover here, levels 3-12."] = "{zone:2521}是天裔精靈的起始島嶼，在{area:17221}自成一個世界；任何人都可以造訪。這裡有20個區域要發現，等級3-12。",
} end)()
t.guides["forever/horde/02-the-barrens"] = (function() return {
		["Assist {npc:261366}: stay by him when {npc:261367} and the {area:21} marines come up the ridge"] = "協助{npc:261366}：{npc:261367}和{area:21}水兵爬上山脊時，待在他身邊",
		["At the {area:2362}"] = "在{area:2362}",
		["Back east over the bridge and up the trail to {npc:5900}'s shrine again. {npc:5900} makes {item:6636} from the tar and pouch. Use it by the brazier next to him to reveal the {npc:5893}, kill it for the {item:6655}, then place the ember in the brazier."] = "向東過橋，再次沿小徑上到{npc:5900}的神殿。{npc:5900}用焦油和袋子製作{item:6636}。在他旁邊的火盆使用它以顯現{npc:5893}，擊殺它取得{item:6655}，然後把餘燼放進火盆。",
		["Back north into {area:378} before the antennae fade: {npc:6394} is inside."] = "在觸角消失前向北回到{area:378}：{npc:6394}在裡面。",
		["Back out of the caverns and up to the cave above the entrance."] = "從洞穴出來，往上走到入口上方的洞穴。",
		["Back to the Razormane camp. Geomancers and Defenders hold its eastern half; {npc:3438} walks among them. Careful: Razormane Flesheaters and Berserkers (18-19) are elites in the camp's north-east, near {npc:3438} and the supply crates, and {npc:267307} (20, elite) lies in the cave under {area:1699} beside them: pull {npc:3438} and the quilboar away from them one at a time, and leave the cave alone unless you are in a group."] = "回到鋼鬃營地。鋼鬃地卜師和鋼鬃防禦者占據營地東半部；{npc:3438}在牠們之間走動。小心：鋼鬃食肉者和狂戰士（18-19級）是精英，位於營地東北部、{npc:3438}和補給箱附近，旁邊{area:1699}下方的洞穴裡還有{npc:267307}（20級，精英）：把{npc:3438}和野豬人一隻一隻地從牠們身邊引開，除非有隊伍，否則別碰那個洞穴。",
		["Bristleback camps"] = "刺背營地",
		["Dogran is chained up in the quilboar camp west of the road."] = "步兵多格蘭被鎖在道路西邊的野豬人營地裡。",
		["Down the {area:458} to {area:378} again."] = "再次沿{area:458}往南前往{area:378}。",
		["East from {npc:261366} toward the {area:382}: {npc:9316} stands at the camp on the road north of the Crossroads."] = "從{npc:261366}向東朝{area:382}走：{npc:9316}站在十字路口北邊道路上的營地。",
		["Fill the {item:7766} at the quilboar watering hole"] = "在野豬人的水源裝滿{item:7766}",
		["Fly from the Crossroads to {area:1638}. {quest:853} waits in the {area:2197}, the cave under {area:1640}: hand in the spores there first, while their time runs. Then {npc:3033} trains you on {area:1639}."] = "從十字路口飛往{area:1638}。{quest:853}在{area:1640}下方的洞穴{area:2197}裡：趁時限還沒到，先去那裡繳交孢子。接著{npc:3033}在{area:1639}為你訓練。",
		["Fly from {zone:1456} straight on to {area:392}."] = "從{zone:1456}直接飛往{area:392}。",
		["Fly to {area:1637}"] = "飛往{area:1637}",
		["Fly to {area:392}"] = "飛往{area:392}",
		["Follow the {area:458} south to {area:378}."] = "沿{area:458}向南前往{area:378}。",
		["For your {area:718} run: {npc:3446}'s next errand, {quest:1491}."] = "為了你的{area:718}之行：{npc:3446}的下一個差事，{quest:1491}。",
		["For your {area:718} run: {npc:5767} and {npc:5768} stand in a hidden cave in the rocks above the entrance, at the north end of the oasis' west shore: climb up from the west side. Follow the arrow up."] = "為了你的{area:718}之行：{npc:5767}和{npc:5768}站在入口上方岩石中的一個隱藏洞穴裡，位於綠洲西岸的北端：從西側爬上去。跟著箭頭往上走。",
		["Grimtotem camp"] = "恐怖圖騰營地",
		["He gives you the {item:15826}"] = "他會給你{item:15826}",
		["He offers {quest:1838} next (1838, level 30): it needs {area:1717} and sends you all over Kalimdor and the Eastern Kingdoms. The Warrior class guide {quest:1838} covers it."] = "他接著提供{quest:1838}（1838，30級）：需要{area:1717}，並會讓你跑遍卡林多和東部王國。戰士職業指南{quest:1838}涵蓋此任務。",
		["In from the north gate: {npc:3464} first, {npc:3338} by the inn, then up to {npc:3449} and {npc:3429} on the tower platform, where the flight master stands."] = "從北門進來：先找{npc:3464}，再找旅店旁的{npc:3338}，然後上到飛行管理員所在的塔樓平台，找{npc:3449}和{npc:3429}。",
		["In the camp, Water Seekers and Thornweavers hold the western half, Hunters the middle; the supply crates sit at its eastern end.\nPlainstriders here count toward the beaks.\nCareful: Razormane Flesheaters and Berserkers (18-19) are elites; they stand in the camp's north-east, beside the supply crates: pull the quilboar away from them one at a time."] = "營地裡，鋼鬃尋水者和鋼鬃織棘者占據西半部，鋼鬃獵手在中間；補給箱在營地東端。\n這裡的陸行鳥也算在鳥喙的數量裡。\n小心：{npc:267308}和狂戰士（18-19級）是精英；牠們站在營地東北部的補給箱旁：把野豬人一隻一隻地從牠們身邊引開。",
		["Keep it: {npc:12696} in {zone:1440}, next guide"] = "先留著：下一份指南中{zone:1440}的{npc:12696}",
		["Kolkar camp"] = "科卡爾半人馬營地",
		["Leave {zone:1454} by the main gate and follow the road south through {zone:1411}, then west over the {area:814} bridge: {npc:5810} stands at {area:379} just above it, on the road to the Crossroads."] = "從大門離開{zone:1454}，沿道路向南穿過{zone:1411}，再向西過{area:814}橋：{npc:5810}站在橋上方不遠的{area:379}，就在前往十字路口的路上。",
		["North to the {area:383}. {npc:3682} camps below the hills; {npc:261366}, the hermit on the ridge behind him, has work for you only once {npc:3682} sends you up."] = "向北前往{area:383}。{npc:3682}在丘陵下紮營；他身後山脊上的隱士{npc:261366}，要等{npc:3682}派你上去後才會有工作給你。",
		["North up the {area:458} to the Crossroads: {npc:3448} at the south gate, {npc:3432} by the inn, {npc:3428} west of the north gate."] = "沿{area:458}往北到十字路口：{npc:3448}在南門，{npc:3432}在旅店旁，{npc:3428}在北門西邊。",
		["North up the {area:458} to the Crossroads: {npc:3448} at the south gate, {npc:3432} by the inn, {npc:3428} west of the north gate. Keep the {item:5075}: {npc:3430} takes it on the next stop in {area:378}."] = "沿{area:458}向北前往十字路口：{npc:3448}在南門，{npc:3432}在旅店旁，{npc:3428}在北門西邊。先留著{item:5075}：下次到{area:378}時交給{npc:3430}。",
		["On the way back down the {area:1076}, {npc:11856} is held in {npc:11858}'s hut at the bend in the road. Once you take her quest she walks straight off south-east to {area:2538}, the burned village, without waiting: stay close, or the quest fails.\nCareful: Three Grimtotems ambush her at the burned village and go for her, not you: pull them off her and kill their caster quickly."] = "沿{area:1076}往回下山時，{npc:11856}被關在道路轉彎處{npc:11858}的小屋裡。接下她的任務後，她會直接往東南走向被燒毀的村莊{area:2538}，不會等你：緊跟著她，否則任務會失敗。\n小心：三個恐怖圖騰成員會在被燒毀的村莊伏擊她，並且攻擊她而不是你：把他們從她身上拉開，並迅速擊殺他們的施法者。",
		["Raptor nests"] = "迅猛龍巢",
		["Razormane camp"] = "鋼鬃營地",
		["South-west from {area:392} across the plains to the {area:1697}: the three nests sit together south-west of the oasis, and Sunscale Scytheclaws guard them. Each nest needs a {item:5165}: kill Sunscale raptors (most drop one) until you have three, then use a feather at each nest."] = "從{area:392}往西南穿過平原前往{area:1697}：三個巢一起位於綠洲西南方，由赤鱗鐮爪龍守護。每個巢都需要一根{item:5165}：擊殺赤鱗迅猛龍（大多會掉落一根）直到你有三根，然後在每個巢使用一根羽毛。",
		["Tauren: the {npc:11957} waits on the southern hill above the bridge. Skyborne: the {npc:272054} stands south of the twin bridges. Then the dens east of the lake: leave your form, click the statue at the entrance for five minutes of stealth, keep clear of the spirits inside and take one of each relic; the {item:280680} lies at the foot of the white cat statue. Careful: the spirits are Territorial Terrans (level 60) that kill whoever they see: stay off their paths, and click the statue again before the stealth runs out."] = "牛頭人：{npc:11957}在橋上方的南邊山丘等著。天裔精靈：{npc:272054}站在雙橋南邊。然後前往湖東邊的獸穴：解除變形，點擊入口的雕像獲得五分鐘的潛行，避開裡面的靈魂，每種聖物各拿一個；{item:280680}在白貓雕像的腳下。小心：這些靈魂是Territorial Terran（60級），看到誰就殺誰：避開牠們的路線，並在潛行結束前再次點擊雕像。",
		["The Venture Co. Overseers and Enforcers at the mine in the north-east corner of the zone drop the {item:5097}."] = "地區東北角礦坑的風險投資公司監工和風險投資公司執行者會掉落{item:5097}。",
		["The pools lie just north of {npc:3389}. Walk into the water to explore them; the Laden Mushrooms for Helbrim grow around them. Kill every Kolkar you pass for bracers. {npc:3394} stands in the Kolkar camp west of the pools."] = "水池就在{npc:3389}北邊不遠。走進水裡探索；要給赫布瑞姆的豐滿的蘑菇長在水池周圍。順路擊殺每一個科卡爾半人馬取得護腕。{npc:3394}站在水池西邊的科卡爾營地裡。",
		["The road climbs north as the {area:1076}. {quest:1483} has a hut where the road forks east to {area:461}."] = "道路以{area:1076}向北爬升。{quest:1483}的小屋在道路向東分岔通往{area:461}的地方。",
		["The tool buckets with the slugs lie around the Venture Co. drill site in the {area:382}."] = "裝著蛞蝓的工具籃在{area:382}的風險投資公司鑽探場周圍。",
		["The {area:2363}"] = "{area:2363}",
		["The {object:172960} is the canyon under the {object:172982}."] = "{object:172960}是{object:172982}下方的峽谷。",
		["The {object:177794} lies at the north edge of the {area:382}, by the Venture Co. tower. It holds the {item:15883} for {quest:30}."] = "{object:177794}在{area:382}北緣，風險投資公司的塔旁。裡面有{quest:30}所需的{item:15883}。",
		["The {object:4141} stands at the Venture Co. research site west of the {area:382}. Close the three valves around the drill, use the console again, then take the {item:5089} from {npc:3471} beside it.\nCareful: Several guards stand within aggro range of the valves, respawn in under about 3 minutes, and run at low health to bring back help; nearby mobs also join if you use a valve while they are close."] = "{object:4141}在{area:382}西邊的風險投資公司研究站。關閉鑽機周圍的三個閥門，再次使用控制台，然後從旁邊的{npc:3471}身上取得{item:5089}。\n小心：有幾名守衛站在閥門的仇恨範圍內，約3分鐘內就會重生，血量低時會逃跑搬救兵；如果你在附近有怪時使用閥門，牠們也會加入。",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:267307} (level 20 elite) needs a group of 3 and sits deep in the cave under {area:1699}, past the Razormane Flesheaters and Berserkers (18-19, elite). Skip it if you are alone."] = "這些是精英怪物：建議組隊，找人一起打。{npc:267307}（20級精英）需要3人隊伍，位於{area:1699}下方的洞穴深處，要先經過鋼鬃食肉者和狂戰士（18-19級，精英）。如果你是獨自一人就跳過。",
		["Thunderhawk Cloudscrapers circle over the plains south of the camp."] = "雷鷹破雲者在營地南邊的平原上空盤旋。",
		["Twitching Antennae"] = "抽動的觸鬚",
		["Twitching Antennae from the silithid"] = "從異種蠍身上取得顫抖的觸角",
		["Underwater"] = "在水下",
		["Upstairs"] = "樓上",
		["West from the burned village to {area:2539}: {npc:12816} stands just outside it, before the village."] = "從被燒毀的村莊往西前往{area:2539}：{npc:12816}就站在村外，在進村之前。",
		["West to {npc:3389}'s watch post on the Kolkar border."] = "向西前往{npc:3389}在科卡爾邊界的哨站。",
		["While you are in the camp: {npc:3429}'s Water Seekers and Thornweavers in its western half, the Hunters in the middle, the supply crates at its eastern end.\nCareful: Razormane Flesheaters and Berserkers (18-19) are elites; they stand in the camp's north-east, beside the supply crates: pull the quilboar away from them one at a time."] = "既然在營地裡：{npc:3429}要的鋼鬃尋水者和鋼鬃織棘者在西半部，鋼鬃獵手在中間，補給箱在營地東端。\n小心：{npc:267308}和狂戰士（18-19級）是精英；牠們站在營地東北部的補給箱旁：把野豬人一隻一隻地從牠們身邊引開。",
		["Your {area:718} quests, if you have not taken them yet: {npc:3446} beside the {object:3972} poster, {npc:3665} on the dock by the flight master. The run is later in this guide, after {npc:3396}."] = "你的{area:718}任務，如果還沒接的話：{npc:3446}在{object:3972}告示旁，{npc:3665}在飛行管理員旁的碼頭上。這趟地城之行在本指南稍後，在{npc:3396}之後。",
		["{area:392}: {area:718} quests"] = "{area:392}：{area:718}任務",
		["{area:718} is a dungeon for a group of five, about levels 17 to 24, and a full run takes about an hour. Its mouth is just north of {npc:3396}'s shore, at the north end of {area:387}, under {npc:5767}'s cave.\nIn the caves before the portal: {npc:3655}, stealthed, with the {item:5334} (he moves between a few spots and comes back slowly: leave him if he's gone). Inside: the Deviates for {npc:5768}, and their hides for {npc:5767} (they drop rarely: one run may not be enough, so leave the rest for another run), {item:6464} from the Ectoplasms. After the four Fanglords, the {npc:3678} at the entrance leads you to Naralex: {npc:3654} drops the {item:10441}: its quest (someone in {area:392}, then {npc:8418} above the caverns) is not on this route; the Dungeons page's hand-in guide takes it."] = "{area:718}是五人地城，約17到24級，完整打一次約需一小時。洞口就在{npc:3396}所在岸邊的北邊，{area:387}北端，{npc:5767}的洞穴下方。\n傳送門前的洞穴裡：潛行中的{npc:3655}帶著{item:5334}（他會在幾個地點之間移動，回來得很慢：如果他不在就別管了）。裡面：給{npc:5768}的變異生物，以及給{npc:5767}的牠們的皮（掉率很低：打一次可能不夠，剩下的留給下一次），{item:6464}則來自軟泥怪。擊敗四位尖牙領主後，入口處的{npc:3678}會帶你去找納拉雷克斯：{npc:3654}會掉落{item:10441}，它的任務（先找{area:392}的某人，再找洞穴上方的{npc:8418}）不在本路線中；由地城頁面的繳交指南處理。",
		["{item:15877}, from a {object:177785} in the lake"] = "{item:15877}，從湖中的{object:177785}取得",
		["{item:2449} from {npc:3490}; herbalists pick it on the plains"] = "向{npc:3490}購買{item:2449}；草藥學家可在平原上採集",
		["{item:6464}: the Ectoplasms"] = "{item:6464}：軟泥怪",
		["{npc:11798} in {area:2361} flies druids there"] = "{area:2361}的{npc:11798}會載德魯伊飛到那裡",
		["{npc:11799}, at the {area:2362}"] = "{npc:11799}，在{area:2362}",
		["{npc:11802}: the welcome from {npc:3033}"] = "{npc:11802}：{npc:3033}的歡迎",
		["{npc:11856}, inside {npc:11858}'s hut"] = "{npc:11856}，在{npc:11858}的小屋裡",
		["{npc:11857}: keep it, {npc:11864} at {area:460} in the {zone:1413} & Stonetalon guide"] = "{npc:11857}：先留著，{zone:1413}與石爪山脈指南中{area:460}的{npc:11864}",
		["{npc:16227}, beside {npc:3442}"] = "{npc:16227}，在{npc:3442}旁邊",
		["{npc:267310} stands on the north-east side of the Crossroads. {quest:97003} is a group quest: {npc:267307} is a level 20 elite boar in the Razormane's {area:1699} cave, east of the town, where the route goes back for {npc:3438} later."] = "{npc:267310}站在十字路口東北側。{quest:97003}是組隊任務：{npc:267307}是20級精英野豬，位於城鎮東邊鋼鬃野豬人的{area:1699}洞穴，路線稍後會回到那裡找{npc:3438}。",
		["{npc:3337}: {quest:840}, from {zone:1411}"] = "{npc:3337}：{quest:840}，來自{zone:1411}",
		["{npc:3338} by the inn first, then Helbrim by the north gate, {npc:3429} and {npc:3449} on the tower platform, {npc:3432} by the inn, and {npc:3448} at the south gate last. His seed test waits for the {npc:3395} pass at the {area:388}: go straight on north-west to the {area:383}. After the spores Helbrim offers {quest:853}, a delivery to {zone:1456} within 45 minutes: this route doesn't go there, so leave it (Druids take it on the next Crossroads stop, right before their flight to {zone:1456})."] = "先找旅店旁的{npc:3338}，接著是北門旁的赫布瑞姆、塔樓平台上的{npc:3429}和{npc:3449}、旅店旁的{npc:3432}，最後是南門的{npc:3448}。他的種子測試要等到去{area:388}找{npc:3395}那一趟再做：現在直接往西北前往{area:383}。繳交孢子後，赫布瑞姆會提供{quest:853}，要在45分鐘內送到{zone:1456}：這條路線不去那裡，所以先不接（德魯伊會在下一次經過十字路口時接取，正好在飛往{zone:1456}之前）。",
		["{npc:3390}: 45 minutes, for Zamah on the {zone:1456} step next"] = "{npc:3390}：限時45分鐘，交給接下來{zone:1456}步驟中的札瑪",
		["{npc:3391}, upstairs"] = "{npc:3391}，在樓上",
		["{npc:3396} leads the Kolkar on the west shore of {area:387}, south of {npc:3389}. He walks that shore, from about 46,36 in the north to 46,42 in the south: if he isn't at the arrow, follow the shore until you meet him. Hand his head to {npc:3389} on your last Crossroads stop. Oasis Snapjaws crawl in the oasis' water there: their shells are for {npc:3448}."] = "{npc:3396}帶領科卡爾盤踞在{npc:3389}南邊的{area:387}西岸。他沿著岸邊走動，北端約46,36，南端約46,42：若箭頭處沒看到他，就沿岸找到他為止。最後一次到十字路口時，把他的頭交給{npc:3389}。綠洲鉗嘴龜在那裡的綠洲水中爬行：牠們的殼是給{npc:3448}的。",
		["{npc:3429}, at the top of the tower"] = "{npc:3429}，在塔頂",
		["{npc:3430}, in the cage"] = "{npc:3430}，在籠子裡",
		["{npc:3432} offers {quest:95774} once {quest:4921} is handed in"] = "繳交{quest:4921}後，{npc:3432}會提供{quest:95774}",
		["{npc:3442} in {area:392}: on the next {area:392} stop"] = "{area:392}的{npc:3442}：下次到{area:392}時",
		["{npc:3442}: the console is in the {area:382}, later"] = "{npc:3442}：控制台之後在{area:382}",
		["{npc:3448}: the Oasis Snapjaws at {area:387}, with {npc:3396} after the {zone:1454} trip"] = "{npc:3448}：{area:387}的綠洲鉗嘴龜，去過{zone:1454}之後和{npc:3396}一起做",
		["{npc:3448}: the bubbling fissure at the {area:388}, on the {npc:3395} pass"] = "{npc:3448}：{area:388}冒泡的裂隙，在去找{npc:3395}的那一趟",
		["{npc:3449}: the harpies come later, in the {area:383}"] = "{npc:3449}：鷹身人之後在{area:383}",
		["{npc:3465} is chained inside the hold. Talk to him to start the escort and stay close: Theramore soldiers attack on the way out. He walks you back to {area:392}."] = "{npc:3465}被鎖在要塞內。和他交談開始護送並緊跟著他：出去的路上塞拉摩士兵會攻擊。他會和你一起走回{area:392}。",
		["{npc:4197} lives in {area:2539}, the troll village just inside Stonetalon at the end of the road west from {npc:3389}."] = "{npc:4197}住在{area:2539}，那是從{npc:3389}往西的道路盡頭、剛進入石爪山脈的食人妖村落。",
		["{npc:4201}, inside"] = "{npc:4201}，在裡面",
		["{npc:4201}: for {npc:3442}, beside {area:392}'s flight master at the end of the {zone:1413} & Stonetalon guide"] = "{npc:4201}：交給{npc:3442}，他在{area:392}的飛行管理員旁，於{zone:1413}與石爪山脈指南的最後",
		["{npc:5767} and {npc:5768}"] = "{npc:5767}和{npc:5768}",
		["{npc:5878} camps beside the road east toward {area:392}."] = "{npc:5878}在往東通往{area:392}的道路旁紮營。",
		["{npc:5901} waits on the hill south of {area:392}, on your way north."] = "{npc:5901}在{area:392}南邊的山丘上等著，就在你往北的路上。",
		["{npc:5907}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:5907}：{npc:2523}、你的{item:5176}和{item:263412}",
		["{npc:5909}, a few steps away"] = "{npc:5909}，就在幾步之外",
		["{npc:6018} stands in the {object:172961} on the city's west side."] = "{npc:6018}站在城市西側的{object:172961}。",
		["{npc:6018} stands in the {object:172961}, on the city's west side."] = "{npc:6018}站在城市西側的{object:172961}。",
		["{npc:6018}: {npc:4606} in the {zone:1458}, two guides on"] = "{npc:6018}：兩份指南後{zone:1458}的{npc:4606}",
		["{object:3972} poster"] = "{object:3972}海報",
		["{quest:1483}, inside"] = "{quest:1483}，在裡面",
		["{quest:1492}, on the dock"] = "{quest:1492}，在碼頭上",
		["{quest:6127}: {area:384}, next guide"] = "{quest:6127}：{area:384}，下一份指南",
		["{quest:809}, beside {npc:3337}: from {npc:3216} in {zone:1454}"] = "{quest:809}，在{npc:3337}旁邊：來自{zone:1454}的{npc:3216}",
		["{quest:853}, in the {area:2197}"] = "{quest:853}，在{area:2197}",
		["{zone:1454} class quests"] = "{zone:1454}的職業任務",
		["{zone:1454} flight master"] = "{zone:1454}的飛行管理員",
} end)()
t.guides["forever/horde/03-silverpine-forest"] = (function() return {
		["Back out through the portal: {npc:3216} stands beside it."] = "從傳送門出來：{npc:3216}就站在旁邊。",
		["Class trainer"] = "職業訓練師",
		["Follow the lake shore south-east from the Yoricks' house: the Vile Fin Shredders and Tidehunters along it drop the murloc eyes."] = "從約里克家沿著湖岸向東南走：沿途的邪鰭切割者和邪鰭潮行者會掉落魚人眼睛。",
		["Follow the road north-east to the Yoricks' house at {area:238}."] = "沿著道路向東北前往{area:238}的尤瑞克家。",
		["Follow the road south. The {object:1627} sits beside it, north of Pyrewood. Careful: Dalaran Apprentices (13) stand around the crate: pull them one at a time before you open it."] = "沿著道路向南走。{object:1627}在路旁，位於焚木村北邊。小心：達拉然學徒（13級）站在箱子周圍：打開之前一次拉一個。",
		["For your {area:2437} run: the {object:172960} is the canyon under the {object:172982}; {npc:3216} stands at its far end, next to the {area:2437} portal."] = "為了你的{area:2437}之行：{object:172960}是{object:172982}下方的峽谷；{npc:3216}站在峽谷盡頭，{area:2437}傳送門旁邊。",
		["Mottled Worgs"] = "雜斑座狼",
		["Mottled Worgs prowl the hills around the house."] = "雜斑座狼在房子周圍的山丘徘徊。",
		["North again to the Yoricks' house."] = "再次向北前往尤瑞克家。",
		["North of the {area:228}. {npc:1983} haunts the {area:240}: kill it, then walk across the field. Careful: {npc:1983} (14) rises once you have killed rot hide gnolls in the field: fight her with full health."] = "在{area:228}北邊。{npc:1983}在{area:240}出沒：殺了它，然後走過整片田地。小心：在田裡殺掉腐皮豺狼人後，{npc:1983}（14級）就會出現：滿血再跟她打。",
		["Speak with {npc:10181}, in the {object:36126}: {quest:93739}"] = "與{object:36126}的{npc:10181}交談：{quest:93739}",
		["Speak with {npc:10540}, in Grommash Hold"] = "與Grommash Hold裡的{npc:10540}交談",
		["Speak with {npc:3230}, in Grommash Hold"] = "與Grommash Hold裡的{npc:3230}交談",
		["Take the road north toward {zone:1420}: the Yoricks' house at {area:238} is on the way. {quest:425} lurks a short walk west of it."] = "沿道路向北朝{zone:1420}走：{area:238}的尤瑞克家就在路上。{quest:425}潛伏在房子西邊不遠處。",
		["The cattails and speargrass grow along the water in the {object:172958}, east of the Drag."] = "香蒲和長矛草沿著the Drag東邊{object:172958}的水邊生長。",
		["The {object:172960} is the canyon under the {object:172982}; {quest:829} stands at its far end."] = "{object:172960}是{object:172982}下方的峽谷；{quest:829}站在峽谷盡頭。",
		["Vile Fin murlocs"] = "邪鰭魚人",
		["Walk in by the main gate. {npc:3310}, the wind rider master, stands on the tower in the {object:172982}; {npc:6929} keeps the inn below it, {npc:268701} stands by the bank. Bind here: the Hearthstone brings you back from {zone:1421} beside the zeppelin towers and the road to the {zone:1413}."] = "從正門走進去。雙足飛龍管理員{npc:3310}站在{object:172982}的塔上；{npc:6929}經營塔下的旅店，{npc:268701}站在銀行旁。在這裡綁定爐石：爐石會把你從{zone:1421}帶回飛艇塔和通往{zone:1413}的道路旁。",
		["Walk in through the main gate. {npc:268701} stands in the {object:172982}."] = "從正門走進去。{npc:268701}站在{object:172982}。",
		["Zeppelin to {zone:1454}"] = "搭飛艇前往{zone:1454}",
		["Zeppelin to {zone:1458}"] = "搭飛艇前往{zone:1458}",
		["{area:159} is a short walk north up the road from the zeppelin towers; {npc:1499} is in the town hall."] = "{area:159}從飛艇塔沿著道路往北走一小段就到；{npc:1499}在市政廳裡。",
		["{area:228} is the Forsaken crypt-town in the middle of the forest. Everyone you need stands around the crypt entrance; {npc:2226}, the bat handler, is just east of it."] = "{area:228}是森林中央的被遺忘者墓穴城鎮。你需要找的人都站在墓穴入口周圍；蝙蝠管理員{npc:2226}就在入口東邊。",
		["{area:2437} is a dungeon for a group of five, about levels 13 to 18, and a full run takes 30 to 45 minutes. Its portal is in the {object:172960}, beside {npc:3216}.\nInside: past Oggleflint and his troggs, {npc:11520} waits in the lava cave and drops his heart. {npc:11518} and Bazzalan, further in, are for {npc:4949}'s Hidden Enemies, which this route leaves out."] = "{area:2437}是五人地城，約13到18級，完整打一次要30到45分鐘。傳送門在{object:172960}，{npc:3216}旁邊。\n裡面：經過歐格弗林特和他的穴居人後，{npc:11520}在熔岩洞穴裡等著，會掉落他的心臟。更深處的{npc:11518}和巴札蘭是{npc:4949}的「隱藏的敵人」任務目標，本路線略過該任務。",
		["{npc:11044}, in the Apothecarium"] = "{npc:11044}，在 Apothecarium",
		["{npc:11046}, the alchemy trainer, stands next door to {npc:3348}."] = "{npc:11046}是煉金術訓練師，站在{npc:3348}隔壁。",
		["{npc:11046}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:11046}：野營入門，來自{zone:1411}布拉克的營火",
		["{npc:11066}, the enchanting trainer, works in the Drag."] = "{npc:11066}是附魔訓練師，在the Drag工作。",
		["{npc:11066}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:11066}：野營入門，來自{zone:1411}布拉克的營火",
		["{npc:1937}: for Quinn, on the road north at the end"] = "{npc:1937}：為了奎恩，最後在北邊的路上",
		["{npc:1952}, below ground"] = "{npc:1952}，在地下",
		["{npc:1978} waits north-east of the house. Escort him back to {npc:1950}; worgs attack on the way."] = "{npc:1978}在房子東北方等候。護送他回到{npc:1950}那裡；途中會有座狼攻擊。",
		["{npc:2226}: {npc:4556} in the {zone:1458}, at the end of this guide; no need to buy the flight"] = "{npc:2226}：{zone:1458}的{npc:4556}，在本指南的最後；不需要購買飛行路線",
		["{npc:246152}, in {area:159}"] = "{npc:246152}，在{area:159}",
		["{npc:268684} and {npc:268682} sit behind Grommash Hold in the {object:172957}; the Smooth Boulders lie around them. The next guide walks from here to {area:379} and the Crossroads."] = "{npc:268684}和{npc:268682}坐在{object:172957}的Grommash Hold後面；光滑巨石就在他們周圍。下一份指南從這裡走到{area:379}和十字路口。",
		["{npc:2855}, the tailoring trainer, is in the {object:172958}."] = "{npc:2855}是裁縫訓練師，在{object:172958}。",
		["{npc:2855}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:2855}：野營入門，來自{zone:1411}布拉克的營火",
		["{npc:3348} and {npc:3347} run the alchemy shop in the Drag; {npc:11046} is next door."] = "{npc:3348}和{npc:3347}在the Drag經營煉金店；{npc:11046}在隔壁。",
		["{npc:3365}, the leatherworking trainer, works in the {object:172958}."] = "{npc:3365}是製皮訓練師，在{object:172958}工作。",
		["{npc:3365}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:3365}：野營入門，來自{zone:1411}布拉克的營火",
		["{npc:3404}, the herbalism trainer, keeps her shop in the Drag."] = "{npc:3404}是草藥學訓練師，她的店在the Drag。",
		["{npc:3404}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:3404}：野營入門，來自{zone:1411}布拉克的營火",
		["{npc:4551}, the bat handler"] = "{npc:4551}，蝙蝠管理員",
		["{npc:4551}: keep {item:16210}, Podrig takes it on the next stop at the {area:228}, at 22"] = "{npc:4551}：保留{item:16210}，22級時在下一站{area:228}交給波崔格",
		["{npc:4556}, the weapon merchant beside the bat handler"] = "{npc:4556}，蝙蝠管理員旁邊的武器商人",
		["{npc:4586}, the engineering trainer, works in the {zone:1458}."] = "{npc:4586}是工程學訓練師，在{zone:1458}工作。",
		["{npc:4586}: Camping 101, from {npc:265812}'s campfire in Tirisfal"] = "{npc:4586}：野營入門，來自提里斯法{npc:265812}的營火",
		["{npc:4598}, the mining trainer, works in the {zone:1458}."] = "{npc:4598}是採礦訓練師，在{zone:1458}工作。",
		["{npc:4598}: Camping 101, from {npc:265812}'s campfire in Tirisfal"] = "{npc:4598}：野營入門，來自提里斯法{npc:265812}的營火",
		["{npc:4605}, the blacksmithing trainer, works in the {zone:1458}."] = "{npc:4605}是鍛造訓練師，在{zone:1458}工作。",
		["{npc:4605}: Camping 101, from {npc:265812}'s campfire in Tirisfal"] = "{npc:4605}：野營入門，來自提里斯法{npc:265812}的營火",
		["{npc:4949}, inside Grommash Hold"] = "{npc:4949}，在Grommash Hold裡",
		["{npc:4949}: keep it, Thork at the Crossroads in the {zone:1413} guide"] = "{npc:4949}：保留此任務，{zone:1413}指南中十字路口的索克",
		["{npc:4949}: {quest:93739}, a tour of the Horde's leaders"] = "{npc:4949}：{quest:93739}，拜訪部落各領袖",
		["{npc:7088}, the skinning trainer, stands in the {object:172958}."] = "{npc:7088}是剝皮訓練師，站在{object:172958}。",
		["{npc:7088}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:7088}：野營入門，來自{zone:1411}布拉克的營火",
		["{quest:264} is handed in at {object:24776}, a grave a few steps south of the crypt entrance, not to a person."] = "{quest:264}要在{object:24776}交，那是墓穴入口南邊幾步遠的一座墳墓，不是交給某個人。",
		["{quest:829}: {quest:809} stands at {area:379}, on the next guide's road to the Crossroads"] = "{quest:829}：{quest:809}站在{area:379}，就在下一份指南前往十字路口的路上",
		["{quest:829}: {quest:832}, from the {item:4903} in {zone:1411}"] = "{quest:829}：{quest:832}，來自{zone:1411}的{item:4903}",
} end)()
t.guides["forever/horde/04-the-barrens"] = (function() return {
		["Bael'dun fortress"] = "巴爾丹要塞",
		["East along the road from {area:2539} to {npc:4049}'s camp."] = "從{area:2539}沿道路向東前往{npc:4049}的營地。",
		["Fly to {area:1638}"] = "飛往{area:1638}",
		["Fly to {area:378}"] = "飛往{area:378}",
		["Fly to {area:378}: {npc:2995} on {zone:1456}'s central rise, or the Crossroads' wind rider master if you start this guide there."] = "飛往{area:378}：{zone:1456}中央高台上的{npc:2995}；若你從十字路口開始本指南，就找十字路口的雙足飛龍管理員。",
		["Fly to {area:392}"] = "飛往{area:392}",
		["Follow the road north toward {area:467}. Antlered Coursers graze along the way; the Sap Beasts, Twilight Runners and Fey Dragons roam the woods below the Peak, and the Cenarion druids hold the grove there."] = "沿著道路向北前往{area:467}。巨角鹿在沿途覓食；腐蝕獸、夜行虎和靈龍在山峰下方的樹林中遊蕩，塞納里奧德魯伊則佔據那裡的樹林。",
		["Follow the road on west past {npc:4049}'s camp into Stonetalon: {npc:3995} waits below ground in {area:2539}, at the foot of the {area:1076}."] = "沿道路繼續向西經過{npc:4049}的營地進入石爪山脈：{npc:3995}在{area:2539}的地底下等著，位於{area:1076}腳下。",
		["Follow the road west past Regthar's bunkers: {npc:4049} camps beside it at the edge of Stonetalon."] = "沿道路向西經過雷戈薩的碉堡：{npc:4049}在石爪山脈邊緣的路旁紮營。",
		["Gaea Dirt Mounds"] = "蓋亞土堆",
		["Gaea Seeds"] = "蓋亞之種",
		["North up the road to {area:378}: your hearthstone takes you there if it is ready."] = "沿道路向北前往{area:378}：如果爐石冷卻好了，可以直接用它回去。",
		["South of Gann, the Bael'dun dwarves dig at {area:359}. Excavators and Foremen work the pit; {npc:3392} (26) carries the journal: pull him alone.\nCareful: Excavators (level 21-22) and Foremen (level 22-23) run off for help once they fall to 15% health, so more dwarves can join the fight."] = "在加恩·石塔南邊，巴爾丹矮人在{area:359}挖掘。巴爾丹挖掘者和巴爾丹工頭在坑中工作；{npc:3392}（26級）身上帶著日誌：單獨把他拉過來。\n小心：挖掘者（21-22級）和工頭（22-23級）血量降到15%時會跑去求援，所以會有更多矮人加入戰鬥。",
		["South-west of Sun Rock lies the burned {area:465}. Plant the Gaea Seeds in the dirt mounds on the valley floor; the fire elementals drop {item:16312}. Bloodfury Harpies and Ambushers nest on the north side, Slayers and Roguefeathers to the south. Careful: the Burning Destroyers, Scorched Basilisks and Bloodfury Storm Witches here are level 27 and the valley floor is crowded: pull one at a time and keep to its edges."] = "烈日石居西南方是燒焦的{area:465}。把蓋亞之種種在谷底的土堆裡；火元素會掉落{item:16312}。血怒鷹身人和血怒伏擊者在北側築巢，血怒殺戮者和血怒遊蕩者在南側。小心：這裡的燃燒的破壞者、炭色石化蜥蜴和血怒風暴女巫都是27級，而且谷底很擁擠：一次拉一隻，並沿著谷底邊緣活動。",
		["The dwarves' flying machine sits on its platform inside the dig site. Use the {item:5021} that {npc:3341} gave you on it."] = "矮人的飛行器停在挖掘場內的平台上。對它使用{npc:3341}給你的{item:5021}。",
		["The flight lands at {area:378}'s wind rider master. {npc:3433} stands at the north edge of the camp, {npc:3387} and {npc:3430} (in the cage) in the middle."] = "飛行會在{area:378}的雙足飛龍管理員處降落。{npc:3433}站在營地北緣，{npc:3387}和{npc:3430}（在籠子裡）在中間。",
		["The flying machine"] = "飛行器",
		["The next guide flies to {area:2897}: hearth to {area:378} if your hearthstone is ready, or walk on east to the Crossroads' flight master."] = "下一份指南會飛往{area:2897}：如果爐石冷卻好了就用爐石回{area:378}，否則繼續向東走到十字路口的飛行管理員。",
		["The road west past {npc:4049}'s camp"] = "沿道路向西經過{npc:4049}的營地",
		["The {object:667362} grows on the bottom of {area:464}, off the same southern shore: dive to the plants and the Dried Mirkweed Piles; both give pods. Watch your breath."] = "{object:667362}生長在{area:464}的湖底，就在同一片南岸外：潛到植物和乾燥的暗色草堆那裡；兩者都會給予豆莢。注意你的呼吸。",
		["Up the {area:1076} to {npc:4201}' hut, where the road forks east to {area:461}: {npc:3442}'s orders are for him."] = "沿著{area:1076}往上走到{npc:4201}的小屋，道路在那裡向東分岔通往{area:461}：{npc:3442}的命令是給他的。",
		["West of Gann, the Razormane hold {area:1701}. {npc:3436} is on the east side, {npc:3434} to the south, {npc:3435} at the west end. Lok (25) and the Warfrenzies (24-25) are a few levels above you; {npc:5859}, a rare elite, sometimes walks the ridge: leave him. Pathfinders and Stalkers drop the Backstabber, Seers the Wand, Warfrenzies the War Shield. {quest:885}, a rare red wind serpent, flies over the ridge: its feather starts a quest.\nCareful: Razormane Stalkers move around in stealth and hit with {spell:1752}, so they can join a fight without warning."] = "在加恩·石塔西邊，鋼鬃野豬人佔據{area:1701}。{npc:3436}在東側，{npc:3434}在南邊，{npc:3435}在西端。洛克·奧克班恩（25級）和鋼鬃戰士（24-25級）比你高幾級；稀有精英{npc:5859}有時會在山脊上走動：別惹他。鋼鬃探路者和鋼鬃捕獵者會掉落鋼鬃背刺匕首，鋼鬃先知會掉落魔杖，鋼鬃戰士會掉落鋼鬃大盾。稀有的紅色風蛇{quest:885}在山脊上空飛行：牠的羽毛會開啟任務。\n小心：鋼鬃捕獵者會潛行移動，並以{spell:1752}攻擊，可能毫無預警地加入戰鬥。",
		["{area:718} quests still in your log: {npc:3446} stands beside the WANTED poster, Bigglefuzz on the dock by the flight master."] = "任務日誌裡還有{area:718}任務：{npc:3446}站在通緝告示旁，畢格弗斯在飛行管理員旁的碼頭上。",
		["{item:277936}, from any Bloodfury harpy"] = "{item:277936}，來自任何血怒鷹身人",
		["{item:5736}, from {quest:1096}"] = "{item:5736}，來自{quest:1096}",
		["{npc:11860}: Glittering Sunstones from the Bloodfury harpies"] = "{npc:11860}：從血怒鷹身人身上取得閃亮日長石",
		["{npc:11860}: Grish is at the {area:1718}, on the next guide's way into {zone:1441}"] = "{npc:11860}：格里什在{area:1718}，就在下一份指南進入{zone:1441}的路上",
		["{npc:11861}, beside {npc:11862}"] = "{npc:11861}，在{npc:11862}旁邊",
		["{npc:11862}, up on the ledge"] = "{npc:11862}，在上方的岩架上",
		["{npc:11864} stands by the bonfire inside Sun Rock: Makaba's news that Kaya is alive is for her."] = "{npc:11864}站在烈日石居內的營火旁：馬卡巴帶來的卡雅還活著的消息正是給她的。",
		["{npc:14242}, up in the tree just east of {npc:3341}"] = "{npc:14242}，在{npc:3341}東邊不遠的樹上",
		["{npc:2995}, the wind rider master, stands on the central rise: take his flight path if you don't have it. {npc:3024} and {npc:4721} stand a short walk east of him."] = "雙足飛龍管理員{npc:2995}站在中央高台上：如果還沒有他的飛行路線就先取得。{npc:3024}和{npc:4721}站在他東邊不遠處。",
		["{npc:3024}: the {object:667362} grows in {area:464}, by Sun Rock"] = "{npc:3024}：{object:667362}生長在烈日石居旁的{area:464}",
		["{npc:3429}, at the top of the tower"] = "{npc:3429}，在塔頂",
		["{npc:3430}, in the cage"] = "{npc:3430}，在籠子裡",
		["{npc:3433}, at the north edge of the camp"] = "{npc:3433}，在營地北緣",
		["{npc:3442} stands beside the flight master you land at. His new orders go back to {npc:4201} on the {area:1076}, later in this guide."] = "{npc:3442}站在你降落處的飛行管理員旁邊。他的新命令要交給{area:1076}的{npc:4201}，在本指南後段。",
		["{npc:3442}: for {npc:4201}, on the way up the {area:1076}"] = "{npc:3442}：交給{npc:4201}，在沿{area:1076}上行的路上",
		["{npc:3442}: {quest:1094}, from {npc:4201}"] = "{npc:3442}：{quest:1094}，來自{npc:4201}",
		["{npc:3665}, on the dock"] = "{npc:3665}，在碼頭上",
		["{npc:4198}'s next quest, Ordanus, is on the Alliance side of {zone:1440}. Skip it."] = "{npc:4198}的下一個任務「奧達努斯」在{zone:1440}的聯盟那一側。跳過。",
		["{npc:4198}, outside the gate"] = "{npc:4198}，在大門外",
		["{npc:4201}, inside"] = "{npc:4201}，在裡面",
		["{npc:4201}: {npc:4202}, at the top of the Venture Co. tower on {area:461}"] = "{npc:4201}：{npc:4202}，在{area:461}的風險投資公司塔樓頂端",
		["{npc:4721}: the phial comes from {zone:1440}, next guide"] = "{npc:4721}：藥瓶來自下一份指南的{zone:1440}",
		["{npc:5899}'s hut stands on the ridge above the quilboar watering hole, south of {area:378}, on the way to {area:359}."] = "{npc:5899}的小屋在{area:378}南邊、野豬人水坑上方的山脊上，在前往{area:359}的路上。",
		["{npc:5899}: the blue waterskin is filled in {zone:1440}, next guide"] = "{npc:5899}：藍色水袋在下一份指南的{zone:1440}裝滿",
		["{npc:5899}: the red waterskin from {area:272}"] = "{npc:5899}：來自{area:272}的紅色水袋",
		["{quest:873}, a big threshadon, swims in the shallows off the {area:391}, east of {npc:3388}."] = "{quest:873}是一隻巨大的長頸龍，在{area:391}外的淺水中游動，位於{npc:3388}東邊。",
} end)()
t.guides["forever/horde/05-stonetalon-mountains"] = (function() return {
		["Back on the road south. Where it turns east into {area:287}, {npc:2214} waits at {area:285}."] = "回到道路往南走。在道路轉向東進入{area:287}的地方，{npc:2214}在{area:285}等候。",
		["Below ground"] = "地下",
		["Down the road through Silverpine to the {area:228}: from the zeppelin towers, south through Tirisfal; from the {object:177844}, south-east from the coast to the road. {npc:2121} and {npc:1937} stand by the crypt entrance."] = "沿著道路穿過銀松森林前往{area:228}：從飛艇塔出發的話，往南穿過提里斯法；從{object:177844}出發的話，從海岸往東南走到道路上。{npc:2121}和{npc:1937}站在墓穴入口旁。",
		["Druid trainer"] = "德魯伊訓練師",
		["Every Wrathtail naga along the strand north of the outpost drops heads."] = "前哨站北邊海岸上的每個怒尾納迦都會掉落頭顱。",
		["Fly to {area:1637}"] = "飛往{area:1637}",
		["For your {area:153} run: the zeppelin lands beside the ruins. Walk into the {zone:1458} through them and down to the {object:36126}: {npc:266484} stands there, near {npc:10181}."] = "為了你的{area:153}之行：飛艇降落在廢墟旁。穿過廢墟走進{zone:1458}，往下到{object:36126}：{npc:266484}站在那裡，靠近{npc:10181}。",
		["For your {area:236} run, at the end of the {area:287} guide: {npc:1952} stands below ground in the crypt."] = "為了你在{area:287}指南結尾的{area:236}之行：{npc:1952}站在墓穴的地下。",
		["From Seereth's camp head north-east across the {zone:1413} to the road north of the Crossroads; Rogues coming from Fizzule's tower head west to it. {npc:8582} stands on the watch tower of the {area:1703} where the road enters {zone:1440}."] = "從賽瑞斯的營地往東北穿過{zone:1413}，前往十字路口北邊的道路；從菲蘇勒的塔過來的盜賊則往西走到這條路。{npc:8582}站在道路進入{zone:1440}處的{area:1703}瞭望塔上。",
		["Naga brazier"] = "納迦火盆",
		["Naga heads"] = "納迦頭顱",
		["On the way west, {npc:267214} is stuck in a ravine south of the main road, south-east of {area:415}. Shadowhorn Stags and Ashenvale Bears roam the woods all around it."] = "向西的途中，{npc:267214}困在主要道路南邊、{area:415}東南方的峽谷裡。黑角鹿和梣谷熊在周圍的樹林中遊蕩。",
		["Out of the ruins, take the road south through Tirisfal into {zone:1421} and on to the {area:228}."] = "離開廢墟，沿道路向南穿過提里斯法進入{zone:1421}，繼續前往{area:228}。",
		["Steer {npc:267214}'s {npc:271181} out of the ravine to the main road within four minutes; if the channel breaks, ask {npc:267214} again."] = "在四分鐘內把{npc:267214}的{npc:271181}操控出峽谷到主要道路；如果引導中斷，再找{npc:267214}一次。",
		["The quest hands you a {item:210713}: use it beside the {object:645153} to offer your blood, then kill the elite spirit that answers.\n{quest:95883} is elite: grouping up is advised."] = "任務會給你一個{item:210713}：在{object:645153}旁使用它獻上你的血，然後擊殺回應的精英靈魂。\n{quest:95883}是精英：建議組隊。",
		["The {area:153} is a dungeon for a group of five, about levels 15 to 22, in the ruined city above the {zone:1458}: its portal is in the ruins you walked through.\nInside: every undead can drop {item:268580} for {npc:266484}, so clear as you go. {npc:250660} can drop an {item:280438}, which starts a quest for {npc:2055}, and a {npc:256102} found inside starts one for {npc:7825}: both are in the {zone:1458}, on this route's next stop there."] = "{area:153}是五人地城，約15到22級，位於{zone:1458}上方的廢墟城市中：傳送門就在你剛走過的廢墟裡。\n裡面：每個不死生物都可能掉落給{npc:266484}的{item:268580}，所以邊走邊清。{npc:250660}可能掉落{item:280438}，可開啟給{npc:2055}的任務；在裡面找到的{npc:256102}則會開啟給{npc:7825}的任務：兩人都在{zone:1458}，就在本路線下一次到那裡時。",
		["Zeppelin to {zone:1458}"] = "搭飛艇前往{zone:1458}",
		["{area:431} is just north up the road. Coming in from the south, the flight master and {npc:12696}'s hunt board at {area:428} come first, then the vendors. {npc:12867} at the lumber camp offers Ashenvale Outrunners: leave it for the next {zone:1440} visit, at 26."] = "沿路往北不遠就是{area:431}。從南邊進來時，先經過飛行管理員和{area:428}的{npc:12696}狩獵告示板，再到商人處。伐木營地的{npc:12867}提供「梣谷先驅者」：留到下次26級來{zone:1440}時再做。",
		["{item:15882}, from the {object:177844}"] = "{item:15882}，來自{object:177844}",
		["{item:271343}, from a {npc:1973}"] = "{item:271343}，來自{npc:1973}",
		["{item:271350}, from the Tortured Souls among the ruins; below ground"] = "{item:271350}，來自廢墟中受折磨的靈魂；在地下",
		["{npc:1952}, below ground"] = "{npc:1952}，在地下",
		["{npc:2214}: Darthalia in {area:272}"] = "{npc:2214}：{area:272}的達薩利亞",
		["{npc:2391} in {area:272} teaches Poisons: keep it"] = "{area:272}的{npc:2391}教授毒藥：先留著",
		["{npc:246152} trains Paladins in {area:159}, a short walk north up the road from the zeppelin towers. Come back down the same road for Silverpine."] = "{npc:246152}在{area:159}訓練聖騎士，從飛艇塔沿著道路往北走一小段就到。之後沿同一條路回來前往銀松森林。",
		["{npc:271181}, on the road"] = "{npc:271181}，在道路上",
		["{npc:5875} stands in the {object:172960}. Use {item:6626} on the summoning circle there and defeat the succubus to bind her."] = "{npc:5875}站在{object:172960}。在那裡的召喚法陣使用{item:6626}，擊敗魅魔以束縛她。",
		["{npc:6389} stands just west of the crypt entrance: hand him {item:16210} from the {zone:1458}."] = "{npc:6389}站在墓穴入口西邊不遠處：把來自{zone:1458}的{item:16210}交給他。",
		["{quest:92421}: the {item:268580}, inside"] = "{quest:92421}：{item:268580}，在裡面",
} end)()
t.guides["forever/horde/06-hillsbrad-foothills"] = (function() return {
		["Back north up the road to the {area:228}: {npc:1938} stands just north of Allister."] = "沿道路向北回到{area:228}：{npc:1938}站在阿利斯特北邊不遠處。",
		["Bears, creepers and lions"] = "熊、食苔蛛和山地獅",
		["Drull's ball and chain"] = "德盧爾的腳鐐",
		["Fill the {item:7768} at the {object:107045} beside the inn"] = "在旅店旁的{object:107045}裝滿{item:7768}",
		["Fly to the {area:1497}"] = "飛往{area:1497}",
		["For your {area:236} run: {npc:1952} stands below ground in the crypt, {npc:1938} just north of Allister."] = "為了你的{area:236}之行：{npc:1952}站在墓穴的地下，{npc:1938}在阿利斯特北邊不遠處。",
		["Hadrec and {npc:1938}"] = "哈德瑞克和{npc:1938}",
		["The farms east of {area:287} town. {npc:232} works the field by the northern farmhouse, {npc:2403} the one further south-east; Farmhands and Farmers are everywhere. {npc:2451} tends the field south of the farms. Careful: Kirin Tor Guards (55) stand north of the farms, on the road up toward Alterac: keep to the fields."] = "{area:287}鎮東邊的農場。{npc:232}在北邊農舍旁的田地工作，{npc:2403}在更東南邊的那塊；希爾斯布萊德雇農和希爾斯布萊德農夫到處都是。{npc:2451}照料農場南邊的田地。小心：祈倫托守衛（55級）站在農場北邊、往奧特蘭克的上坡路上：待在田地裡。",
		["The {item:280438} from the {area:153}: Faranell takes it here."] = "來自{area:153}的{item:280438}：法拉尼爾在這裡接收。",
		["The {object:556670} poster by the inn"] = "旅店旁的{object:556670}海報",
		["The {quest:95204} from your {area:153} run: {npc:7825} takes it."] = "你{area:153}之行取得的{quest:95204}：交給{npc:7825}。",
		["West of Tarren Mill, Gray Bears, Forest Moss Creepers and Starving Mountain Lions roam the hills on the way down to the farms. The creepers drop {item:3477} rarely; you need only one."] = "在塔倫米爾西邊，灰熊、森林食苔蛛和饑餓的山地獅在通往農場的山丘上遊蕩。食苔蛛很少掉落{item:3477}；你只需要一個。",
		["Your {area:153} limbs: {npc:266484} stands in the {object:36126}, just past the Apothecarium."] = "你{area:153}的肢體：{npc:266484}站在{object:36126}，就在皇家藥劑師協會過去一點。",
		["Zeppelin to {zone:1454}"] = "搭飛艇前往{zone:1454}",
		["{area:236} is a dungeon for a group of five, about levels 20 to 30, and a full run takes about an hour. Follow the road south from the {area:228}: the keep stands on the hill above {area:204}, its gate at the top of the path.\nInside: Rethilgore first; the Deathstalker freed from the cells after him opens the courtyard door, and {npc:4444} lies just inside the courtyard, to the right: hand {quest:1098} in to him there. Then {npc:3886}, {npc:3887}, {npc:4278}, {npc:4279}, {npc:4274} and {npc:3927}; {npc:4275} at the top drops his head for {npc:1938}."] = "{area:236}是五人地城，約20到30級，完整打一次約需一小時。從{area:228}沿道路向南：城堡矗立在{area:204}上方的山丘上，大門在小路頂端。\n裡面：先打雷希戈爾；在他之後從牢房救出的亡靈哨兵會打開庭院的門，{npc:4444}就躺在庭院入口右邊：在那裡把{quest:1098}交給他。接著是{npc:3886}、{npc:3887}、{npc:4278}、{npc:4279}、{npc:4274}和{npc:3927}；頂端的{npc:4275}會掉落他的頭，交給{npc:1938}。",
		["{item:15885}: use a half at the {area:2362}"] = "{item:15885}：在{area:2362}使用一半墜飾",
		["{item:3692}: the Peasants in the fields"] = "{item:3692}：田裡的希爾斯布萊德農民",
		["{npc:11798} in {area:2361} flies druids there"] = "{area:2361}的{npc:11798}會載德魯伊飛到那裡",
		["{npc:1952}, below ground"] = "{npc:1952}，在地下",
		["{npc:2055}, in the Apothecarium"] = "{npc:2055}，在皇家藥劑師協會",
		["{npc:2230}, next to Lydon; inside"] = "{npc:2230}，在藥劑師林度恩旁邊；在裡面",
		["{npc:2238}'s ball and chain"] = "{npc:2238}的腳鐐",
		["{npc:2274} is {npc:232}'s dog, at the northern farmhouse in {area:286}."] = "{npc:2274}是{npc:232}的狗，在{area:286}北邊的農舍。",
		["{npc:2391}: Poisons"] = "{npc:2391}：毒藥",
		["{npc:3024}: {quest:97538}, the Mirkweed in {area:464} by Sun Rock"] = "{npc:3024}：{quest:97538}，太陽岩旁{area:464}的暗色水草",
		["{npc:4606} stands in the {object:36070}."] = "{npc:4606}站在{object:36070}。",
		["{npc:4721}: {quest:1195}, the phial from {zone:1440}'s Laughing Sisters"] = "{npc:4721}：{quest:1195}，從{zone:1440}的狂笑姐妹身上取得藥瓶",
		["{quest:1014}: the {item:5442}"] = "{quest:1014}：{item:5442}",
} end)()
t.guides["forever/horde/07-ashenvale"] = (function() return {
		["A short walk north of the Galak camps, the cave of {area:1557} leads down to its deepest chamber, where the {object:20807} burns. Use the {item:5868} on it, then loot the {item:5869} at once: the flame only stays out briefly, and if it relights the phial is gone. Then east to {npc:2986}'s mesa.\nCareful: Two Galak Flame Guards (30) stand by the brazier and a centaur guard walks the cave: pull them away one at a time before you douse the flame."] = "在加拉克營地北邊不遠處，{area:1557}的洞穴通往最深處的洞室，{object:20807}就在那裡燃燒。對它使用{item:5868}，然後立刻拾取{item:5869}：火焰只會熄滅一小段時間，如果重新燃起，藥瓶就沒了。接著向東前往{npc:2986}的台地。\n小心：火盆旁站著兩個加拉克火焰守衛（30級），還有一個半人馬守衛在洞穴中巡邏：在熄滅火焰之前，先把他們一次一個拉開。",
		["Back south to the camp, then up into {zone:1456} for the flight to {area:378}."] = "向南回到營地，然後上到{zone:1456}搭乘飛往{area:378}的飛行路線。",
		["Back to {npc:12867} at the lumber camp, on the road north to Splintertree."] = "回到伐木營地的{npc:12867}那裡，就在往北通往碎木崗哨的路上。",
		["Befouled Water Elementals drift around the lake's shores; the gazebo stands on the island, overlooking the Alliance outpost."] = "污濁的水元素在湖岸周圍漂浮；涼亭在島上，俯瞰著聯盟前哨。",
		["Class trainer"] = "職業訓練師",
		["Felmusk satyrs"] = "魔草薩特",
		["Fly to {area:1638}"] = "飛往{area:1638}",
		["Fly to {area:1638} from Zoram'gar. If you don't know its flight path, fly to {area:378} and walk north through {zone:1412} instead."] = "從左拉姆加飛往{area:1638}。如果你不知道它的飛行路線，改飛往{area:378}，然後向北步行穿過{zone:1412}。",
		["Fly to {area:378}"] = "飛往{area:378}",
		["Follow the main road east past {area:415} (Alliance: keep to the road). {npc:12678}, a big grizzly, roams the {area:418} south of the road, west of {area:421}. His paw starts the next hunt quest."] = "沿著主要道路向東經過{area:415}（聯盟據點：沿著道路走）。{npc:12678}是一頭大灰熊，在道路南邊、{area:421}西邊的{area:418}遊蕩。牠的爪子會開始下一個狩獵任務。",
		["For your {area:2797} run, in the same tunnels as the Sapphires: {npc:12736}'s ruins errand. Look for a group now if you have none yet."] = "為了你的{area:2797}之行，就在藍寶石所在的同一條隧道裡：{npc:12736}的廢墟差事。如果你還沒有隊伍，現在就開始找。",
		["From the {area:2360} head north-east to the Warsong lumber camp on the road: {npc:12867} stands there."] = "從{area:2360}往東北前往路邊的戰歌伐木營地：{npc:12867}站在那裡。",
		["Galak centaurs"] = "加拉克半人馬",
		["Gazebo"] = "涼亭",
		["Gloomrise Toxin Samples, from the Gnawed Corpses"] = "鬱湧毒素樣本，來自{npc:264096}",
		["Keep east on the road. {npc:12858} waits south-west of the Warsong lumber camp. He and his grunts storm the {area:2360}: let them take aggro and stay with {npc:12858} until {npc:12860} is dead."] = "沿著道路繼續向東。{npc:12858}在戰歌伐木營地西南方等候。他和他的步兵會猛攻{area:2360}：讓他們吸引仇恨，跟著{npc:12858}直到{npc:12860}死亡。",
		["Kill the {npc:10720} that comes for {npc:10638}"] = "擊殺前來對付{npc:10638}的{npc:10720}",
		["Laughing Sisters"] = "歡笑姐妹",
		["North of the camp, spiders overrun the burial ground at {area:17044}. Use {npc:264074}'s {item:273015} on the Gnawed Corpses; the Spinners drop the {item:273181}. {npc:264082} (30, elite) sits at the north end: leave her unless you do {quest:96261} with a group; her {item:273658} starts {quest:96294}."] = "在營地北邊，蜘蛛佔據了{area:17044}的墓地。對被啃咬的屍體使用{npc:264074}的{item:273015}；紡絲蜘蛛會掉落{item:273181}。{npc:264082}（30級，精英）在北端：除非組隊做{quest:96261}，否則別碰她；她的{item:273658}會開始{quest:96294}。",
		["North-west of Splintertree, the Felmusk satyrs camp in the woods. Every satyr can drop horns. Careful: Felmusk Rogues and Shadowstalkers move in stealth and join fights without warning."] = "在碎木崗哨西北方，魔草薩特在樹林中紮營。每個薩特都可能掉落角。小心：魔草盜賊和魔草捕獵者會潛行移動，毫無預警地加入戰鬥。",
		["On the way back north-east to Splintertree: {npc:12676} prowls the woods south-east of the Warsong lumber camp. Her claw starts the next hunt quest. Careful: {npc:12676} is a level 31 nightsaber and hits hard: pull her alone, away from the Outrunners."] = "往東北返回碎木崗哨的路上：{npc:12676}在戰歌伐木營地東南邊的樹林裡徘徊。她的爪子會開始下一個狩獵任務。小心：{npc:12676}是一隻31級的夜刃豹，攻擊很痛：把她單獨拉出來，遠離梣谷先驅者。",
		["Only if the {npc:10617} dropped his plot for you: {npc:10638} stands at {area:2237}."] = "只有在{npc:10617}掉落他的陰謀給你時才做：{npc:10638}站在{area:2237}。",
		["Ride the lift down, then follow the road east through the canyons to {area:484}, a Tauren village on top of the mesas. Its lift is on the north side."] = "搭升降梯下去，然後沿著道路向東穿過峽谷前往{area:484}，這是一座位於台地頂端的牛頭人村莊。它的升降梯在北側。",
		["Sapphires of Aku'Mai"] = "阿庫麥爾藍寶石",
		["South from Raynewood, the moonwell sits in a hollow west of the river, hard to see from the road; {area:421} is west of it. Use the {item:5867} at the moonwell to fill it."] = "從雷恩林地往南，月井位於河流西邊的一處窪地中，從道路上很難看見；{area:421}在它西邊。在月井使用{item:5867}將它裝滿。",
		["Speak with {npc:3057}, in {area:1638}: {quest:93739}"] = "與{area:1638}的{npc:3057}交談：{quest:93739}",
		["Take the lift down. The egg lies in a nest on the canyon floor in one of three spots: south-east of the mesas (52.3,55.2), east (56.4,50.4) or south-west (37.6,56.1)."] = "搭升降梯下去。蛋在峽谷底部的巢裡，位於三處之一：台地東南方（52.3,55.2）、東方（56.4,50.4）或西南方（37.6,56.1）。",
		["The Earthen Ring"] = "陶土議會",
		["The Foulweald furbolgs hold the woods east of {area:421}, south of the road. Place {item:16972} on the {object:178206} and guard it: the furbolgs come to tear it down. {npc:12918} comes last; his totem drops in the basket."] = "汙林熊怪佔據{area:421}東邊、道路南邊的樹林。把{item:16972}放在{object:178206}上並守住它：熊怪會來把它拆掉。{npc:12918}最後出現；他的圖騰會掉在籃子裡。",
		["The Galak camps fill the canyon north of Freewind; Scouts, Wranglers and Windchasers share every camp. A lone {npc:10617} walks a long path between the camps: if you meet him, kill him, his note starts a quest for {area:2237}. Don't wait for him. Careful: storm elementals roam the canyon floor around the camps: Stormheart (30), the Ravaging Tempests (40) and {npc:216463} (38), all elite. Keep clear of them."] = "加拉克營地遍布亂風崗北邊的峽谷；每個營地都有加拉克斥候、加拉克爭鬥者和加拉克逐風者。有一個落單的{npc:10617}沿著一條很長的路線在營地之間走動：如果遇到他，就殺了他，他的信會開始一個交給{area:2237}的任務。不要專門等他。小心：風暴元素在營地周圍的峽谷底部遊蕩：Stormheart（30級）、Ravaging Tempest（40級）和{npc:216463}（38級），全都是精英。遠離牠們。",
		["The Laughing Sisters, dryads, wander {area:426} around {npc:12677}'s woods; one of them drops {npc:4721}'s {item:5867}, which can take several kills."] = "歡笑姐妹是樹妖，在{npc:12677}所在樹林周圍的{area:426}遊蕩；其中一隻會掉落{npc:4721}的{item:5867}，可能需要擊殺好幾隻。",
		["The Sapphires are blue crystals on the walls of the tunnels leading to the {area:2797} portal, underground and outside the instance: swim down from the pit, under the wall, into the cave. The satyrs and naga in the tunnels are elite: grouping up is advised. The crystals respawn quickly, so there is no need to go deep."] = "藍寶石是通往{area:2797}傳送門的隧道牆上的藍色水晶，位於地下、副本之外：從坑洞往下游，穿過牆下進入洞穴。隧道裡的薩特和納迦是精英：建議組隊。水晶重生得很快，不必深入。",
		["The Wanted poster beside {npc:10537}"] = "{npc:10537}旁的通緝告示",
		["The fountain stands in the middle of the {area:418}, where {npc:12678} roams: use the {item:7767} there."] = "噴泉位於{area:418}中央，{npc:12678}在那裡遊蕩：在那裡使用{item:7767}。",
		["The night elf {quest:6503} (23-24) stalk the woods south and south-east of the lumber camp; they stealth, so watch for them."] = "夜精靈的{quest:6503}（23-24級）在伐木營地南方和東南方的樹林中潛行；他們會隱形，要留意。",
		["The way to the Sapphires is through the sunken ruins at the north end of the strand: go down the stairs into the pit."] = "前往藍寶石的路要穿過海岸北端沉沒的遺跡：從階梯走下坑洞。",
		["Underwater"] = "在水下",
		["Warsong lumber camp"] = "戰歌伐木營地",
		["West of Freewind, the Grimtotem camps below {area:2097}. The Secret Notes are in Document Chests at the south-east, south-west and north-west camps."] = "在亂風崗西邊，恐怖圖騰在{area:2097}下方紮營。密信放在東南、西南和西北營地的{object:176344}裡。",
		["West of Mystral Lake, {npc:12678}, a big grizzly, roams the {area:418}: his paw now drops for you."] = "在密斯特拉湖西邊，大灰熊{npc:12678}在{area:418}遊蕩：現在牠的爪子會為你掉落了。",
		["for {npc:5901}, south of {area:392}: next guide"] = "給{area:392}南邊的{npc:5901}：下一份指南",
		["{area:2797} is a dungeon for a group of five, about levels 22 to 30, and a full run takes about an hour. Its portal is a little further along the tunnels you are in, past the Sapphires.\nInside: the {object:177964} lies under the water of the Moonshrine Ruins' pool, beneath the walkway (clear the crabs first): open it for the {item:16762}, and {quest:6922} comes; open the {item:16782} he drops for a quest for {npc:12736}. The Tide Priestesses sometimes drop a {item:16790}: open it for another quest for {npc:12736}. {npc:4787}, by a campfire in an underwater side room off Ghamoo-ra's room, offers Blackfathom Villainy ({npc:4832}' head, for {npc:9087} on {zone:1456}'s {area:1639})."] = "{area:2797}是五人地城，約22到30級，完整打一次約需一小時。傳送門就在你所在的隧道再往前一點，過了藍寶石就到。\n裡面：{object:177964}在月神殿廢墟水池的水下，走道下方（先清掉螃蟹）：打開它取得{item:16762}，{quest:6922}就會出現；打開他掉落的{item:16782}，可取得一個給{npc:12736}的任務。潮汐女祭司有時會掉落{item:16790}：打開它可取得另一個給{npc:12736}的任務。{npc:4787}在迦莫拉房間旁一間水下側室的營火邊，提供「黑暗深淵的惡行」（{npc:4832}的頭，交給{zone:1456}{area:1639}的{npc:9087}）。",
		["{area:2797} ruins"] = "{area:2797}遺跡",
		["{area:418} fountain"] = "{area:418}的噴泉",
		["{item:273181}, from Gloomrise Spinners"] = "{item:273181}，來自{npc:264081}",
		["{item:273658}, from {npc:264082}: it does not drop for everyone"] = "{item:273658}，來自{npc:264082}：不是每個人都會掉落",
		["{item:5867}, at the {object:20806}"] = "{item:5867}，在{object:20806}",
		["{item:5867}, from a {npc:4054}"] = "{item:5867}，來自{npc:4054}",
		["{item:5868}, at the {object:20807}"] = "{item:5868}，在{object:20807}",
		["{item:5869}, from the {object:20807}"] = "{item:5869}，來自{object:20807}",
		["{npc:10079}, at the top of the lift: {npc:10537} at {area:484}"] = "{npc:10079}，在升降梯頂端：{npc:10537}在{area:484}",
		["{npc:10377}, by the wind rider master"] = "{npc:10377}，在雙足飛龍管理員旁",
		["{npc:10428}'s next quest, Sacred Fire, ends in {zone:1456}, off this route. Skip it."] = "{npc:10428}的下一個任務「聖火」在{zone:1456}完成，不在這條路線上。跳過。",
		["{npc:10617}'s {quest:4881}, if you meet him"] = "{npc:10617}的{quest:4881}，如果你遇到他",
		["{npc:12576} and {npc:10079} wait at the top of the {area:485}: Maggran's letter is for {npc:12576}, and Moonhorn's message goes down to {area:484} with you."] = "{npc:12576}和{npc:10079}在{area:485}頂端等著：瑪格蘭的信是給{npc:12576}的，月角的口信則跟著你下到{area:484}。",
		["{npc:12677}, a shadow panther, stalks the woods around {area:426}, west of the Felmusk camp. Her head starts the next hunt quest."] = "{npc:12677}是一隻暗影豹，在魔草營地西邊的{area:426}周圍的樹林中潛行。她的頭顱會開始下一個狩獵任務。",
		["{npc:12696} keeps the hunt board at {area:428}, by the flight master: take {quest:6383} and hand it straight back. {npc:12678}, {npc:12676} and {npc:12677} drop their trophies only after it."] = "{npc:12696}在{area:428}的飛行管理員旁管理狩獵告示板：接下{quest:6383}並立刻交回。之後{npc:12678}、{npc:12676}和{npc:12677}才會掉落牠們的戰利品。",
		["{npc:12718}: only if you carry the manual pages"] = "{npc:12718}：只有在你帶著手冊書頁時",
		["{npc:12736} offers a {area:2797} quest next; leave it unless you have a group."] = "{npc:12736}接著會提供一個{area:2797}任務；除非你有小隊，否則先不要做。",
		["{npc:12736} then offers the next part, {quest:6564}: it is for a second run, so leave it."] = "{npc:12736}接著會提供下一部分{quest:6564}：那是第二趟用的，先別接。",
		["{npc:12757}: a banner defence in the Foulweald, east of {area:421}: furbolg waves, then {npc:12918}"] = "{npc:12757}：在{area:421}東邊的穢木林守衛旗幟：先是一波波熊怪，然後是{npc:12918}",
		["{npc:2986} stands on a mesa top east of the Galak camps. For the {quest:1149}, walk off the end of the planks beside him: you land safely."] = "{npc:2986}站在加拉克營地東邊的台地頂上。為了{quest:1149}，從他旁邊的木板盡頭走下去：你會安全落地。",
		["{npc:3024} stands beside {npc:4721}, east of {npc:2995}."] = "{npc:3024}站在{npc:4721}旁邊，位於{npc:2995}東邊。",
		["{npc:4721} stands a short walk east of {npc:2995}."] = "{npc:4721}站在{npc:2995}東邊不遠處。",
		["{npc:4721}: {npc:4722} at {area:484}, later in this guide"] = "{npc:4721}：{area:484}的{npc:4722}，在本指南稍後",
		["{npc:4722} stands in {area:484}: {npc:4721}'s filled phial is for him."] = "{npc:4722}站在{area:484}：{npc:4721}裝滿的藥瓶是要給他的。",
		["{npc:4722}: the {object:20807} in {area:1557}, among the Galak camps"] = "{npc:4722}：{area:1557}裡的{object:20807}，在加拉克營地之間",
		["{npc:5899}'s hut stands on the ridge above the quilboar watering hole south of {area:378}, on the road to the {area:485}."] = "{npc:5899}的小屋在{area:378}南邊野豬人飲水處上方的山脊上，位於前往{area:485}的路上。",
		["{object:176344}, north-west camp"] = "{object:176344}，西北營地",
		["{object:176344}, south-east camp"] = "{object:176344}，東南營地",
		["{object:176344}, south-west camp"] = "{object:176344}，西南營地",
		["{quest:6921}: the {item:16762}, from the {object:177964}"] = "{quest:6921}：{item:16762}，來自{object:177964}",
		["{zone:1456}'s central rise"] = "{zone:1456}的中央高台",
} end)()
t.guides["forever/horde/30-40/01-hillsbrad-foothills"] = (function() return {
		["Back to the fields: the Peasants work south of the farmhouses. Careful: A fleeing peasant that reaches the town hall can bring back adds; snares or roots keep them from escaping."] = "回到農田：農民在農舍南邊工作。小心：逃跑的農民如果跑到鎮公所，可能會帶回更多敵人；用緩速或定身可以阻止他們逃跑。",
		["Back to {area:272}."] = "返回{area:272}。",
		["City of Dalaran"] = "達拉然城",
		["Drull's ball and chain"] = "德盧爾的腳鐐",
		["Fly to {area:1637}"] = "飛往{area:1637}",
		["Fly to {area:272}"] = "飛往{area:272}",
		["For your City of Dalaran run, later in this guide: {npc:2278} stands in {area:272}, a short walk east of {npc:2410}."] = "為了你稍後在本指南中的達拉然城之行：{npc:2278}站在{area:272}，在{npc:2410}東邊不遠處。",
		["Hillsbrad Peasants"] = "希爾斯布萊德農民",
		["South-east of Tarren Mill. Drull and {npc:2238} are chained in the keep's courtyard buildings: {npc:2427} carries the {item:3467} and {npc:2428} the {item:3499}, both in the keep. Kill them, then open both locks."] = "在塔倫米爾東南方。德盧爾和{npc:2238}被鎖在城堡庭院的建築裡：{npc:2427}帶著{item:3467}，{npc:2428}帶著{item:3499}，兩人都在城堡裡。殺死他們，然後打開兩道鎖。",
		["The City of Dalaran is a dungeon for a group of five, about levels 28 to 33, under the violet dome. Without the {item:277507}, go in through the sewer pipe north-west of the crater: the arrow leads there.\nInside: {npc:247126} is {npc:2278}'s. {npc:268743}, in the sewer, gives Opportunistic Education and takes it back there."] = "達拉然城是五人地城，約28到33級，位於紫色的穹頂之下。沒有{item:277507}的話，就從巨坑西北方的下水道管道進去：箭頭會帶你去那裡。\n裡面：{npc:247126}是{npc:2278}要的。下水道裡的{npc:268743}會給你「投機教育」，並在那裡收回。",
		["The smithy"] = "鐵匠鋪",
		["Torn Fin murlocs"] = "碎鰭魚人",
		["Town hall"] = "市政廳",
		["Train"] = "訓練",
		["Train while you are in the {zone:1458}: the trainers stand in the {object:36070}, the {object:36073} and the {object:36082} (Paladins: {npc:260093})."] = "趁你在{zone:1458}時學習：訓練師都在{object:36070}、{object:36073}和{object:36082}（聖騎士：{npc:260093}）。",
		["Train your new spells."] = "學習你的新法術。",
		["West past the hills to the farms east of {area:287} town. {npc:232} works the field by the northern farmhouse, {npc:2403} the one further south-east; Farmhands and Farmers are everywhere.\nCareful: Kirin Tor Guards (55) patrol {area:287}'s fields and roads and attack the Horde: keep an eye out for them and stay out of their way."] = "往西越過山丘，前往{area:287}鎮東邊的農場。{npc:232}在北邊農舍旁的田裡工作，{npc:2403}在更東南邊的那片田裡；雇農和農夫到處都是。\n小心：祈倫托守衛（55級）在{area:287}的田地和道路上巡邏，會攻擊部落：留意牠們，別擋到牠們的路。",
		["You missed Darthalia's first errands, from the 22-25 {area:287} guide: they come first now. They are a few levels below you and quick, and they open the rest of the {quest:527} in this guide."] = "你錯過了22-25級{area:287}指南中達薩利亞最早的幾個差事：現在先做這些。它們比你低幾級，很快就能完成，還會開啟本指南中{quest:527}的後續任務。",
		["Zeppelin to {zone:1458}"] = "搭飛艇前往{zone:1458}",
		["{npc:2215}: her next {quest:539}, and {npc:2419}'s sword, are elite group quests at {area:290}: take them only with a group"] = "{npc:2215}：她的下一個任務{quest:539}和{npc:2419}的劍，都是{area:290}的精英組隊任務：只有在有隊伍時才接",
		["{npc:2238}'s ball and chain"] = "{npc:2238}的腳鐐",
		["{npc:270038} stands in the Apothecarium. His {quest:97985} is for Stormheart, a level 30 elite who walks the canyon east of {area:484}, on the next guide's way to the {area:439}."] = "{npc:270038}站在皇家藥劑師協會。他的{quest:97985}目標是風暴之心，一隻30級精英，在{area:484}東邊的峽谷中走動，就在下一份指南前往{area:439}的路上。",
		["{npc:270038}: back to him on the next {zone:1458} stop, at about 38"] = "{npc:270038}：下次約38級到{zone:1458}時再回來找他",
		["{npc:4949}, Grommash Hold, if you carry it"] = "{npc:4949}，Grommash Hold，如果你帶著它",
		["{quest:96986} from your City of Dalaran run: {npc:2278}, a short walk east of {npc:2410}."] = "你達拉然城之行的{quest:96986}：{npc:2278}，在{npc:2410}東邊不遠處。",
		["{quest:96986}: {npc:247126}, inside"] = "{quest:96986}：{npc:247126}，在裡面",
		["{zone:1458} trainers"] = "{zone:1458}的訓練師",
} end)()
t.guides["forever/horde/30-40/02-thousand-needles"] = (function() return {
		["Clam beds"] = "蚌床",
		["Fly to {area:460}"] = "飛往{area:460}",
		["Fly to {area:484}"] = "飛往{area:484}",
		["Head north along the coast, then inland to the ruined tower of {area:2405}: {npc:11863} waits inside. The coast's clams and naga come after {area:599}, on one walk north to {area:2406}."] = "沿著海岸向北走，然後往內陸前往{area:2405}的廢棄塔樓：{npc:11863}在裡面等你。海岸的蚌和納迦留到{area:599}之後，一路往北走向{area:2406}時再處理。",
		["South from the raceway over the {zone:1446} border to {area:976}, the walled goblin town: learn its flight path and fly back to {area:484} from there, which is quicker than the walk west across the flats, and the next guides fly straight to {area:976}."] = "從賽車場向南越過{zone:1446}邊界前往{area:976}，那座有城牆的哥布林城鎮：學會那裡的飛行路線，然後從那裡飛回{area:484}，比向西走過平原更快，而且接下來的指南會直接飛往{area:976}。",
		["The zeppelin lands at the tower outside {zone:1454}'s main gate. {npc:5639} walks the Drag: if he isn't at the arrow, look along its streets to the south-west. {npc:5640} stands in the {object:172961} on the west side of the city."] = "飛艇停靠在{zone:1454}正門外的塔上。{npc:5639}在暗巷區四處走動：如果他不在箭頭處，就沿著西南方的街道尋找。{npc:5640}站在城市西側的{object:172961}。",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:270094} is a level 30 elite: most classes solo it at level 32, but you may need help. Skip it if you are alone: the route has you grind the XP back.\n{npc:270094} walks the canyon road east of {area:484}'s lift, on the way to the salt flats: kill him for his heart."] = "這些是精英怪物：建議組隊，找人一起打。{npc:270094}是30級精英：大多數職業在32級時可以單刷，但你可能需要幫忙。如果你是獨自一人就跳過：路線會讓你把經驗值練回來。\n{npc:270094}在{area:484}升降梯東邊的峽谷道路上走動，就在前往鹽平原的路上：殺了他取得心臟。",
		["Underwater"] = "在水下",
		["West to the shore. Giant Softshell Clams lie in the shallows and the Enraged Reef Crawlers walk the beach: each clam you open on the sea floor, and some crawlers, give a {item:15874}. Open each one in your bags for its meat.\nThe Drysnap Crawlers and Pincers on the same beach carry {item:15878}, about one in seven."] = "向西前往海岸。巨型軟殼蚌躺在淺水中，狂怒的礁石爬行者在海灘上走動：你在海底打開的每個蚌，以及部分爬行者，都會給你一個{item:15874}。在背包中打開每一個以取得蚌肉。\n同一片海灘上的乾鉗爬行者和乾鉗鉗蟹身上帶有{item:15878}，大約七隻掉一把。",
		["Zeppelin to {zone:1454}"] = "搭飛艇前往{zone:1454}",
		["{item:15878}, from the Drysnap crabs"] = "{item:15878}，來自乾鉗螃蟹",
		["{item:15881}, from the Slitherblade naga"] = "{item:15881}，來自滑刃納迦",
		["{item:279186}, from {npc:270094}"] = "{item:279186}，來自{npc:270094}",
		["{npc:5395} now offers Centaur Bounty: the second {zone:1443} visit, at 38, takes it on its way to the {area:607}."] = "{npc:5395}現在會提供「半人馬賞金」：38級第二次造訪{zone:1443}時，會在前往{area:607}的路上接取。",
		["{npc:5641}'s next errand sends you after a demon lord with an elite guard: skip it."] = "{npc:5641}的下一個差事要你去對付一名帶著精英守衛的惡魔領主：跳過它。",
		["{npc:5892} stands in the {object:172957}."] = "{npc:5892}站在{object:172957}。",
		["{npc:5901}: {npc:3527} and your {item:5177}"] = "{npc:5901}：{npc:3527}和你的{item:5177}",
		["{npc:5905} also starts Elemental Aid ({area:1717}), the 33-40 chain to The Tempest's Weapons: forever/class/shaman/call-of-air-horde."] = "{npc:5905}也會開啟Elemental Aid（{area:1717}），這是通往風暴武器的33-40級任務鏈：forever/class/shaman/call-of-air-horde。",
		["{npc:5905}: your {item:5178}"] = "{npc:5905}：你的{item:5178}",
		["{object:177787} lies on the ground just south-west of {npc:11863}'s tower, on the way down to the shore: read it. Its two keys drop only while you have the quest."] = "{object:177787}躺在{npc:11863}塔樓西南方不遠處的地上，就在下往海岸的路上：閱讀它。它的兩把鑰匙只有在你接了任務時才會掉落。",
		["{zone:1454} flight master"] = "{zone:1454}的飛行管理員",
} end)()
t.guides["forever/horde/30-40/03-stranglethorn-vale"] = (function() return {
		["Back north to the camp."] = "向北回到營地。",
		["Back to {object:3202}."] = "返回{object:3202}。",
		["Boat to {area:35}"] = "搭船前往{area:35}",
		["Dizzywig's parts go back to Kravel in the {area:439}, off the route: leave them."] = "迪茲維格的零件要交還給{area:439}的克拉維爾，不在路線上：放棄它們。",
		["Fly to {area:1637}"] = "飛往{area:1637}",
		["Fly to {area:35}"] = "飛往{area:35}",
		["Fly to {area:392}"] = "飛往{area:392}",
		["Fly to {object:3202}"] = "飛往{object:3202}",
		["Follow the road north out of {object:3202}; Nesingwary's hunting camp sits on the hill north-east of the river. {npc:773} wants it investigated: walk among its tents. From here on, keep every page of The {item:2755} you loot: {npc:716} takes them on your next Stranglethorn visit."] = "沿著道路從{object:3202}向北走；奈辛瓦里的狩獵營地在河東北方的山丘上。{npc:773}要你調查那裡：在帳篷之間走一走。從現在起，保留你拾取的每一頁{item:2755}：{npc:716}會在你下次來荊棘谷時收下。",
		["Leave {area:35} through the tunnel and follow the road north to {object:3202}, the orc camp on the west side of the vale. Stay on the road: the jungle beside it is above your level."] = "從隧道離開{area:35}，沿著道路向北前往{object:3202}，也就是山谷西側的獸人營地。待在道路上：路旁叢林的等級比你高。",
		["Mosh'Ogg camp"] = "莫什奧格營地",
		["Nesingwary's camp"] = "奈辛瓦里的營地",
		["North-west of Grom'gol the {area:104} lies under the water off the coast. The {item:4094} rests on the sea floor by the sunken ruins; watch your breath and the murlocs."] = "{area:104}位於格羅姆高營地西北方的外海水下。{item:4094}在沉沒遺跡旁的海底；注意你的呼吸和魚人。",
		["River Crocolisks lie along the river below the camp. Young Stranglethorn Tigers prowl west of the camp, Young Panthers east of it. Head west past the camp. Stranglethorn Raptors (33-34) hunt the clearings, and the Bloodscalp trolls hold the ruins on the coast: every Bloodscalp can drop a tusk. A {item:4614} is a very rare drop from them: if one drops, read it. Careful: The troll camps have many patrolling mobs, so other trolls often join a fight."] = "淡水鱷沿著營地下方的河邊趴著。幼年荊棘谷猛虎在營地西邊徘徊，幼年黑豹在營地東邊。經過營地往西走。荊棘谷迅猛龍（33-34級）在空地上獵食，血頂食人妖佔據著海岸的遺跡：每個血頂食人妖都可能掉落獠牙。{item:4614}是牠們極為稀有的掉落物：如果掉落了，就閱讀它。小心：食人妖營地有許多巡邏的怪物，其他食人妖經常會加入戰鬥。",
		["The Shadowmaw Panthers come much later, by {object:3202}"] = "深喉獵豹要很久以後才會遇到，在{object:3202}附近",
		["The next guide takes the zeppelin to {zone:1454} from the tower on the west side of the camp."] = "下一份指南會從營地西側的塔搭飛艇前往{zone:1454}。",
		["Underwater"] = "在水下",
		["{area:2408} flight master"] = "{area:2408}的飛行管理員",
		["{area:35} first: the goblins' boat sails there from {area:392}, and every {area:35} quest is for the north of the vale, which you then walk up into."] = "先去{area:35}：地精的船從{area:392}開往那裡，而且{area:35}的每個任務都在山谷北部，之後你會步行往北走。",
		["{npc:2464} stands in the middle of {object:3202}, {npc:2497} near the zeppelin tower, {npc:2465} beside the flight master."] = "{npc:2464}站在{object:3202}中央，{npc:2497}在飛艇塔附近，{npc:2465}在飛行管理員旁邊。",
		["{npc:2496}, upstairs"] = "{npc:2496}，在樓上",
		["{npc:2497}: for Arathi, later on the route"] = "{npc:2497}：給阿拉希，在路線稍後",
		["{npc:3391} waits upstairs in the house by the flight master; {quest:1111} stands on the docks, beside the boat."] = "{npc:3391}在飛行管理員旁那棟房子的樓上等候；{quest:1111}站在碼頭上，船的旁邊。",
		["{npc:3391}, upstairs"] = "{npc:3391}，在樓上",
		["{npc:3391}: for {npc:4631} in {area:35}, where the boat goes"] = "{npc:3391}：給{area:35}的{npc:4631}，也就是船的目的地",
		["{npc:4631} stands on the pier where the boat docks. {npc:2495}'s shop is in the building east of the inn; {npc:2498} is on the inn's bottom floor, {npc:2496}, {npc:737} and {npc:773} upstairs, {npc:2858} the flight master on the upper deck."] = "{npc:4631}站在船停靠的碼頭上。{npc:2495}的商店在旅店東邊的建築裡；{npc:2498}在旅店的一樓，{npc:2496}、{npc:737}和{npc:773}在樓上，飛行管理員{npc:2858}在上層平台。",
		["{npc:4631}, on the pier"] = "{npc:4631}，在碼頭上",
		["{quest:1111}, on the docks"] = "{quest:1111}，在碼頭上",
		["{zone:1454} flight master"] = "{zone:1454}的飛行管理員",
} end)()
t.guides["forever/horde/30-40/04-dustwallow-marsh"] = (function() return {
		["Fly to {area:1637}"] = "飛往{area:1637}",
		["Fly to {area:378}"] = "飛往{area:378}",
		["Fly to {area:392}"] = "飛往{area:392}",
		["Head east from {area:378} along the road into the marsh. The burned-out {area:403} stands beside it just past the border; the shield, the badge and the hoofprints are in and beside the ruin."] = "從{area:378}沿著道路向東進入沼澤。燒毀的{area:403}就在過了邊界不遠的路旁；盾牌、徽章和蹄印都在廢墟裡和廢墟旁。",
		["Head north to {area:502}. Stinky stands at the foot of the hill; escort him while he gathers Bogbean Leaves just south of it."] = "向北前往{area:502}。伊格納茲站在山腳下；他在山南邊採集泥豆葉時護送他。",
		["Jarl lives in the {area:497} south-east of {area:502}."] = "加爾住在{area:502}東南方的{area:497}。",
		["Mirefin murlocs"] = "黑鰭魚人",
		["Stinky Ignatz"] = "伊格納茲",
		["Swamp Eye Jarl"] = "「沼澤之眼」加爾",
		["Take the road north at the fork to the ogre village of Brackenwall."] = "在岔路往北走，前往巨魔村莊蕨牆村。",
		["The Mirefin murlocs crowd the coast east and north-east of {area:502}; every kind drops heads."] = "黑鰭魚人聚集在{area:502}東邊和東北方的海岸；每一種都會掉落頭顱。",
		["The {area:2657}"] = "{area:2657}",
		["Underwater"] = "在水下",
		["Zeppelin to {zone:1454}"] = "搭飛艇前往{zone:1454}",
		["only if you carry a {item:3853} ({skill:164} or the Auction House)"] = "僅限你帶著{item:3853}時（{skill:164}或拍賣場）",
		["{area:2408} flight master"] = "{area:2408}的飛行管理員",
		["{item:3713}, for \"Swamp Eye\" Jarl"] = "{item:3713}，給「沼澤之眼」加爾",
		["{npc:3446} stands below Gazlowe's house by the flight master, towards the docks."] = "{npc:3446}站在飛行管理員旁加茲羅的房子下方，靠碼頭那一側。",
		["{npc:4503}, at the south edge of the village where the road comes in"] = "{npc:4503}，在村莊南緣、道路進村的地方",
		["{npc:6019} waits at the goblin camp on the west side of the {area:596}."] = "{npc:6019}在{area:596}西側的哥布林營地等候。",
		["{object:20985}, beside the manor"] = "{object:20985}，在莊園旁",
		["{object:20985}, now that {npc:4791} has read the report"] = "{object:20985}，現在{npc:4791}已經讀過報告了",
		["{zone:1454} flight master"] = "{zone:1454}的飛行管理員",
} end)()
t.guides["forever/horde/30-40/05-arathi-highlands"] = (function() return {
		["Back to {area:321}"] = "返回{area:321}",
		["Below ground"] = "地下",
		["Fleshstalker raptors"] = "獵獸龍",
		["Fly to {area:272}"] = "飛往{area:272}",
		["Highland Fleshstalkers (36-37) hunt the southern highlands, a pack north of {area:316} and another on the plain to its west. Pull them one at a time."] = "高地獵獸龍（36-37級）在南部高地獵食，一群在{area:316}北邊，另一群在它西邊的平原上。一次拉一隻。",
		["The Boulderfist Brutes camp outside the ogres' hall, far south-west of {area:321}; the Magus stand among them. Pull them one at a time."] = "石拳蠻兵在{area:321}西南方遠處的巨魔大廳外紮營；石拳法師站在他們之間。一次拉一隻。",
		["The inner circle lies south of the western circle, east of Stromgarde."] = "內圈法陣在西邊法陣的南邊、激流堡的東邊。",
		["The {object:138492}"] = "{object:138492}",
		["The {object:2690}"] = "{object:2690}",
		["The {object:2691}"] = "{object:2691}",
		["The {object:2701} lie at the far end of the gorge."] = "{object:2701}在峽谷的最深處。",
		["The {object:2702}"] = "{object:2702}",
		["Train while you are in the {zone:1458}: the trainers stand in the {object:36070}, the {object:36073} and the {object:36082} (Paladins: {npc:260093})."] = "趁你在{zone:1458}時學習：訓練師都在{object:36070}、{object:36073}和{object:36082}（聖騎士：{npc:260093}）。",
		["Underwater"] = "在水下",
		["West of the cove the Daggerspine Raiders and Sorceresses (38-40) hold the shore: pull them one at a time. The two wrecks lie in the shallows off it, the charts and logs inside them; the gems lie on the sea floor around the wrecks."] = "在海灣西邊，刺脊襲擊者和刺脊巫師（38-40級）佔據海岸：一次拉一隻。兩艘沉船在外海的淺水中，海圖和航海日誌在船裡；寶石散落在沉船周圍的海底。",
		["Zeppelin to {zone:1458}"] = "搭飛艇前往{zone:1458}",
		["{npc:270038} stands in the Apothecarium."] = "{npc:270038}站在皇家藥劑師協會。",
		["{npc:270038}: Stormheart's heart from {zone:1441}"] = "{npc:270038}：{zone:1441}的風暴之心的心臟",
		["{npc:2792}, by the gate"] = "{npc:2792}，在大門旁",
		["{zone:1458} trainers"] = "{zone:1458}的訓練師",
} end)()
t.guides["forever/horde/30-40/06-badlands"] = (function() return {
