} end)()
t.guides["forever/horde/40-50/01-stranglethorn-vale"] = (function() return {
		["Draenethyst crystals"] = "德萊尼水晶",
		["Fly to the {area:1497}"] = "飛往{area:1497}",
		["Fly to {area:35}"] = "飛往{area:35}",
		["Fly to {object:3202}"] = "飛往{object:3202}",
		["Follow the road east from {zone:1431} through {zone:1430} into the swamp. {npc:1776} waits at the {area:657}, the draenei camp just off the road where it comes in from {zone:1430}."] = "沿道路從{zone:1431}向東穿過{zone:1430}進入沼澤。{npc:1776}在{area:657}等著，那是道路從{zone:1430}進來處旁邊的德萊尼營地。",
		["Further north, the goblins of the Venture Co. dig at the mine east of the road; miners, foremen, surveyors and tinkerers all drop the crystals.\nCareful: Stealthed Shadowmaw Panthers and Stranglethorn Tigresses roam the area around the camp."] = "再往北，風險投資公司的哥布林在道路東邊的礦坑挖掘；礦工、工頭、勘探員和修理工都會掉落水晶。\n小心：潛行中的影喉黑豹和荊棘谷母虎在營地周圍遊蕩。",
		["Gringer, the flight master, waits on {area:35}'s upper deck. The quest givers stand on the boardwalks around the harbour and in the inn."] = "飛行管理員格林格在{area:35}的上層平台等著。任務給予者站在港口周圍的木棧道上和旅店裡。",
		["Head east to {area:75}, in the reeds south of the road."] = "向東前往道路南邊蘆葦叢中的{area:75}。",
		["Head north up the road to the hunters' camp."] = "沿道路向北走到獵人營地。",
		["Head north up the road; the hunters camp on the hill above the river."] = "沿道路向北走；獵人在河流上方的山丘上紮營。",
		["Head south to {area:35}. Shaky Phillipe waits on the docks."] = "向南前往{area:35}。「病鬼」菲力浦在碼頭上等著。",
		["Head west to {object:3202}."] = "向西前往{object:3202}。",
		["His strongbox waits at his old camp north of {area:75}, on the way back west."] = "他的保險箱在{area:75}北邊他的舊營地，就在往西回去的路上。",
		["Into the {zone:1435}"] = "進入{zone:1435}",
		["Jungle Stalkers"] = "叢林捕獵者",
		["Jungle stalkers"] = "叢林捕獵者",
		["Leave town by the tunnel; the note lies in the pirates' cove just north of {area:35}."] = "從隧道出城；字條在{area:35}北邊不遠的海盜海灣裡。",
		["Mistvale gorillas"] = "迷霧谷猩猩",
		["Nesingwary's camp"] = "奈辛瓦里的營地",
		["Noboru wanders the clearing south-west of the {area:76}; his cudgel starts a quest."] = "木棒諾博魯在{area:76}西南方的空地遊蕩；他的木棒會開啟一個任務。",
		["Riding at 40"] = "40級騎術",
		["Riding needs level 40 and costs 100 gold; learning it gives you a mount. Each race learns it from its own race's trainer: yours is {npc:4773} in {area:159}, a short ride north of the zeppelin towers, with {npc:4731}'s skeletal horses (20 gold each) beside her. Ride back to the towers for the {object:3202} zeppelin."] = "騎術需要40級，花費100金幣；學會後會得到一匹坐騎。每個種族都向自己種族的訓練師學習：你的是{area:159}的{npc:4773}，從飛艇塔往北騎一小段就到，旁邊是{npc:4731}的骷髏馬（每匹20金）。之後騎回飛艇塔，搭乘前往{object:3202}的飛艇。",
		["Sawtooth crocolisks"] = "鹽齒鱷魚",
		["Skeletal horses: {npc:4731}, beside {npc:4773} in {area:159}."] = "骷髏馬：{npc:4731}，在{area:159}的{npc:4773}旁邊。",
		["Skullsplitter warriors"] = "劈顱戰士",
		["The Bloodsail ships"] = "血帆海盜船",
		["The crocolisks wallow in the pools around {npc:5391}'s camp and south towards {area:75}; about one in four drops a flank."] = "鹽齒鱷魚在{npc:5391}營地周圍和往南到{area:75}的水池中打滾；約四隻有一隻掉落側腹肉。",
		["The next trophy skulls stand in the small ruins just north of the warriors' camp.\nThe last skulls are in the ruins a short walk west, on the way back to {object:3202}."] = "下一批祖瑪維顱骨堆在劈顱戰士營地北邊不遠的小廢墟中。\n最後一批顱骨在往西走一小段的廢墟裡，就在回{object:3202}的路上。",
		["Venture Co. mine"] = "風險投資公司礦坑",
		["Your level 40 training is in the {area:1497}: fly there from {area:340}, train, and take the zeppelin from the towers outside the city to {object:3202}."] = "你的40級訓練在{area:1497}：從{area:340}飛過去，學習技能，然後從城外的飛艇塔搭飛艇前往{object:3202}。",
		["Zeppelin to {object:3202}"] = "搭飛艇前往{object:3202}",
		["Zul'Kunda"] = "祖昆達廢墟",
		["Zul'Mamwe"] = "祖瑪維廢墟",
		["for a later stop in the {zone:1435}"] = "留待之後在{zone:1435}的一站",
		["the {area:16550}'s entrance, underwater"] = "{area:16550}的入口，在水下",
		["the {object:2076}, beside {npc:2497}"] = "{object:2076}，在{npc:2497}旁邊",
		["{area:1497} trainers"] = "{area:1497}訓練師",
		["{area:340} flight master"] = "{area:340}飛行管理員",
		["{npc:2495}, inside: the {item:4105}"] = "{npc:2495}，在屋內：{item:4105}",
		["{npc:2495}: the {npc:2635} suns on the coast between Zul'Kunda and {object:3202}, later on this loop"] = "{npc:2495}：{npc:2635}在祖昆達廢墟和{object:3202}之間的海岸上曬太陽，在這趟路線稍後會遇到",
		["{npc:2496}, on the balcony beside MacKinley"] = "{npc:2496}，在麥金利旁邊的陽台上",
		["{npc:2497}: for the {zone:1425}, around level 48"] = "{npc:2497}：給{zone:1425}，約48級",
		["{npc:2519}: the cavern entrance under the {area:104}, west of the camp"] = "{npc:2519}：洞穴入口在營地西邊的{area:104}底下",
		["{npc:4631}, on the docks: Gazlowe's letter, if you carry it"] = "{npc:4631}，在碼頭上：如果你帶著加茲魯維的信",
		["{npc:4773}, riding trainer"] = "{npc:4773}，騎術訓練師",
		["{npc:5391} is held in the {area:76} in the swamp's north-east. Free him and follow him out, fighting off the swamp creatures that chase him."] = "{npc:5391}被關在沼澤東北部的{area:76}。釋放他並跟著他出去，擊退追趕他的沼澤生物。",
		["{npc:716} collects the pages of {quest:338}: the trolls of the vale drop them now and then. Take his quest; each chapter he takes once you have all its pages."] = "{npc:716}收集{quest:338}的書頁：谷中的食人妖偶爾會掉落。接下他的任務；每一章在你湊齊所有書頁後交給他。",
		["{npc:716}: every page of chapter I is in your bags"] = "{npc:716}：第一章的每一頁都在你的背包裡",
		["{npc:716}: every page of chapter II is in your bags"] = "{npc:716}：第二章的每一頁都在你的背包裡",
		["{npc:716}: every page of chapter III is in your bags"] = "{npc:716}：第三章的每一頁都在你的背包裡",
		["{npc:716}: every page of chapter IV is in your bags"] = "{npc:716}：第四章的每一頁都在你的背包裡",
		["{npc:716}: the four chapters"] = "{npc:716}：四個章節",
		["{quest:95770}: west of {object:3202}, swim out over the {area:104} and dive to the cavern entrance in the reef; the quest completes as you find it. Leave the cavern for now: the jungle stalkers are south along the coast."] = "{quest:95770}：在{object:3202}西邊，游到{area:104}上方，潛到礁石中的洞穴入口；找到時任務就會完成。先別進洞穴：叢林捕獵者在沿海岸往南的地方。",
} end)()
t.guides["forever/horde/40-50/02-feralas"] = (function() return {
		["Coming from the {zone:2548}: {area:340}'s flight master stands at the foot of the fortress."] = "從{zone:2548}過來：{area:340}的飛行管理員站在要塞腳下。",
		["Flown in: {area:976}'s quests first, by the flight master, then the {area:2240} is a short ride north over the {zone:1446} border."] = "飛抵後：先做{area:976}飛行管理員旁的任務，然後越過{zone:1446}邊界往北騎一小段就到{area:2240}。",
		["Fly to {area:1638}"] = "飛往{area:1638}",
		["Fly to {area:484}"] = "飛往{area:484}",
		["Fly to {area:976}"] = "飛往{area:976}",
		["Fly to {object:3202}"] = "飛往{object:3202}",
		["For your {area:978} run, in the next guide: {quest:2864} wants scarab shells, and {npc:7804}, a short walk from the flight master, {quest:3042} from the Sandfury trolls."] = "為了你在下一份指南中的{area:978}之行：{quest:2864}要聖甲蟲殼，離飛行管理員不遠的{npc:7804}要沙怒食人妖身上的{quest:3042}。",
		["Grimtotem camp"] = "恐怖圖騰營地",
		["Kodos: {npc:3685}, beside {npc:3690} in {area:222}."] = "科多獸：{npc:3685}，在{area:222}的{npc:3690}旁邊。",
		["North of the gnolls the ogres hold a hilltop outpost; pull the ogre-magi to you. The cobalt is in the dirt mounds around the outpost, and the scroll lies on the ground inside it.\nCareful: {npc:222233} (level 43, elite) stands in the outpost: pull the ogres out to you, away from him."] = "在豺狼人北邊，巨魔佔據山頂的前哨站；把巨魔法師拉過來打。鈷礦在前哨站周圍的土堆裡，卷軸就在前哨站裡的地上。\n小心：{npc:222233}（43級，精英）站在前哨站裡：把巨魔拉出來，遠離他。",
		["Raptors: Zjolnir, beside {npc:7953} in {area:367}."] = "迅猛龍：祖尼爾，在{area:367}的{npc:7953}旁邊。",
		["Ride north-east to the goblin harbour on the coast."] = "向東北騎往海岸上的哥布林港口。",
		["Riding and Galestriders: {npc:265756}, at the {area:17684} in {area:16638} on Zephras Isle."] = "騎術與逐風者：{npc:265756}，在微風島{area:16638}的{area:17684}。",
		["Riding at 40"] = "40級騎術",
		["Riding needs level 40 and costs 100 gold; learning it gives you a mount. Each race learns it from its own race's trainer: yours is {npc:3690} in {area:222}, with {npc:3685}'s kodos (20 gold each) beside him. Ride back up to {zone:1456}'s flight master afterwards."] = "騎術需要40級，費用100金；學會後會得到一匹坐騎。每個種族都向自己種族的訓練師學習：你的訓練師是{area:222}的{npc:3690}，{npc:3685}的科多獸（每隻20金）就在他旁邊。之後騎回{zone:1456}的飛行管理員那裡。",
		["Riding needs level 40 and costs 100 gold; learning it gives you a mount. {npc:4752} teaches Orcs in the {object:172958}, by {npc:3362}'s kennel. Skyborne learn it from {npc:265756} at the {area:17684} in {area:16638} on Zephras Isle, with a Galestrider: the skyboat to the isle leaves the cliffs south of {area:17045}, north of {zone:1456}, about every five minutes. Your race's other mounts are 20 gold each: Collectibles, Mounts · Level 40 has a guide for each."] = "騎術需要40級，費用100金；學會後會得到一匹坐騎。{npc:4752}在{object:172958}教導獸人，位於{npc:3362}的狼舍旁。天裔精靈向微風島{area:16638}的{area:17684}的{npc:265756}學習，並得到一隻逐風者：前往島上的天空船約每五分鐘從{zone:1456}北邊、{area:17045}南側的懸崖出發。你種族的其他坐騎每匹20金：收藏品的「坐騎 · 40級」每一匹都有指南。",
		["The Grimtotem tauren camp beside the sprite darters' grove; raiders, naturalists and shamans all carry horns.\nCareful: {npc:222286} (level 43, elite) stands in the camp: pull the raiders and shamans away from her."] = "恐怖圖騰牛頭人在小精龍的樹林旁紮營；恐怖圖騰襲擊者、博學者和薩滿都帶著角。\n小心：{npc:222286}（43級，精英）站在營地裡：把襲擊者和薩滿從她身邊拉開。",
		["The Woodpaw gnolls camp in the hills just north-west of Mojache; any of them can drop a mane.\nCareful: Every Woodpaw gnoll except the Alpha runs off for help at 15% health, which can pull more gnolls into the fight."] = "木爪豺狼人在莫沙徹營地西北方的山丘上紮營；他們每一個都可能掉落鬃毛。\n小心：除了突擊隊員以外，每個木爪豺狼人血量降到15%時都會跑去求援，可能把更多豺狼人引進戰鬥。",
		["The battle map lies in the Woodpaw camp south of Mojache."] = "戰鬥地圖在莫沙徹營地南邊的木爪營地裡。",
		["The sprite darters flit over the grove just west of Mojache; nearly every one drops a wing. The Woodpaw alphas lead the camps south-west of it: kill them within the hour.\nCareful: Most Alphas sit in small tent camps with 2-4 other gnolls that join the fight, and other gnolls patrol between the camps."] = "小精龍在莫沙徹營地西邊的樹林上空飛舞；幾乎每一隻都會掉落翅膀。木爪突擊隊員帶領著西南方的營地：在一小時內殺掉他們。\n小心：大多數突擊隊員待在小帳篷營地裡，身邊有2-4隻其他豺狼人會一起參戰，還有其他豺狼人在營地之間巡邏。",
		["Upstairs"] = "樓上",
		["Wolves: {npc:3362}, beside {npc:4752}."] = "狼：{npc:3362}，在{npc:4752}旁邊。",
		["Woodpaw battle map"] = "木爪戰鬥地圖",
		["Woodpaw north camp"] = "木爪北方營地",
		["Your trainer is in {zone:1456}: {npc:3033} (Druids) on {area:1639}, {npc:246344} (Paladins)."] = "你的訓練師在{zone:1456}：{npc:3033}（德魯伊）在{area:1639}，{npc:246344}（聖騎士）。",
		["Zeppelin to {zone:1454}"] = "搭飛艇前往{zone:1454}",
		["for {zone:1454}, around level 45"] = "給{zone:1454}，約45級時",
		["{area:340} flight master"] = "{area:340}飛行管理員",
		["{area:392} for the Felsteed"] = "前往{area:392}學地獄戰馬",
		["{area:976} flight master"] = "{area:976}飛行管理員",
		["{area:976} is the walled goblin town just past the {zone:1446} border."] = "{area:976}是剛過{zone:1446}邊界、有圍牆的哥布林城鎮。",
		["{npc:3690}, riding trainer"] = "{npc:3690}，騎術訓練師",
		["{npc:4752}, riding trainer"] = "{npc:4752}，騎術訓練師",
		["{npc:7953}, riding trainer"] = "騎術訓練師{npc:7953}",
		["{npc:8115}: for {zone:1454}, around level 45"] = "{npc:8115}：給{zone:1454}，約45級時",
		["{npc:8579}: the screechers live in {zone:1444}, on the next {zone:1444} visit"] = "{npc:8579}：尖嘯者住在{zone:1444}，下次造訪{zone:1444}時",
		["{quest:2863}: one hour from now"] = "{quest:2863}：從現在起一小時內",
		["{zone:1454} flight master"] = "{zone:1454}的飛行管理員",
} end)()
t.guides["forever/horde/40-50/03-feralas"] = (function() return {
		["Back east past {area:75}: the Atal'ai artifacts lie in the water and on the banks of the {quest:1424}."] = "向東經過{area:75}：阿塔萊的文物在{quest:1424}的水中和岸邊。",
		["Below ground"] = "地下",
		["Dragon caves"] = "龍穴",
		["Fly to {area:1099}"] = "飛往{area:1099}",
		["Fly to {area:75}"] = "飛往{area:75}",
		["Frayfeather hippogryphs"] = "亂羽角鷹獸",
		["Level 45.37"] = "等級45.37",
		["Murlocs of the Misty Reed"] = "蘆葦崗哨的魚人",
		["No flight path to {area:75} yet (the {zone:2548} skip the {zone:1435}): ride north-east from {object:3202} through {zone:1431} and {zone:1430} into the swamp, then east along the road to {area:75}, and learn its flight path."] = "還沒有{area:75}的飛行路線（{zone:2548}跳過了{zone:1435}）：從{object:3202}向東北騎，穿過{zone:1431}和{zone:1430}進入沼澤，再沿道路向東前往{area:75}，並學會那裡的飛行路線。",
		["Onyxia's eggs"] = "奧妮克希亞的蛋",
		["Rage Scar yetis"] = "狂暴的怒痕雪人",
		["Ride back north to Brackenwall."] = "向北騎回蕨牆村。",
		["Ride north-west to the {area:1108}; {npc:14637} waits on the dock."] = "向西北騎到{area:1108}；{npc:14637}在碼頭上等著。",
		["Ride west along the road; the scroll lies at the water's edge in the swamp's far west."] = "沿道路向西騎；卷軸在沼澤最西邊的水邊。",
		["Riding at 40"] = "40級騎術",
		["Riding needs level 40 and costs 100 gold; learning it gives you a mount. Each race learns it from its own race's trainer: yours is {npc:4773} in {area:159}, a short ride north of the zeppelin towers, with {npc:4731}'s skeletal horses (20 gold each) beside her. Ride back to the towers for the {object:3202} zeppelin."] = "騎術需要40級，花費100金幣；學會後會得到一匹坐騎。每個種族都向自己種族的訓練師學習：你的是{area:159}的{npc:4773}，從飛艇塔往北騎一小段就到，旁邊是{npc:4731}的骷髏馬（每匹20金）。之後騎回飛艇塔，搭乘前往{object:3202}的飛艇。",
		["Rogue Vale opens just north of {npc:14637}'s dock. Kill a {npc:5308}, use {item:10699} on its body before you loot it, then talk to the spirit that rises: it is friendly. Three spirits in all."] = "Rogue Vale就在{npc:14637}碼頭北邊不遠處。擊殺一隻{npc:5308}，拾取之前對屍體使用{item:10699}，然後和出現的靈魂對話：它是友善的。總共三個靈魂。",
		["Rogue Vale screechers"] = "遊蕩的山谷尖嘯者",
		["Sawtooth crocolisks"] = "鹽齒鱷魚",
		["Skeletal horses: {npc:4731}, beside {npc:4773} in {area:159}."] = "骸骨戰馬：{npc:4731}，在{area:159}的{npc:4773}旁邊。",
		["South of the vale the Frayfeather hippogryphs roost on the slopes; nearly every one drops sinew and metallic fragments."] = "山谷南邊，亂羽角鷹獸棲息在山坡上；幾乎每一隻都會掉落肌腱和金屬碎片。",
		["Sprite darters and forest walkers"] = "小精龍與森林漫遊者",
		["The Eggs of Onyxia lie in the dragon caves in the {area:511}'s south-east, guarded by the scalebanes; smash five."] = "奧妮克希亞的蛋在{area:511}東南部的龍穴中，由火鬃守衛看守；砸碎五個。",
		["The Marsh Murlocs live on the strand south of the post; the Inkspewers are along the shore east of it and the Flesheaters further west, around the huts on the western shore."] = "沼澤魚人住在哨站南邊的海灘；沼澤噴墨魚人在哨站東邊的岸邊，沼澤食腐魚人在更西邊、西岸的小屋周圍。",
		["The sprite darters flit over the grove just west of the camp and carry the {item:9589}; the Wandering Forest Walkers, a little further west, carry the Splintered Logs.\nCareful: a {npc:272401} (level 60) flies over the forest west of the camp: keep clear of it."] = "小精龍在營地西邊不遠的樹林上空飛舞，身上帶著{item:9589}；再往西一點的森林漫遊者身上帶著斷裂的原木。\n小心：一隻{npc:272401}（60級）在營地西邊的森林上空飛行：遠離牠。",
		["To {area:75}"] = "前往{area:75}",
		["Underwater"] = "在水下",
		["Zeppelin to {object:3202}"] = "搭飛艇前往{object:3202}",
		["Zeppelin to {zone:1458}"] = "搭飛艇前往{zone:1458}",
		["for the {npc:5598} in the {zone:1425}, around level 48"] = "之後給{zone:1425}的{npc:5598}，約48級",
		["for the {object:2555} in {zone:1445}, later in this guide"] = "之後在本指南中用於{zone:1445}的{object:2555}",
		["for the {zone:1425} owlbeasts, around level 48"] = "之後給{zone:1425}的梟獸，約48級",
		["the {object:2555}"] = "{object:2555}",
		["{area:1099} flight master"] = "{area:1099}飛行管理員",
		["{npc:2934}, on the way back to Zinge"] = "{npc:2934}，在回去找辛吉的路上",
		["{npc:4500}'s challenge, back in Brackenwall, needs a group of three. Alone, grind the Firemane scouts here on the {area:511}'s northern edge to level 45.37 before you ride back north, so you don't come back down for it. Or, with a group, run the {area:978} dungeon instead."] = "回到蕨牆村後，{npc:4500}的挑戰需要三人隊伍。單人的話，在騎回北邊之前，先在{area:511}北緣這裡刷火鬃斥候到45.37級，這樣就不用再下來一趟。或者，有隊伍的話，改去打{area:978}地城。",
		["{npc:4773}, riding trainer"] = "騎術訓練師{npc:4773}",
		["{npc:7825}, the {object:36126}"] = "{npc:7825}，{object:36126}",
		["{quest:7738}, a rare drop"] = "{quest:7738}，稀有掉落",
} end)()
t.guides["forever/horde/40-50/04-tanaris"] = (function() return {
		["Back north, just south of {area:976}, use the {item:8524} now: the two-hour timer starts. The Blisterpaw Hyenas, Glasshide Basilisks and Scorpid Hunters share the dunes here. Each can drop an untested sample: use it, and it either passes as an acceptable one or is lost. Keep killing until you have eight of each."] = "回到北邊，就在{area:976}南方，現在使用{item:8524}：兩小時的計時開始。水泡土狼、玻璃皮蜥蜴和蠍子獵手共同分布在這裡的沙丘上。每種都可能掉落未測試的樣本：使用它，它要麼通過成為合格的樣本，要麼就會損失。持續擊殺直到每種各有八個。",
		["Below ground"] = "地下",
		["Below ground: the plans, on the {area:1443}'s upper ledge"] = "地下：設計圖，在{area:1443}的上層岩架",
		["Dark Iron Lookouts"] = "黑鐵哨兵",
		["Fly to {area:976}"] = "飛往{area:976}",
		["For your {area:978} run, after {area:979}: {npc:7407}, by the water tower, wants his {quest:2768} back; {quest:2864} his scarab shells and Trenton Lighthammer Troll Temper, if you have not taken those yet."] = "為了你在{area:979}之後的{area:978}之行：水塔旁的{npc:7407}想要拿回他的{quest:2768}；如果你還沒接，{quest:2864}要他的聖甲蟲殼，特倫頓·輕錘要食人妖回火劑。",
		["From {area:16727}, ride into the {zone:1427} by its eastern pass, then west to the dig site. The {object:173265} stands at its southern end; the Dark Iron Geologists dig just north of it. Bring 15 {item:4306} (the Auction House sells it)."] = "從{area:16727}經由東邊的山口騎進{zone:1427}，然後向西前往挖掘場。{object:173265}在挖掘場南端；黑鐵地質學家就在它北邊挖掘。帶15塊{item:4306}（拍賣場有賣）。",
		["His next request needs the {item:10552} from elite cultists: leave it."] = "他的下一個請求需要精英教徒身上的{item:10552}：別管它。",
		["Keep the Model 4711-FTZ Power Source Bilgewhizzle gave you: it starts {quest:654}, a two-hour timer, so use it on the way back north from Scrimshank's hive."] = "保留比格維茲給你的4711-FTZ型能量源：它會開始{quest:654}，限時兩小時，所以在從謝申克的蟲巢往北回去的路上再使用。",
		["OOX-17/TN"] = "OOX-17/TN",
		["Only with the distress beacon: OOX-17/TN sits south-east of Scrimshank's hive. Escort it north to {area:977}; its reward waits with Oglethorpe in {area:35}.\nCareful: The escort has two ambushes. Three level 47 scorpids attack near the start. Near the end, by the beach, three Wastewander humans attack: one mage and two assassins, around level 44."] = "僅限持有定位器時：OOX-17/TN在謝申克蟲巢的東南方。護送它向北前往{area:977}；獎勵在{area:35}的奧格索普那裡等著。\n小心：護送途中有兩次伏擊。剛開始不久會有三隻47級的蠍子攻擊。接近終點的海灘旁，會有三名廢土人類攻擊：一名法師和兩名刺客，約44級。",
		["Only with the {item:11818}: back east to the {object:173265} at the dig site."] = "僅限持有{item:11818}時：向東回到挖掘場的{object:173265}。",
		["Ride north-west across the gorge; {area:1446} is the scaffolded camp in the north-west."] = "向西北騎過峽谷；{area:1446}是西北方搭著鷹架的營地。",
		["Scrimshank's gear"] = "謝申克的設備",
		["The Dark Iron Lookouts stand on the ridges around the sentry towers south of the Cauldron; about one in ten carries the {item:18960}."] = "黑鐵哨兵站在大熔爐南邊哨塔周圍的山脊上；大約十分之一帶有{item:18960}。",
		["The Dark Iron Steamsmiths work the furnaces in the middle of the Cauldron; half of them carry a {item:10551}, one in ten the {item:18959}. Slaves, Slavers and Taskmasters carry daggers too."] = "黑鐵鍛造師在大熔爐中央操作熔爐；一半帶有{item:10551}，十分之一帶有{item:18959}。奴隸工、奴隸販子和工頭也帶著匕首。",
		["The Steamsmiths' furnaces"] = "鍛造師的熔爐",
		["The {area:247}"] = "{area:247}",
		["The {object:179827} board"] = "{object:179827}告示板",
		["The {quest:2768}: {npc:7407}, by the water tower."] = "{quest:2768}：{npc:7407}，在水塔旁。",
		["The {quest:3042}: {npc:7804}, a short walk from the flight master."] = "{quest:3042}：{npc:7804}，離飛行管理員不遠。",
		["Use the {item:8524}"] = "使用{item:8524}",
		["West along the road south; {npc:7771} camps by the ruins at the {area:1938}. Put on his {item:9978}: it shows the buried ornaments, here and around the {area:983}."] = "沿著往南的道路向西走；{npc:7771}在{area:1938}的廢墟旁紮營。戴上他的{item:9978}：它會顯示埋在地下的飾品，在這裡和{area:983}周圍都有。",
		["West of Gadgetzan, use the {item:8584} beside the water hole in the troll camp."] = "在加基森西邊，於食人妖營地的水池旁使用{item:8584}。",
		["Your {area:978} scarab shells: {npc:7876}, beside the wind rider master."] = "你{area:978}的聖甲蟲殼：{npc:7876}，在雙足飛龍管理員旁邊。",
		["for {npc:7010} in {zone:1454}, around level 50"] = "交給{zone:1454}的{npc:7010}，大約50級",
		["the {item:8526} grows in the {zone:1425}, around level 48"] = "{item:8526}生長在{zone:1425}，大約48級",
		["the {object:173265}"] = "{object:173265}",
		["{area:1099} flight master"] = "{area:1099}飛行管理員",
		["{area:976} and the {zone:1427} at 46-48: the Wastewander camps, {npc:5955}'s escort and {area:1446}."] = "46-48級的{area:976}和{zone:1427}：廢土流浪者營地、{npc:5955}的護送和{area:1446}。",
		["{area:978} is a dungeon for a group of five; its quests here are level 45 to 47. Its gate lies about 400 yards north of the troll camp's water hole.\nInside: the Scarabs drop the shells, every Sandfury troll can drop {quest:3042}, and {npc:7604} carries the {quest:2768}."] = "{area:978}是五人地城；這裡的相關任務是45到47級。它的大門在食人妖營地水池北邊約400碼處。\n裡面：聖甲蟲會掉落甲殼，每個沙怒食人妖都可能掉落{quest:3042}，{npc:7604}身上帶著{quest:2768}。",
		["{item:11818}, a rare drop"] = "{item:11818}，稀有掉落",
		["{item:8623}, a rare drop"] = "{item:8623}，稀有掉落",
		["{npc:5955} waits in the valley. Walk him all the way to his wife {npc:6015} in {area:977}, north-east across the desert: stay close, slow down for him and fight off what attacks him. Do not mount or hearth out of his reach. {npc:8579} stands in the port too."] = "{npc:5955}在山谷裡等候。一路護送他向東北穿過沙漠，到{area:977}找他的妻子{npc:6015}：跟緊他，放慢速度配合他，擊退攻擊他的敵人。不要騎坐騎或用爐石離開他的範圍。{npc:8579}也在港口裡。",
		["{npc:5955}'s escort"] = "護送{npc:5955}",
		["{npc:7876}, beside the wind rider master"] = "{npc:7876}，在雙足飛龍管理員旁邊",
		["{quest:2768}: {npc:7604}, inside"] = "{quest:2768}：{npc:7604}，在裡面",
		["{quest:2865}: the Scarabs, inside"] = "{quest:2865}：聖甲蟲，在裡面",
		["{quest:3042}: the Sandfury trolls, inside"] = "{quest:3042}：沙怒食人妖，在裡面",
} end)()
t.guides["forever/horde/40-50/05-the-hinterlands"] = (function() return {
		["Back west to {area:350}; rangers and marksmen stay near the lodge, scouts and outrunners on the slopes south of it."] = "向西回到{area:350}；高原遊俠和高原神射手待在小屋附近，高原斥候和高原前鋒在小屋南邊的山坡上。",
		["East of the village, the violet flower grows in the hills."] = "村子東邊的丘陵上長著紫色水生菇。",
		["Fly to {area:272}"] = "飛往{area:272}",
		["Fly to {area:75}"] = "飛往{area:75}",
		["Follow the roads east across the {zone:1425} to the troll village on the eastern coast."] = "沿道路向東穿過{zone:1425}，前往東海岸的食人妖村落。",
		["Highvale"] = "高原精靈",
		["His next request, going on to the {area:355}, is for a group."] = "他的下一個要求是前往{area:355}，需要組隊。",
		["Huntsman Malkhor's skull lies on a pile below the Vilebranch ruins, his bones on a pile at the foot of {area:354}. The Vessels of Tainted Blood sit on the lower terraces, and {npc:14757} is held at the top. The trolls inside are elite: stay with your group and keep to the paths."] = "獵戶莫克霍爾的顱骨在邪枝廢墟下方的一堆東西上，他的骨頭在{area:354}山腳的另一堆上。污染之血之瓶放在下層平台，{npc:14757}被關在頂端。裡面的食人妖是精英：跟隊伍待在一起，走在小路上。",
		["No flight path to {area:75} yet: the arrow takes the quickest way there (by the {object:3202} flight and the road through {zone:1431} and {zone:1430}). Learn {area:75}'s flight path when you arrive."] = "還沒有{area:75}的飛行路線：箭頭會走最快的路線（搭飛往{object:3202}的班機，再走穿過{zone:1431}和{zone:1430}的道路）。抵達後學會{area:75}的飛行路線。",
		["North along the coast, {npc:14731}'s picnic basket is on the small island; a {npc:14748} guards it."] = "沿海岸向北，{npc:14731}的野餐籃在小島上；由一個{npc:14748}看守。",
		["OOX-09/HL"] = "OOX-09/HL",
		["Ride all the way west to the Wildhammer town of {area:348} and place the message by the well in its centre. The town is full of Alliance guards: get in, place it and get out."] = "一路向西騎到蠻錘矮人的城鎮{area:348}，把訊息放在鎮中央的井邊。鎮上滿是聯盟守衛：進去、放下、離開。",
		["Ride back north to the bloodmages."] = "向北騎回血法師那裡。",
		["Ride north-east from {area:272} into the {zone:1425} and east along the road; {npc:7801} camps on the hill south of the elves' {area:350}."] = "從{area:272}向東北騎進{zone:1425}，再沿道路向東；{npc:7801}在精靈的{area:350}南邊的山丘上紮營。",
		["Ride west out of {area:75} and south through the canyon into the {zone:1419}; the two bloodmages stand by the road just inside."] = "從{area:75}向西騎出，再向南穿過峽谷進入{zone:1419}；兩名血法師就站在入口處的道路旁。",
		["South of the lodge the Witherbark trolls hold their villages. Every one of them carries a skull: with twenty, use {item:15002} to make the Laden Pike, then plant it inside the village."] = "小屋南邊，枯木食人妖佔據他們的村落。每一隻身上都帶著頭骨：收集二十個後，使用{item:15002}製作尼姆布亞的長矛，然後插在村子裡。",
		["South-west again, the exile hides by the ruins of {area:353}."] = "再往西南，流放者躲在{area:353}的廢墟旁。",
		["South-west of the lake, the Vilebranch soothsayers hold the {area:355}, the troll temple south of the central hills. Qiaga and {npc:8636} (elite, 50) stand at its top: take the soothsayers on the lower steps.\nSouth-west, the Silvermane Howlers roam the hills east of the Witherbark villages."] = "在湖的西南方，邪枝占卜者佔據中部丘陵南邊的食人妖神廟{area:355}。守護者奇爾加和{npc:8636}（精英，50級）站在頂端：在下層階梯對付占卜者。\n往西南，銀鬃嚎叫者在枯木村莊東邊的丘陵上遊蕩。",
		["The Highvale elves camp around {area:350}. Burn the report, the notes and the records in their camps. {npc:7780} is held inside the lodge: lead him out and fight off the ambush on the way.\nCareful: Groups of about three elves ambush the escort, usually twice."] = "高原精靈在{area:350}周圍紮營。燒掉他們營地中的報告、筆記和紀錄。{npc:7780}被關在小屋裡：帶他出來，途中擊退伏擊。\n小心：每次約三名精靈伏擊護送，通常兩次。",
		["The bloodmages"] = "血法師",
		["The crates of {item:8684} lie around the abandoned Horde camp at {area:351}, among the oozes."] = "{item:8684}的箱子散落在{area:351}廢棄的部落營地周圍，在軟泥怪之間。",
		["The secret lies on the {area:307}, above the beach."] = "秘密在海灘上方的{area:307}。",
		["Their follow-ups ask for the same parts again for a buff item and pay no experience: leave them."] = "他們的後續任務要你再交一次同樣的材料換取增益物品，不給經驗值：不用理會。",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:7977} is a level 48 elite: most classes solo it at level 50, but you may need help. Skip it if you are alone: the route has you grind the XP back.\n{npc:7977} walks the shore below the {area:307}, from the arrow south to about 75,66 and north to about 82,52: if she isn't at the arrow, follow the shore."] = "這些是精英怪：建議組隊，找人一起打。{npc:7977}是48級精英：大多數職業在50級時可以單刷，但你可能需要幫忙。如果你是獨自一人就跳過：本路線會讓你把經驗值刷回來。\n{npc:7977}沿著{area:307}下方的海岸行走，從箭頭處向南到約75,66，向北到約82,52：如果她不在箭頭處，就沿著海岸找。",
		["To {area:75}"] = "前往{area:75}",
		["Underwater"] = "在水下",
		["for {npc:6986} in {zone:1454}, around level 50"] = "之後給{zone:1454}的{npc:6986}，約50級",
		["for {npc:7825} in the {zone:1458}, around level 50"] = "之後給{zone:1458}的{npc:7825}，約50級",
		["{area:1446} flight master"] = "{area:1446}飛行管理員",
		["{area:348} well"] = "{area:348}的井",
		["{item:8704}, a rare drop"] = "{item:8704}，稀有掉落",
		["{npc:14731}'s lunch"] = "{npc:14731}的午餐",
		["{npc:14757}, at the top of {area:354}"] = "{npc:14757}，在{area:354}頂端",
		["{npc:7801}'s camp"] = "{npc:7801}的營地",
} end)()
t.guides["forever/horde/40-50/06-azshara"] = (function() return {
		["Back to {area:1099}"] = "返回{area:1099}",
		["Back to {npc:11548} at the shrine; stay west of the {area:3137} guards."] = "回到神殿的{npc:11548}處；待在{area:3137}守衛的西邊。",
		["Back to {object:3202}"] = "返回{object:3202}",
		["Below ground"] = "地下",
		["Class trainer"] = "職業訓練師",
		["Fly to {area:1099}"] = "飛往{area:1099}",
		["Fly to {area:1637}"] = "飛往{area:1637}",
		["Fly to {area:1638}"] = "飛往{area:1638}",
		["Fly to {area:35}"] = "飛往{area:35}",
		["Fly to {area:976}"] = "飛往{area:976}",
		["Fly to {object:3202}"] = "飛往{object:3202}",
		["Follow the road north to {area:1237}, the Horde camp."] = "沿著道路向北前往部落營地{area:1237}。",
		["Frayfeather Hippogryphs"] = "亂羽角鷹獸",
		["Hippogryph nests"] = "角鷹獸巢穴",
		["Keep {quest:3444}: {npc:7771}'s chest is opened on a later visit."] = "保留{quest:3444}：{npc:7771}的箱子要在下次造訪時打開。",
		["Ride east along the road out of Splintertree. {npc:11548} waits at the {area:1235} just off the road, a few steps west of the Alliance's {area:3137}: come in from the west and keep clear of the Azshara Sentinels and Jarrodenus (elite)."] = "沿著道路從碎木崗哨向東騎。{npc:11548}在路旁不遠的{area:1235}等候，位於聯盟{area:3137}西邊幾步遠：從西邊過去，避開艾薩拉哨兵和加羅迪努斯（精英）。",
		["Ride into {zone:1447}"] = "騎進{zone:1447}",
		["Ride south along the road to the {area:1938}; {npc:7771} camps beside it. From here the road west leads down into {zone:1449}, where the next guide starts."] = "沿著道路向南前往{area:1938}；{npc:7771}在旁邊紮營。從這裡往西的道路會下到{zone:1449}，下一份指南從那裡開始。",
		["Sprite Darters"] = "小精龍",
		["The Bloodsail ships"] = "血帆海盜船",
		["The Droffers' shop is a few steps further into the Drag."] = "德羅佛斯的商店在暗巷區再往裡走幾步。",
		["The Highborne ghosts haunt the ruins just north of the shrine; the Haldarr satyrs camp a little further north."] = "精靈貴族的鬼魂在神殿北邊的遺跡中出沒；哈達爾薩特在更北邊一點紮營。",
		["The Sea Elementals and Sea Sprays wash along the shore around the dock.\nThe Land Walkers and Cliff Giants roam the hills north of the dock. Zap each one with {item:18904} first: shrunken, they are no longer elite. Every zapped giant drops residue; use the Muisek Vessel on its body too."] = "海元素和巨型海元素在碼頭周圍的海岸邊漂流。\n大地行者和峭壁巨人在碼頭北邊的山丘上遊蕩。先用{item:18904}電擊每一隻：縮小後牠們就不再是精英。每個被縮小的巨人都會掉落殘渣；也對牠的屍體使用靈魂精華容器。",
		["The faerie dragons flit around the woods just west of the camp. Use the vessel on each one you kill."] = "精靈龍在營地西邊的樹林中飛舞。對你殺死的每一隻使用容器。",
		["The flight from {area:75} lands on {area:35}'s upper deck. {npc:7406} has his workshop on the upper ring of the bay."] = "從{area:75}起飛的航班降落在{area:35}的上層平台。{npc:7406}的工作室在海灣的上層環道。",
		["The hippogryph nests are on the hills to the south, around the {area:2522}; each holds an egg for the {object:142071}."] = "角鷹獸巢穴位於南邊的山丘上，在{area:2522}周圍；每個巢裡都有一顆要給{object:142071}的蛋。",
		["The hippogryphs nest on the hills south-west of the camp. Kill one, then use the Muisek Vessel on its body."] = "角鷹獸在營地西南方的山丘上築巢。殺一隻，然後對牠的屍體使用靈魂精華容器。",
		["The treants wander the forest roads between the camp and the middle of {zone:1444}; there are only a few, so look along the paths."] = "樹人在營地和{zone:1444}中部之間的林間道路上遊蕩；數量不多，沿著小路找找。",
		["The {object:142071}, in the middle of town"] = "{object:142071}，在城鎮中央",
		["Wandering Forest Walkers"] = "森林漫遊者",
		["Zeppelin to {zone:1454}"] = "搭飛艇前往{zone:1454}",
		["{area:1099} flight master"] = "{area:1099}飛行管理員",
		["{npc:5769}, on the {area:1639}"] = "{npc:5769}，在{area:1639}",
		["{npc:6746}, at the inn: for Hamuul"] = "{npc:6746}，在旅店：給哈繆爾",
		["{npc:6986}, the Drag"] = "{npc:6986}，在城裡",
		["{npc:7010}, the Drag"] = "{npc:7010}，暗巷區",
		["{npc:7010}, the Drag: if you still carry it"] = "{npc:7010}，暗巷區：如果你還帶著它",
		["{npc:7776}: the bears are in {zone:1448}"] = "{npc:7776}：熊在{zone:1448}",
		["{npc:7876}, beside the wind rider master"] = "{npc:7876}，在雙足飛龍管理員旁",
		["{zone:1454} flight master"] = "{zone:1454}的飛行管理員",
} end)()
t.guides["forever/horde/50-60/01-un-goro-crater"] = (function() return {
		["Back a few steps west to Felstone Farm, the first farm along the road; {npc:10778} waits in the house."] = "往西回走幾步到費爾斯通農場，也就是沿路的第一座農場；{npc:10778}在屋裡等候。",
		["Back north-east to {area:251}."] = "向東北回到{area:251}。",
		["Below ground"] = "地下",
		["Bridge into {area:254}"] = "通往{area:254}的橋",
		["Cross the south of the crater to the pylon on the western cliffs."] = "穿過環形山南部，前往西邊懸崖上的水晶塔。",
		["Eastern Pylon"] = "東部水晶塔",
		["Fly to {area:1637} and train before the boat to {area:16727}: the {zone:1458} stop later in this guide has no Hunter or Shaman trainer."] = "飛往{area:1637}，在搭往{area:16727}的船前先訓練：這份指南稍後在{zone:1458}的停留沒有獵人或薩滿訓練師。",
		["Follow the cliffs south to {quest:3821}, the Firegut ogres' hill. {npc:9136}'s remains lie at its foot."] = "沿著懸崖向南前往火腹巨魔的山丘{quest:3821}。{npc:9136}的遺骸在山腳下。",
		["For your {area:1584} run, next, on the way through {area:254}: the {object:164867} poster in {area:340} wants the Anvilrage dwarves inside thinned out."] = "為了你接下來的{area:1584}之行，在穿過{area:254}的路上：{area:340}的{object:164867}告示要你削減裡面的鐵怒矮人。",
		["From the {area:1938} ride west to the long ramp that winds down into {zone:1449}, then follow the crater's north wall to {area:541}, a camp in the cliff caves. Everyone here is neutral."] = "從{area:1938}向西騎到蜿蜒而下進入{zone:1449}的長坡道，然後沿著環形山北壁前往{area:541}，一個位於懸崖洞穴中的營地。這裡的所有人都是中立的。",
		["Gorillas"] = "猩猩",
		["Into the {zone:1427}"] = "進入{zone:1427}",
		["Into {zone:1449}"] = "進入{zone:1449}",
		["Keep {npc:10267}'s letter: {quest:4808} is in {area:2255}, {zone:1452}."] = "保留{npc:10267}的信：{quest:4808}在{zone:1452}的{area:2255}。",
		["Keep {npc:9118}'s {quest:4147} and {npc:8737}'s letter for later guides."] = "保留{npc:9118}的{quest:4147}和{npc:8737}的信，留給之後的指南。",
		["Lar'korwi Mates"] = "拉克維的配偶",
		["Lashers and Threshers"] = "血瓣花鞭笞者與猛擊者",
		["Leave the {zone:1458} and ride east along the road through {zone:1420} to the {area:152}, the Forsaken fort on the border."] = "離開{zone:1458}，沿著道路向東穿過{zone:1420}前往邊境上的被遺忘者要塞{area:152}。",
		["Northern Pylon"] = "北部水晶塔",
		["Out of the refuge"] = "離開避難營",
		["Power Crystals and soil"] = "能量水晶與土壤",
		["Ride down the east side of the crater to the pylon on the eastern cliffs."] = "沿著環形山東側往下騎到東邊懸崖上的水晶塔。",
		["Ride north along the east side. Bloodpetal Lashers and Threshers fill the jungle."] = "沿著東側向北騎。血瓣花鞭笞者和血瓣花猛擊者佈滿叢林。",
		["Scarlet forward camp"] = "血色十字軍前進營地",
		["Stegodons and ravasaurs"] = "劍龍與暴掠龍",
		["Take a {object:176092} from the crate next to Derrington for {quest:5096}, done on the way back. Equip the {quest:5405}: Scourgestones only drop while you wear it."] = "從德靈頓旁邊的箱子拿一個{object:176092}，用於{quest:5096}，在回程時完成。裝備{quest:5405}：只有穿戴時才會掉落天譴石。",
		["Take the pass out of {area:340}'s west side into the {zone:1427}, then ride south across the gorge to the long bridge into {area:254}. Inside, follow the chain walkways down and leave through the southern exit; stay off the paths to the dungeon portals."] = "從{area:340}西側的山口進入{zone:1427}，然後向南穿過峽谷，走長橋進入{area:254}。進去後沿著鐵鍊走道往下，從南側出口離開；不要走往地城傳送門的路。",
		["The Anvilrage dwarves of your {area:1584} run: {npc:9077}, in {area:340}."] = "你{area:1584}之行的鐵怒矮人：{npc:9077}，在{area:340}。",
		["The Lar'korwi Mates prowl the jungle north-west of {npc:9619}."] = "拉克維的配偶在{npc:9619}西北方的叢林中徘徊。",
		["The crystal clusters stand all over the crater, many around {area:537}. Take a few extra of each colour for the pylons."] = "水晶簇遍布整個環形山，許多在{area:537}周圍。每種顏色多拿幾個給水晶塔用。",
		["The expedition's crate sits at an abandoned camp in the eastern jungle."] = "探險隊的箱子在東部叢林中一處廢棄的營地裡。",
		["The expedition's lost equipment lies in the south-west jungle."] = "探險隊遺失的設備在西南方的叢林裡。",
		["The mountain lets you out beside {area:252}, full of 55-57 orcs. Follow the road east along the northern cliffs to the Horde camp at {area:251}."] = "出了山就在{area:252}旁邊，那裡滿是55-57級的獸人。沿著道路向東，沿北側懸崖前往{area:251}的部落營地。",
		["The pylon stands on the slope east of the refuge."] = "水晶塔位於避難營東邊的山坡上。",
		["The raft lies on the shore of the south-eastern lake; the small pack sits in the water beside it."] = "木筏在東南方湖泊的岸邊；小包就在旁邊的水裡。",
		["The {object:164867} poster"] = "{object:164867}告示",
		["Underwater"] = "在水下",
		["Upstairs"] = "樓上",
		["Use the Mangled Journal to start it"] = "使用被撕破的日記開始任務",
		["Western Pylon"] = "西部水晶塔",
		["{area:1584} is a dungeon for a group of five from about level 48, the biggest in the mountain: its Anvilrage dwarves are this quest's, and you need not go further in than they are. Its portal is deep inside the mountain, down the chain walkways from the bridge.\nInside: the Anvilrage Guardsmen, Wardens and Footmen. Then back out of the portal and on through the mountain's southern exit to the {zone:1428}."] = "{area:1584}是五人地城，約48級起，是山中最大的地城：這個任務的目標是它的鐵怒矮人，你不必深入到比牠們更裡面的地方。傳送門在山的深處，從橋沿著鎖鏈走道往下走。\n裡面：鐵怒衛兵、鐵怒看守者和鐵怒步兵。然後從傳送門出來，繼續從山的南側出口前往{zone:1428}。",
		["{area:340} flight master"] = "{area:340}飛行管理員",
		["{area:340} is built into the cliffs on the {zone:1418}' west edge."] = "{area:340}建在{zone:1418}西緣的懸崖中。",
		["{item:11116}, a rare drop"] = "{item:11116}，稀有掉落",
		["{npc:10879}, the {object:36078}, beside the bat master"] = "{npc:10879}，{object:36078}，在蝙蝠管理員旁邊",
		["{npc:7825} stands in the {object:36082}."] = "{npc:7825}站在{object:36082}。",
		["{npc:8390}, the Apothecarium: the vials fill in {zone:1447} later"] = "{npc:8390}，皇家藥劑師協會：瓶子稍後在{zone:1447}裝滿",
		["{npc:9117}, at the back of the cave; below ground"] = "{npc:9117}，在洞穴深處；在地下",
		["{npc:9618}, just outside"] = "{npc:9618}，就在外面",
		["{npc:9619} camps in the south-east corner of the crater."] = "{npc:9619}在環形山的東南角紮營。",
		["{npc:9623} then wants a {item:10561}, an {skill:202} item. Skip it unless you have one."] = "{npc:9623}接著會要一個{item:10561}，這是{skill:202}物品。除非你有，否則跳過。",
		["{npc:9623}, the robot on the plateau; below ground"] = "{npc:9623}，高地上的機器人；在地下",
		["{npc:9998}, at the entrance"] = "{npc:9998}，在入口",
		["{npc:9998}, at the refuge entrance"] = "{npc:9998}，在避難營入口",
		["{quest:3822} walks the caves and mine tunnels of {quest:3821}; if he isn't home, clear the ogres around the entrances until he comes back."] = "{quest:3822}在{quest:3821}的洞穴和礦坑隧道中走動；如果他不在，就清掉入口周圍的巨魔，直到他回來。",
		["{quest:4081}: the Anvilrage dwarves, inside"] = "{quest:4081}：鐵怒矮人，在裡面",
		["{zone:1454} flight master"] = "{zone:1454}的飛行管理員",
} end)()
t.guides["forever/horde/50-60/02-felwood"] = (function() return {
		["Back north to {area:1763}. Fill Greta's canteen at the corrupted moonwell in the middle of the southern camp."] = "向北回到{area:1763}。在南方營地中央的腐化月井裝滿葛瑞塔的水壺。",
		["Below ground"] = "地下",
		["Class trainer"] = "職業訓練師",
		["Diseased Wolves"] = "生病的狼",
		["Druid trainer"] = "德魯伊訓練師",
		["East of Bloodvenom Post, the cratered vale where the Entropic Beasts and Horrors roam. Kill two of each, then walk to each of the three fel-water craters."] = "在血毒崗哨東邊，熱能野獸和熱能恐獸遊蕩的坑窪山谷。各擊殺兩隻，然後走到三個魔化水坑的每一個。",
		["Follow the road north-west. The south of {area:1763}, around its corrupted moonwell, is held by Shadow Council cultists, adepts, guardsmen and their hounds."] = "沿著道路向西北走。{area:1763}南部的腐化月井周圍，由加德納爾祭司、加德納爾精兵、加德納爾守護者和加德納爾惡犬佔據。",
		["He camps by the {area:202}, south-east of {area:200}."] = "他在{area:200}東南方的{area:202}旁紮營。",
		["Keep {quest:5158}: {npc:5901} is in the {zone:1413}."] = "保留{quest:5158}：{npc:5901}在{zone:1413}。",
		["Keep {quest:8465} for {zone:1452}."] = "保留{quest:8465}，留到{zone:1452}。",
		["Northern crater"] = "北方坑洞",
		["Ride back south past {area:1763} to the corrupted moonwell of the Jadefire satyrs and fill {npc:9996}'s flasket there."] = "向南騎回去經過{area:1763}，前往碧火薩特的腐化月井，在那裡裝滿{npc:9996}的小瓶。",
		["Ride north up the road again."] = "再次沿著道路向北騎。",
		["Ride south-west past Felstone Farm and follow the road west back to the {area:152}."] = "向西南騎過費爾斯通農場，沿著道路向西回到{area:152}。",
		["Ride the road south through {zone:1448} to the Sanctuary."] = "沿著道路向南穿過{zone:1448}前往聖地。",
		["Ror stands at the far south end of {area:1761}."] = "洛爾站在{area:1761}的最南端。",
		["Southern crater"] = "南方坑洞",
		["Southern {area:1763}"] = "{area:1763}南部",
		["Step into the cave: {npc:11558} stands just inside."] = "走進洞穴：{npc:11558}就站在入口內。",
		["Take the kitten to the same moonwell and release it there with {item:12565}; once it has turned into a {npc:10042}, bring it back to {npc:9996} and click on it to hand it over."] = "把小貓帶到同一個月井，用{item:12565}在那裡放出牠；牠變成{npc:10042}後，把牠帶回給{npc:9996}，點擊牠來交給她。",
		["The Deadwood furbolg village just west of the tunnel. {npc:9462} (56) stands among them. {npc:11557}, a friendly furbolg, sits at the north end of the village."] = "就在隧道西邊的死木熊怪村莊。{npc:9462}（56級）站在牠們之中。友善的熊怪{npc:11557}坐在村莊北端。",
		["The Horde camp just north of {area:1763}."] = "{area:1763}北邊的部落營地。",
		["The Jadefire moonwell"] = "碧火月井",
		["The diary lies in the farmhouse, the cabinet stands inside and the outhouse is behind it. A {npc:10816} carries the outhouse key; {npc:10836} comes out when you open the outhouse and carries the cabinet key."] = "日記在農舍裡，櫃子在屋內，廁所在屋後。一隻{npc:10816}帶著廁所鑰匙；打開廁所時{npc:10836}會出來，他身上帶著櫃子鑰匙。",
		["The druids' camp is just past the border."] = "德魯伊的營地就在邊界過去一點。",
		["The road ends at {npc:15395}, outside the {area:1769} tunnel in the far north-east."] = "道路盡頭是{npc:15395}，在東北角的{area:1769}隧道外。",
		["The {area:1763} moonwell"] = "{area:1763}月井",
		["Western crater"] = "西方坑洞",
		["Zeppelin to {zone:1454}"] = "搭飛艇前往{zone:1454}",
		["{area:200} farmhouse"] = "{area:200}農舍",
		["{item:12565}, at the Jadefire moonwell"] = "{item:12565}，在碧火月井",
		["{npc:10306}: the owlbeasts are in {zone:1452}"] = "{npc:10306}：梟獸在{zone:1452}",
		["{npc:11554}, at the south edge of the camp"] = "{npc:11554}，在營地南緣",
		["{npc:11557}: keep 30 {quest:6031} for him; he trades only at Neutral with the Timbermaw; below ground"] = "{npc:11557}：為他保留30塊{quest:6031}；他只在木喉聲望達到中立時才交易；在地下",
		["{npc:11558}: the Timbermaw speak to you only from Neutral; walks around here: look inside the circle on the map"] = "{npc:11558}：木喉熊怪只有在中立以上才會和你說話；會在這附近走動：在地圖上的圓圈內找他",
		["{npc:8659} takes the ravasaur claws from Un'Goro; he stands in the {object:172960}, a short walk from the middle of the city."] = "{npc:8659}收下安戈洛的恐龍爪；他站在{object:172960}，從城市中央走一小段路就到。",
		["{npc:8659}, the {object:172960}"] = "{npc:8659}，{object:172960}",
		["{npc:9529}, on the west side of the Sanctuary"] = "{npc:9529}，在聖地西側",
		["{npc:9529}, on the west side of the camp"] = "{npc:9529}，在營地西側",
		["{npc:9996}'s kitten"] = "{npc:9996}的小貓",
		["{zone:1454} flight master"] = "{zone:1454}的飛行管理員",
} end)()
t.guides["forever/horde/50-60/03-winterspring"] = (function() return {
		["Back south to {npc:7775}. Keep the elixir and don't drink it yet: it kills you, and that is how you meet Gaeriyan by {area:976} later."] = "往南回到{npc:7775}那裡。留著藥劑，先別喝：喝了會死，而這正是之後在{area:976}附近見到蓋瑞恩的方法。",
		["Chillwind chimaeras"] = "冰風奇美拉",
		["Fly to {area:1099}"] = "飛往{area:1099}",
		["Fly to {area:1637}"] = "飛往{area:1637}",
		["Fly to {area:1638}"] = "飛往{area:1638}",
		["Gregor's quests lead to other zones: keep them."] = "格雷戈的任務會通往其他地區：保留它們。",
		["Ice Thistle yetis"] = "冰薊雪人",
		["In the {object:172958}."] = "在{object:172958}。",
		["Linken's letter"] = "林克的信",
		["Raging Owlbeasts"] = "狂怒的梟獸",
		["Ride south from the tunnel: {npc:9298} camps among the steaming pools of {area:2246}, in the west of the valley."] = "從隧道向南騎：{npc:9298}在山谷西部{area:2246}冒著蒸氣的池塘之間紮營。",
		["The chimaeras roam the snowfields south and west of {area:2255}. Stay clear of {area:2245}'s cave: its blue dragonkin are elite."] = "奇美拉在{area:2255}南邊和西邊的雪原上遊蕩。避開{area:2245}的洞穴：裡面的藍龍是精英。",
		["The {item:11242} grows inside a ruined building north of {npc:7775}'s camp, east of the harpies' {area:1114}: climb in through the broken part of its wall."] = "{item:11242}生長在{npc:7775}營地北邊、鷹身人的{area:1114}東邊一棟廢墟建築裡：從牆壁的破損處爬進去。",
		["{area:2255} is the goblin town on the east side of the valley, past the owlbeast hills."] = "{area:2255}是山谷東側的哥布林城鎮，經過梟獸丘陵就到。",
		["{area:2408} flight master"] = "{area:2408}的飛行管理員",
		["{item:11243}, {npc:7775}'s reward"] = "{item:11243}，{npc:7775}的獎勵",
		["{npc:11556} stands right at the {zone:1452} exit of {area:1769}'s tunnel, where you come out."] = "{npc:11556}就站在{area:1769}隧道的{zone:1452}出口，也就是你出來的地方。",
		["{npc:3033} on {area:1639}; {npc:246344}"] = "{area:1639}的{npc:3033}；{npc:246344}",
		["{quest:1123} waits in {zone:1450}: keep it for later."] = "{quest:1123}在{zone:1450}等著：保留到稍後。",
		["{quest:3909} comes from {npc:7775} in {zone:1444}, later in this guide."] = "{quest:3909}來自{zone:1444}的{npc:7775}，在本指南稍後。",
		["{quest:5084} is turned in at the {object:176091} in {zone:1448}, on a later trip."] = "{quest:5084}要在之後前往{zone:1448}時，到{object:176091}繳交。",
		["{quest:8471}, a rare drop from the Winterfall furbolgs"] = "{quest:8471}，冬泉熊怪的稀有掉落",
} end)()
