		["{npc:265810}: for {npc:3013}"] = "{npc:265810}：給{npc:3013}",
		["{npc:265810}: for {npc:3069}"] = "{npc:265810}：給{npc:3069}",
		["{npc:265810}: for {npc:5938}"] = "{npc:265810}：給{npc:5938}",
		["{npc:265810}: for {npc:5939}"] = "{npc:265810}：給{npc:5939}",
		["{npc:265810}: for {npc:6290}"] = "{npc:265810}：給{npc:6290}",
		["{npc:269068} wants tauren incense: buy its four parts from {npc:3014} the herbalist, {npc:3012} the enchanting supplier, {npc:3005} the leatherworking supplier and {npc:3027} the cooking supplier, then combine them into {item:278078}."] = "{npc:269068}想要牛頭人的薰香：向草藥商{npc:3014}、附魔供應商{npc:3012}、製皮供應商{npc:3005}和烹飪供應商{npc:3027}購買四種材料，然後合成{item:278078}。",
		["{npc:277182} stands at the north edge of the village. Kyle wants {item:287505} from plainstriders."] = "{npc:277182}站在村子北緣。Kyle想要從平原陸行鳥取得的{item:287505}。",
		["{npc:277182}, at the north end of the village"] = "{npc:277182}，在村子北端",
		["{npc:2948}, for Hamuul in {zone:1456}"] = "{npc:2948}，給{zone:1456}的大德魯伊哈繆爾·符文圖騰",
		["{npc:2984} stands at the edge of the {area:404}, south of the well."] = "{npc:2984}站在{area:404}邊緣，水井南邊。",
		["{npc:2991} sits by the tent on the camp's eastern edge; the {object:2907} stands next to her."] = "{npc:2991}坐在營地東緣的帳篷旁；{object:2907}就在她旁邊。",
		["{npc:2993}, for {npc:3057} in {zone:1456}"] = "{npc:2993}，給{zone:1456}的{npc:3057}",
		["{npc:3001} takes it once your {skill:186} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "你的{skill:186}技能達到20後，{npc:3001}就會接收它：在那之前先採集或製作，指南會同時繼續進行。",
		["{npc:3013} takes it once your {skill:182} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "你的{skill:182}技能達到20後，{npc:3013}就會接收它：在那之前先採集或製作，指南會同時繼續進行。",
		["{npc:3059}, the warrior trainer; inside"] = "戰士訓練師{npc:3059}；在裡面",
		["{npc:3060}, the druid trainer beside him"] = "他旁邊的德魯伊訓練師{npc:3060}",
		["{npc:3061}, the hunter trainer"] = "獵人訓練師{npc:3061}",
		["{npc:3062}, the shaman trainer in camp"] = "營地裡的薩滿訓練師{npc:3062}",
		["{npc:3063}'s quest: beat three Novice Warriors (or players in duels) next to him."] = "{npc:3063}的任務：在他旁邊擊敗三名新戰士（或在決鬥中擊敗玩家）。",
		["{npc:3065} stands at the north end of {area:222}. Tame with the {item:15908}: an {npc:2956} on the plains, a {npc:2959} north of the village, a {npc:2970} to the north-west."] = "{npc:3065}站在{area:222}北端。用{item:15908}馴服：平原上的一隻{npc:2956}、村子北邊的一隻{npc:2959}，以及西北方的一隻{npc:2970}。",
		["{npc:3069} takes it once your {skill:165} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "你的{skill:165}技能達到20後，{npc:3069}就會接收它：在那之前先採集或製作，指南會同時繼續進行。",
		["{npc:3069}, beside {npc:3067}: {quest:97934}"] = "{npc:3069}，在{npc:3067}旁邊：{quest:97934}",
		["{npc:3418} stands at {area:378}, where the road from {zone:1412} meets the {area:458} north to the Crossroads."] = "{npc:3418}站在{area:378}，也就是{zone:1412}來的道路與向北通往十字路口的{area:458}交會之處。",
		["{npc:3418}: for {npc:3429} at the Crossroads"] = "{npc:3418}：給十字路口的{npc:3429}",
		["{npc:3429}, by the wind rider tower"] = "{npc:3429}，在雙足飛龍塔旁",
		["{npc:3441}: for {quest:860} at the Crossroads"] = "{npc:3441}：給十字路口的{quest:860}",
		["{npc:3615}, the wind rider master"] = "雙足飛龍管理員{npc:3615}",
		["{npc:5769}: for {npc:3448} at the Crossroads"] = "{npc:5769}：給十字路口的{npc:3448}",
		["{npc:5888}: {npc:5873} and your {item:5175}"] = "{npc:5888}：{npc:5873}和你的{item:5175}",
		["{npc:5907} stands alone on the ridge above the Razormane camp, north-east of the Crossroads on the road to {area:379}."] = "{npc:5907}獨自站在鋼鬃營地上方的山脊上，在十字路口東北方、通往{area:379}的路上。",
		["{npc:5938} takes it once your {skill:356} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "你的{skill:356}技能達到20後，{npc:5938}就會接收它：在那之前先採集或製作，指南會同時繼續進行。",
		["{npc:5939} takes it once your {skill:129} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "你的{skill:129}技能達到20後，{npc:5939}就會接收它：在那之前先採集或製作，指南會同時繼續進行。",
		["{npc:6290} takes it once your {skill:393} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "你的{skill:393}技能達到20後，{npc:6290}就會接收它：在那之前先採集或製作，指南會同時繼續進行。",
		["{npc:6290}, beside {npc:3067}: {quest:97936}"] = "{npc:6290}，在{npc:3067}旁邊：{quest:97936}",
		["{npc:6746}: {quest:5926}, for {npc:3033} on {area:1639}"] = "{npc:6746}：{quest:5926}，給{area:1639}的{npc:3033}",
		["{npc:6775} stands at the west end of the camp, at the north-west corner of the hills where the Mountain Cougars prowl: take his quest, then hunt the cougars south through the hills towards the Seer's tent at their foot."] = "{npc:6775}站在營地西端，山獅出沒的丘陵西北角：接他的任務，然後往南穿過丘陵獵殺山獅，一路走向山腳下灰舌先知的帳篷。",
		["{quest:96130}, a lone wolf, prowls the plains west of the village. Prairie Stalkers and Flatland Cougars roam the plains north and west of it."] = "孤狼{quest:96130}在村子西邊的平原徘徊。草原捕食者和平原獅在村子北邊和西邊的平原遊蕩。",
} end)()
t.guides["forever/horde/troll/01-durotar"] = (function() return {
		["Armored Scorpids crawl over the plains west of {area:362}. Tame one, then return to {npc:3171}."] = "硬甲蠍在{area:362}西邊的平原上爬行。馴服一隻，然後回到{npc:3171}那裡。",
		["Back to the Den"] = "回到大獸穴",
		["Back to {area:362}."] = "回到{area:362}。",
		["Below ground"] = "地下",
		["Burning Blade cultists hold the caves of {quest:827}; any of them drops a {item:4871}. {npc:3204}, a level 14 warlock, stands deep inside and drops the {item:4903}.\nCareful: voidwalkers fight beside the Burning Blade cultists in {quest:827} and {npc:3204} (14) waits at the back with his own: pull one cultist at a time near the entrance for the collars. The {item:4903} is optional: leave {npc:3204} unless you are 13 or have a friend."] = "燃刃氏族的教徒佔據{quest:827}的洞穴；他們都會掉落{item:4871}。{npc:3204}是14級的術士，站在深處，會掉落{item:4903}。\n小心：在{quest:827}裡，虛空行者與燃刃氏族的教徒並肩作戰，{npc:3204}（14級）帶著他自己的虛空行者在最裡面等著：在入口附近一次拉一個教徒來收集項圈。{item:4903}是可選的：除非你已經13級或有朋友同行，否則別碰{npc:3204}。",
		["Class trainer"] = "職業訓練師",
		["Druid trainer"] = "德魯伊訓練師",
		["Felstalkers roam the slope below the cave, on the valley's north side."] = "地獄捕獵者在洞穴下方的山坡上遊蕩，位於山谷北側。",
		["Follow the road east out of the valley to {area:367} on the coast.\nCareful: Ukorsbane (8) is elite and walks among the Ridgeshade spiders in the camp south of {area:362}: pull the spiders away from him."] = "沿著道路向東離開山谷，前往海岸邊的{area:367}。\n小心：Ukorsbane（8級）是精英，在{area:362}南邊營地的Ridgeshade蜘蛛之間走動：把蜘蛛從他身邊拉開。",
		["Follow the road north from {area:379} to {zone:1454}'s main gate, just west of {area:817}. {npc:3352} stands with the hunter trainers in the {object:172958}."] = "沿著道路從{area:379}向北前往{zone:1454}的正門，就在{area:817}西邊。{npc:3352}和獵人訓練師們站在{object:172958}。",
		["Free {npc:275811} and see her safely out of the crag"] = "釋放{npc:275811}，並護送她安全離開峭壁",
		["Heal and fortify {npc:12430}"] = "治療{npc:12430}並為她施放耐力",
		["Inside the cave, go straight on at the first split, then right and follow the stream on your left to the waterfall: the pick glows by the water, behind a column of rock."] = "進入洞穴後，在第一個岔路直走，然後往右，沿著左手邊的溪流走到瀑布：鎬在水邊發光，在一根石柱後面。",
		["Inside the cave, keep to the right wall all the way round, over the stream: {npc:3183} waits at the end."] = "進入洞穴後，一路沿著右側牆壁繞行，越過溪流：{npc:3183}在盡頭等著。",
		["Misha's hut stands south of the lizards. The crocolisks along the {area:814} to the west carry {item:4891}."] = "米莎的小屋在蜥蜴的南邊。西邊{area:814}沿岸的鱷魚身上帶著{item:4891}。",
		["North-east to the beach below {area:370}, north of {npc:275657}: Spitelash Scouts and Attendants hold it. Hunters: tame a {npc:3107} on the beach."] = "向東北前往{area:370}下方、{npc:275657}北邊的海灘：惡鞭斥候和惡鞭侍從佔據那裡。獵人：在海灘上馴服一隻{npc:3107}。",
		["Spitelash naga"] = "惡鞭納迦",
		["Tame it with the {item:15908}"] = "用{item:15908}馴服牠",
		["The weapons lie around the Den and the training grounds; the Mottled Boars roam the whole valley floor."] = "武器散落在大獸穴和訓練場周圍；雜斑野豬在整個谷底遊蕩。",
		["The {object:58595} stands in {area:817}, among the cultists you just fought."] = "{object:58595}在{area:817}裡，就在你剛才打過的教徒之間。",
		["Thunder Lizards and Lightning Hides graze on {area:369}, beside the road north to {zone:1454}; any of them can drop a {item:6486}. {npc:5810} takes it when the next guide passes {area:379}.\nCareful: Halikor, a level 12 elite, roams {area:369} among the lizards: watch for him before you pull."] = "雷霆蜥蜴和閃電蜥蜴在{area:369}吃草，就在往北到{zone:1454}的路旁；任何一隻都可能掉落{item:6486}。下一篇指南經過{area:379}時，把它交給{npc:5810}。\n小心：12級精英哈利寇在{area:369}的蜥蜴群中遊蕩：拉怪前先留意他的位置。",
		["Thunder lizards on the way north"] = "北上途中的雷霆蜥蜴",
		["To {zone:1454}"] = "前往{zone:1454}",
		["Training weapons and boars"] = "訓練武器與野豬",
		["Underwater"] = "在水下",
		["Upstairs"] = "樓上",
		["Wade across to the northern Echo Isle. The Matriarch prowls among the raptors there; Durotar Tigers roam the isle and the shore south of Sen'jin."] = "涉水到北邊的回音群島。族母在那裡的迅猛龍之間徘徊；杜洛塔猛虎在島上以及森金村南邊的海岸遊蕩。",
		["Wake {quest:5441} with the {item:16114}"] = "用{item:16114}叫醒{quest:5441}",
		["the {object:654925} on the ground beside her"] = "她旁邊地上的{object:654925}",
		["{area:366} lies west of Sen'jin. The three attack plans sit on the ground among the centaur tents. {npc:275811} is held at the crag as well."] = "{area:366}在森金村西邊。三份進攻計畫放在半人馬帳篷之間的地上。{npc:275811}也被關在峭壁那裡。",
		["{area:817}'s mouth"] = "{area:817}入口",
		["{npc:10176}, where you start"] = "{npc:10176}，在你的出生點",
		["{npc:11025} takes it once your {skill:202} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "你的{skill:202}技能達到20後，{npc:11025}就會接收它：在那之前先採集或製作，指南會同時繼續進行。",
		["{npc:12430} kneels behind the rocks just off the road south of {area:362}, on your way to the keep. Cast {spell:613} (Rank 2) on her, then {spell:1243}: Rank 1 of {spell:613} does not count."] = "{npc:12430}跪在{area:362}南邊道路旁的岩石後面，就在你前往城堡的路上。對她施放{spell:613}（等級2），然後施放{spell:1243}：等級1的{spell:613}不算數。",
		["{npc:265809} camps just south of {area:362}. Sit by his campfire (/sit) until the {spell:1229451} buff appears. With a profession learned, {npc:265809} also offers its Camping 101, which its trainer takes: in {area:362} or in {zone:1454} at the start of the next guide."] = "{npc:265809}在{area:362}南邊紮營。坐在他的營火旁（/sit），直到出現{spell:1229451}增益效果。學會專業技能後，{npc:265809}也會提供該專業的露營入門任務，交給該專業的訓練師：在{area:362}或在{zone:1454}（下一份指南的開頭）。",
		["{npc:265809}'s campfire"] = "{npc:265809}的營火",
		["{npc:265809}: for {npc:11025}"] = "{npc:265809}：交給{npc:11025}",
		["{npc:265809}: for {npc:3175}"] = "{npc:265809}：交給{npc:3175}",
		["{npc:265809}: for {npc:5943}"] = "{npc:265809}：交給{npc:5943}",
		["{npc:266881}: enchanters only, the residue is disenchanted from Hexed Pendants"] = "{npc:266881}：僅限附魔師，殘渣要從妖術墜飾分解取得",
		["{npc:275657} stands on the shore east of {area:362}. The trident, banner and dagger lie on the beach around him."] = "{npc:275657}站在{area:362}東邊的岸上。三叉戟、旗幟和匕首散落在他周圍的海灘上。",
		["{npc:3102} hooves"] = "{npc:3102}的蹄子",
		["{npc:3142}, back in {area:362}"] = "{npc:3142}，回到{area:362}",
		["{npc:3142}: {npc:275666}, an elite sea giant"] = "{npc:3142}：{npc:275666}，一個精英海巨人",
		["{npc:3143} stands just inside the cave mouth; {npc:3159} at the back of the cave behind him."] = "{npc:3143}就站在洞口內；{npc:3159}在他身後的洞穴深處。",
		["{npc:3143} waits inside the Den, the building just west of {npc:10176}."] = "{npc:3143}在大獸穴裡等候，就是{npc:10176}西邊的那棟建築。",
		["{npc:3147}, in the watchtower"] = "{npc:3147}，在瞭望塔裡",
		["{npc:3175} takes it once your {skill:186} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "你的{skill:186}技能達到20後，{npc:3175}就會接收它：在那之前先採集或製作，指南會同時繼續進行。",
		["{npc:3287} lies wounded at the foot of the hills north-west of the Den."] = "{npc:3287}受傷躺在大獸穴西北方的山腳下。",
		["{npc:3294}, by the inn"] = "{npc:3294}，在旅店旁",
		["{npc:3706}, beside {npc:266940}: the {item:16606}"] = "{npc:3706}，在{npc:266940}旁邊：{item:16606}",
		["{npc:3706}, for {npc:6018} in {zone:1454}: keep it"] = "{npc:3706}，交給{zone:1454}的{npc:6018}：保留此任務",
		["{npc:3706}, in the barracks beside {npc:266940}"] = "{npc:3706}，在{npc:266940}旁邊的兵營裡",
		["{npc:3707}, the priest trainer at the Den"] = "{npc:3707}，大獸穴的牧師訓練師",
		["{npc:3707}, the priest trainer at the Den: for {npc:3706} in {area:362}"] = "{npc:3707}，大獸穴的牧師訓練師：交給{area:362}的{npc:3706}",
		["{npc:5875} stands in the {object:172960}, the canyon under the {object:172982}. Hand him the {item:6535}, then use the {item:7464} on the summoning circle beside him and defeat the voidwalker to bind it.\nCareful: the voidwalker you summon hits hard and it is the fight Warlocks die to most in {zone:1454}: start at full health and mana, send your imp in, keep Corruption and Immolate on it, and use a healthstone if you have one."] = "{npc:5875}站在{object:172960}，也就是{object:172982}下方的峽谷。把{item:6535}交給他，然後在他旁邊的召喚法陣使用{item:7464}，擊敗虛空行者以束縛它。\n小心：召喚出的虛空行者攻擊很痛，這是術士在{zone:1454}最常陣亡的一場戰鬥：滿血滿魔再開始，先派小鬼上去，在牠身上保持腐蝕術和獻祭，有治療石就用。",
		["{npc:5887} stands outside the Den. {area:639} is the hill just south of it: drink the {item:6635} there to see the {npc:5891}, then take the {item:6656} back to {npc:5887}."] = "{npc:5887}站在大獸穴外。{area:639}就是它南邊的山丘：在那裡喝下{item:6635}以看見{npc:5891}，然後把{item:6656}帶回給{npc:5887}。",
		["{npc:5887}: {npc:5873} and your {item:5175}"] = "{npc:5887}：{npc:5873}和你的{item:5175}",
		["{npc:5891}, on {area:639}"] = "{npc:5891}，在{area:639}上",
		["{npc:5943} takes it once your {skill:129} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "你的{skill:129}技能達到20後，{npc:5943}就會接收它：在那之前先採集或製作，指南會同時繼續進行。",
		["{npc:6786} stands on the road at the valley's eastern exit."] = "{npc:6786}站在山谷東側出口的道路上。",
		["{npc:9796} stands just outside the Den's entrance."] = "{npc:9796}就站在大獸穴入口外。",
		["{npc:9796}, by the cooking fire"] = "{npc:9796}，在烹飪火堆旁",
		["{quest:828} camps on the hill west of the naga beach, south of {quest:827}."] = "{quest:828}在納迦海灘西邊的山丘上紮營，位於{quest:827}南邊。",
		["{zone:1454}'s main gate is just west of {area:817}. {npc:5875} stands in the {object:172960}, the canyon under the {object:172982}."] = "{zone:1454}的正門就在{area:817}西邊。{npc:5875}站在{object:172960}，就是{object:172982}下方的峽谷。",
} end)()
t.guides["forever/horde/undead/01-tirisfal-glades"] = (function() return {
		["/sit by her campfire until you get {spell:1229451}"] = "在她的營火旁/sit，直到獲得{spell:1229451}",
		["Ask {npc:10666} for his report"] = "向{npc:10666}索取報告",
		["Ask {npc:1496} for his report"] = "向{npc:1496}索取報告",
		["Ask {npc:251001} for his report"] = "向{npc:251001}索取報告",
		["Back to the church"] = "回到教堂",
		["Back to {area:154}"] = "返回{area:154}",
		["Back up the road and through {area:159} to its west end."] = "沿路回去，穿過{area:159}走到它的西端。",
		["Beat {npc:6784} in the duel"] = "在決鬥中擊敗{npc:6784}",
		["Below ground"] = "地下",
		["Crusader's Outpost"] = "十字軍前哨",
		["Dry Branches"] = "乾樹枝",
		["Eleanor camps just south-west of town. With a profession learned, she also offers its Camping 101, which its trainer takes: in {area:159}, at Linnea's camp, or in the {zone:1458} in the next guide."] = "她在城鎮西南方紮營。學會專業技能後，艾莉諾也會提供對應的「露營入門」任務，交給該專業的訓練師：在{area:159}、林奈的營地，或下一份指南中的{zone:1458}。",
		["Eleanor: for {npc:2114}"] = "艾莉諾：給{npc:2114}",
		["Eleanor: for {npc:2132}"] = "艾莉諾：給{npc:2132}",
		["Eleanor: for {npc:3523}"] = "艾莉諾：給{npc:3523}",
		["Eleanor: for {npc:3549}"] = "艾莉諾：給{npc:3549}",
		["Eleanor: for {npc:4586}"] = "艾莉諾：給{npc:4586}",
		["Eleanor: for {npc:4598}"] = "艾莉諾：給{npc:4598}",
		["Eleanor: for {npc:4605}"] = "艾莉諾：給{npc:4605}",
		["Eleanor: for {npc:5695}"] = "艾莉諾：給{npc:5695}",
		["Eleanor: for {npc:5759}"] = "艾莉諾：給{npc:5759}",
		["Eleanor: for {npc:6289}"] = "艾莉諾：給{npc:6289}",
		["Escort {npc:275954} out of the outpost"] = "護送{npc:275954}離開前哨",
		["Follow the path north into {area:154}; Sarvis stands in front of the church."] = "沿著小路向北進入{area:154}；薩維斯站在教堂前。",
		["Follow the road north-west to {area:157}. {npc:1657} walks the graveyard south of the mills; Nissa, Gregor and {npc:1656} haunt the mills themselves. Rattlecage and Cracked Skull Soldiers drop the ribs, Darkeye Bonecasters the skulls, and any of them may drop {item:2839}.\nCareful: Rotting undead and Darkeye Bonecasters near the Agamands can join a fight as adds."] = "沿著道路向西北前往{area:157}。{npc:1657}在磨坊南邊的墓地走動；妮薩、格里高和{npc:1656}則在磨坊內徘徊。斷骨骷髏和碎顱士兵會掉落肋骨，暗眼骷髏法師掉落頭骨，牠們都可能掉落{item:2839}。\n小心：阿加曼德家附近的腐爛不死生物和暗眼骷髏法師可能會加入戰鬥。",
		["Follow the road south-east from {area:159} past the zeppelin towers."] = "沿著道路從{area:159}向東南走，經過飛艇塔。",
		["Follow the road south-east from {area:159} past the zeppelin towers. Linnea, Kristof and {npc:3549} camp by the road."] = "沿著道路從{area:159}向東南經過飛艇塔。林奈、克里斯多夫和{npc:3549}在路旁紮營。",
		["Follow the road south-west from {area:159} to the Scarlet Crusade camp. {npc:1662} stands at its south end; every Scarlet there can drop a ring."] = "沿著道路從{area:159}向西南前往血色十字軍營地。{npc:1662}站在營地南端；那裡的每個血色十字軍都可能掉落戒指。",
		["Heal and fortify {npc:12428}"] = "治療{npc:12428}並為他施放韌性",
		["Leave {area:154} by the road north-east. {npc:6784} stands by the farmhouse at the {area:156}; {npc:1519} stands by the road just past it."] = "沿著東北方的道路離開{area:154}。{npc:6784}站在{area:156}的農舍旁；{npc:1519}站在過了農舍不遠的路旁。",
		["Listen to Leonid and {npc:246378}, then talk to him again"] = "聽萊尼德和{npc:246378}交談，然後再和他說話",
		["Mindless Zombies"] = "無腦的殭屍",
		["Offer aid to the {npc:246143}"] = "向{npc:246143}伸出援手",
		["Only if the letter dropped"] = "僅限信件有掉落時",
		["Rattlecage Skeletons wander the ruined houses in the north half of {area:154}. Young Scavengers and Duskbats roam all around the village; the Ragged Scavengers and Mangy Duskbats are on its east side. {npc:1661} wants their paws and wings: kill them as you meet them while you clear the skeletons."] = "斷骨骷髏在{area:154}北半部的廢墟房屋間遊蕩。小食腐狼和夜行蝙蝠在村莊各處遊蕩；蓬毛食腐狼和癩皮夜行蝙蝠在村莊東側。{npc:1661}要牠們的爪子和翅膀：清理骷髏時遇到就殺。",
		["The Dry Branches lie on the ground around the south-west edge of {area:159}."] = "乾樹枝散落在{area:159}西南邊緣周圍的地上。",
		["The Scarlet Converts and Initiates hold the farm east of {area:154}. {npc:1919} wanders between the farmhouses: his remains are for {quest:6395}."] = "血色信徒和血色新兵佔據{area:154}東邊的農場。{npc:1919}在農舍之間遊蕩：他的遺骸用於{quest:6395}。",
		["The Scarlet camp"] = "血色十字軍營地",
		["The Scarlet farm"] = "血色十字軍農場",
		["The zombies shamble around the graveyard and the houses just east of the church."] = "殭屍在墓地和教堂東邊的房屋周圍蹣跚而行。",
		["The {area:154} trainers stand around the church"] = "{area:154}的訓練師們在教堂周圍",
		["The {npc:1931}, in the inn's cellar"] = "{npc:1931}，在旅店地下室",
		["The {npc:246143}"] = "{npc:246143}",
		["The {object:164662} lie beside the ruined houses in the north of {area:154}."] = "{object:164662}在{area:154}北部的廢墟房屋旁。",
		["Tirisfal Pumpkins"] = "提里斯法南瓜",
		["Use the {item:286176} on five idle Deathguards around town"] = "對城鎮周圍五名閒置的亡靈衛兵使用{item:286176}",
		["Vile Fin Attackers"] = "邪鰭攻擊者",
		["Vile Fin Seers"] = "邪鰭先知",
		["Walk south from {area:159} to the {area:153} and down into the {area:1497}. {npc:4568} stands in the {object:36082}. The Scarlet camp is just west of the ruins."] = "從{area:159}向南走到{area:153}，再往下進入{area:1497}。{npc:4568}站在{object:36082}。血色十字軍營地就在廢墟西邊。",
		["Walk south from {area:159} to the {area:153} and down into the {area:1497}. {npc:5675} stands in the {object:36082}. The Scarlet camp is just west of the ruins."] = "從{area:159}向南走到{area:153}，再往下進入{area:1497}。{npc:5675}站在{object:36082}。血色十字軍營地就在廢墟西邊。",
		["You rise in the crypt at the south end of {area:154}. {npc:1568} waits just outside."] = "你在{area:154}南端的墓穴中甦醒。{npc:1568}就在外面等著。",
		["{item:16333}, from {npc:1919}"] = "{item:16333}，來自{npc:1919}",
		["{item:2320} from {npc:2118}, for Gretchen"] = "向{npc:2118}購買{item:2320}，給格莉絲",
		["{item:2839}, a rare drop"] = "{item:2839}，稀有掉落",
		["{item:7227}, in the farmstead's garden"] = "{item:7227}，在農場的花園裡",
		["{npc:12428} kneels by the north gate of {area:159}'s graveyard, on your way north. Cast {spell:613} (Rank 2) on him, then {spell:1243}: Fortitude first does not count."] = "{npc:12428}跪在{area:159}墓地的北門旁，就在你往北的路上。先對他施放{spell:613}（等級2），再施放{spell:1243}：先施放真言術：韌不算數。",
		["{npc:1495}'s camp"] = "{npc:1495}的營地",
		["{npc:1499}, in the town hall"] = "{npc:1499}，在市政廳裡",
		["{npc:1500}, in the inn"] = "{npc:1500}，在旅店裡",
		["{npc:1560}, in the inn"] = "{npc:1560}，在旅店裡",
		["{npc:1569}: the scroll for {npc:244808}"] = "{npc:1569}：給{npc:244808}的卷軸",
		["{npc:1570}, in the church"] = "{npc:1570}，在教堂裡",
		["{npc:1661}, beside the church; inside"] = "{npc:1661}，在教堂旁；在裡面",
		["{npc:2114} takes it once your {skill:182} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "你的{skill:182}技能達到20後，{npc:2114}就會接收它：在那之前先採集或製作，指南會同時繼續進行。",
		["{npc:2114}, beside Johaan: {quest:97957}"] = "{npc:2114}，在喬漢旁邊：{quest:97957}",
		["{npc:2119}, the warrior trainer; inside"] = "{npc:2119}，戰士訓練師；在裡面",
		["{npc:2122}, the rogue trainer"] = "{npc:2122}，盜賊訓練師",
		["{npc:2123}, the priest trainer in the church"] = "{npc:2123}，教堂裡的牧師訓練師",
		["{npc:2123}, the priest trainer in the church, sends you to {npc:2129} in {area:159}. Train {spell:613} (Rank 2) from him now: the wounded guard Beryl sends you to needs it."] = "{npc:2123}，教堂裡的牧師訓練師，會派你去找{area:159}的{npc:2129}。現在就向他學習{spell:613}（等級2）：貝瑞爾派你去找的那名受傷衛兵需要它。",
		["{npc:2123}: for {npc:2129} in {area:159}"] = "{npc:2123}：給{area:159}的{npc:2129}",
		["{npc:2124}, the mage trainer, in the church"] = "{npc:2124}，法師訓練師，在教堂裡",
		["{npc:2126}, the warlock trainer"] = "{npc:2126}，術士訓練師",
		["{npc:2128}: {npc:4568} in the {zone:1458} takes it"] = "{npc:2128}：由{zone:1458}的{npc:4568}接收",
		["{npc:2129}, upstairs"] = "{npc:2129}，在樓上",
		["{npc:2129}, upstairs: the {item:16607}"] = "{npc:2129}，在樓上：{item:16607}",
		["{npc:2132} takes it once your {skill:171} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "你的{skill:171}技能達到20後，{npc:2132}就會接收它：在那之前先採集或製作，指南會同時繼續進行。",
		["{npc:2132}, beside Johaan: {quest:97951}"] = "{npc:2132}，在喬漢旁邊：{quest:97951}",
		["{npc:2132}, beside Johaan; inside"] = "{npc:2132}，在喬漢旁邊；在裡面",
