} end)()
t.guides["forever/legacy/legacy-challenges"] = (function() return {
		["Adventure: explore the world map"] = "冒險：探索世界地圖",
		["Adventure: {npc:16042}"] = "冒險：{npc:16042}",
		["All 13 Hyjal Summit bosses are a point. Hyjal Summit is a new 20-player Forever raid at the top of {zone:2482}, near Nordrassil, open from 9 December; its bosses are not in our data, so tick it off once all 13 are down."] = "擊敗Hyjal Summit的全部13個首領值1點。Hyjal Summit是Forever新增的20人團隊副本，位於{zone:2482}頂端、諾達希爾附近，12月9日開放；它的首領不在我們的資料中，所以全部13個首領都倒下後請自行勾選。",
		["All 8 Barrow Deeps bosses are a point. Barrow Deeps is a new 10-player Forever raid beneath {zone:2482}, entered from {zone:2482}, {zone:1452} or {area:1216} and open from 9 December; its bosses are not in our data, so tick it off once all 8 are down."] = "擊敗Barrow Deeps的全部8個首領值1點。Barrow Deeps是Forever新增的10人團隊副本，位於{zone:2482}地底，可從{zone:2482}、{zone:1452}或{area:1216}進入，12月9日開放；它的首領不在我們的資料中，所以全部8個首領都倒下後請自行勾選。",
		["Classes give 27 points: every class reaching 25, 45 and 60. They count once per class across your account, so a second character of a class you already raised adds nothing; a new class does. The first character to reach 25 usually unlocks the Legacy System itself."] = "職業可提供27點：每個職業達到25、45和60級。每個職業在整個帳號只計算一次，所以已經練過的職業再練第二個角色不會增加點數；新的職業才會。第一個達到25級的角色通常就會解鎖傳承系統本身。",
		["Classes: level 25"] = "職業：等級25",
		["Classes: level 45"] = "職業：等級45",
		["Classes: level 60"] = "職業：等級60",
		["Dire Maul East"] = "厄運之槌東區",
		["Dire Maul North"] = "厄運之槌北區",
		["Dire Maul West"] = "厄運之槌西區",
		["Dungeons: level 15-25"] = "地城：等級15-25",
		["Dungeons: level 26-45"] = "地城：等級26-45",
		["Dungeons: level 46-60"] = "地城：等級46-60",
		["Each crafting profession gives 3 points, at 150, 225 and 300. Ranks count once per profession across your account. Follow the Polestar guide \"{skill:171} 1-300\" (Professions). A crafting profession at 150 also unlocks the Legacy System."] = "每個製造專業可提供3點，分別在150、225和300。每個專業的等級在整個帳號只計算一次。請參照Polestar指南「{skill:171} 1-300」（專業）。製造專業達到150也會解鎖傳承系統。",
		["Exploring the entire world map on one character is a point, and it can also unlock the Legacy System. It must all be on the same character. Forever's new zones are part of the map: the {zone:2548}, {zone:2652} and {zone:2482}, a level 60 zone."] = "用一個角色探索整個世界地圖值1點，也可能解鎖傳承系統。全部必須在同一個角色上完成。Forever的新地區也是地圖的一部分：{zone:2548}、{zone:2652}，以及60級地區{zone:2482}。",
		["Follow the Polestar Exploration guides: Exploration: Eastern Kingdoms 1-30, 30-45 and 45-60, and Exploration: Kalimdor 1-30, 30-45 and 45-60. They track every area as you discover it. Exploration: Zephras Isle covers the Skyborne island; whether its map counts towards this challenge is not confirmed yet."] = "請參照Polestar探索指南：「探索：東部王國 1-30」、「30-45」和「45-60」，以及「探索：卡林多 1-30」、「30-45」和「45-60」。它們會在你發現每個區域時進行追蹤。「探索：微風島」涵蓋天裔精靈的島嶼；它的地圖是否計入這項挑戰尚未確認。",
		["Follow the Polestar guide \"{skill:164} 1-300\" (Professions)."] = "請參照Polestar指南「{skill:164} 1-300」（專業）。",
		["Follow the Polestar guide \"{skill:165} 1-300\" (Professions)."] = "請參照Polestar指南「{skill:165} 1-300」（專業）。",
		["Follow the Polestar guide \"{skill:197} 1-300\" (Professions)."] = "請參照Polestar指南「{skill:197} 1-300」（專業）。",
		["Follow the Polestar guide \"{skill:202} 1-300\" (Professions)."] = "請參照Polestar指南「{skill:202} 1-300」（專業）。",
		["Follow the Polestar guide \"{skill:333} 1-300\" (Professions)."] = "請參照Polestar指南「{skill:333} 1-300」（專業）。",
		["Legacy Challenges"] = "傳承挑戰",
		["Level 45 with this character's class."] = "以此角色的職業達到45級。",
		["Level 60 with this character's class."] = "以此角色的職業達到60級。",
		["Lower {area:1583}"] = "{area:1583}下層",
		["PvP: Field of Honor"] = "PvP：Field of Honor",
		["PvP: battleground reputations (Alliance)"] = "PvP：戰場聲望（聯盟）",
		["PvP: battleground reputations (Horde)"] = "PvP：戰場聲望（部落）",
		["PvP: honor ranks"] = "PvP：榮譽等級",
		["Raids: Barrow Deeps"] = "團隊：Barrow Deeps",
		["Raids: Hyjal Summit"] = "團隊：Hyjal Summit",
		["Raids: {npc:10184}"] = "團隊：{npc:10184}",
		["Ranks 3, 7, 10, 13 and 14 are a point each. Polestar cannot read your highest rank yet, so tick each one off yourself. Forever's honor rules for reaching a rank have not been published in detail; in Classic, ranks come from your weekly honor standing, and 13-14 take many weeks of top standing."] = "等級3、7、10、13和14各值1點。Polestar目前還無法讀取你的最高等級，所以請自行逐一勾選。Forever達到各等級的榮譽規則尚未詳細公布；在經典版中，等級取決於你每週的榮譽排名，13-14級需要好幾週的頂尖排名。",
		["The Field of Honor PvP season has weekly journey quests; finishing the ones for weeks 4, 7 and 10 is a point each. These quests are new in Forever and not in our data, so tick each one off yourself."] = "Field of Honor PvP賽季有每週的歷程任務；完成第4、7和10週的任務各值1點。這些任務是Forever新增的，不在我們的資料中，所以請自行逐一勾選。",
		["The {npc:16042} questline is a point. It is the level 60 dungeon-set chain, from An Earnest Proposition to your class's {quest:8999}: {npc:16013} ({zone:1455}) or {npc:16012} ({zone:1454}) send you through In Search of Anthion and Anthion's Parting Words to {npc:16033} at {area:254}, whose Three Kings of Flame, the Left and Right Pieces of Lord Valthalak's Amulet, Final Preparations and {quest:8995} end with {quest:8996}. {quest:8997} then leads to {quest:8999}."] = "{npc:16042}任務線值1點。這是60級地城套裝任務鏈，從「認真的提議」到你職業的{quest:8999}：{npc:16013}（{zone:1455}）或{npc:16012}（{zone:1454}）會帶你完成「尋找安希恩」和「安希恩的離別感言」，前往{area:254}的{npc:16033}，他的「烈焰三巨頭」、「瓦薩拉克護符的左半塊」和「瓦薩拉克護符的右半塊」、「最後的準備」和{quest:8995}，最後以{quest:8996}結束。{quest:8997}接著會引導至{quest:8999}。",
		["This step cannot check the whole map by itself yet; it becomes a tracked goal once the Legacy achievement ids are recorded."] = "此步驟目前還無法自行檢查整張地圖；記錄傳承成就ID後，它就會成為可追蹤的目標。",
		["Tradeskills: {skill:164}"] = "專業技能：{skill:164}",
		["Tradeskills: {skill:165}"] = "專業技能：{skill:165}",
		["Tradeskills: {skill:171}"] = "專業技能：{skill:171}",
		["Tradeskills: {skill:197}"] = "專業技能：{skill:197}",
		["Tradeskills: {skill:202}"] = "專業技能：{skill:202}",
		["Tradeskills: {skill:333}"] = "專業技能：{skill:333}",
		["Upper {area:1583}"] = "{area:1583}上層",
		["all 13 Hyjal Summit bosses"] = "海加爾山的全部13個首領",
		["all 8 Barrow Deeps bosses"] = "古墓深淵的全部8個首領",
		["enemy players and finish the Field of Honor week 10 journey quest"] = "敵對玩家，並完成榮譽戰場第10週的旅程任務",
		["enemy players and finish the Field of Honor week 4 journey quest"] = "敵對玩家，並完成榮譽戰場第4週的旅程任務",
		["enemy players and finish the Field of Honor week 7 journey quest"] = "敵對玩家，並完成榮譽戰場第7週的旅程任務",
		["enemy players for honor until PvP Rank 10"] = "敵對玩家以獲取榮譽，直到PvP軍階10級",
		["enemy players for honor until PvP Rank 13"] = "敵對玩家以獲取榮譽，直到PvP軍階13級",
		["enemy players for honor until PvP Rank 14"] = "敵對玩家以獲取榮譽，直到PvP軍階14級",
		["enemy players for honor until PvP Rank 3"] = "敵對玩家以獲取榮譽，直到PvP軍階3級",
		["enemy players for honor until PvP Rank 7"] = "敵對玩家以獲取榮譽，直到PvP軍階7級",
		["{area:2279}, Live side"] = "{area:2279}，活人區",
		["{area:2279}, Undead side"] = "{area:2279}，亡靈區",
		["{area:718} (appears after the {npc:3678}'s event)"] = "{area:718}（在{npc:3678}的事件之後出現）",
		["{area:796}: Armory"] = "{area:796}：軍械庫",
		["{area:796}: Cathedral"] = "{area:796}：大教堂",
		["{area:796}: Graveyard"] = "{area:796}：墓地",
		["{area:796}: Library"] = "{area:796}：圖書館",
		["{npc:16012} then offers your class's {quest:9007}, the last quest of the challenge: it takes your class's dungeon-set helm and chest and upgrades them."] = "{npc:16012}接著會提供你職業的{quest:9007}，這是這項挑戰的最後一個任務：它會收下你職業的地城套裝頭盔和胸甲並加以升級。",
		["{npc:16013} then offers your class's {quest:8999}, the last quest of the challenge: it takes your class's dungeon-set helm and chest and upgrades them."] = "{npc:16013}接著會提供你職業的{quest:8999}，這是這項挑戰的最後一個任務：它會收下你職業的地城套裝頭盔和胸甲並加以升級。",
		["{npc:16033} offers it once {quest:8996} is turned in"] = "{quest:8996}繳交後，{npc:16033}會提供此任務",
		["{npc:16073}, inside Upper Blackrock Spire after Mea Culpa (no spawn in the data: the arrow leads to {npc:16033}'s {area:254})"] = "{npc:16073}，在黑石塔上層完成「認錯，瓦薩拉克」之後（資料中沒有重生點：箭頭指向{npc:16033}所在的{area:254}）",
} end)()
t.guides["forever/miscellaneous/cozy-sleeping-bag"] = (function() return {
		["Along the coast to {zone:1436}"] = "沿海岸前往{zone:1436}",
		["At the gate in {area:1057} between Arathi and {area:287}, turn north and follow the wall on the {area:287} side to a fallen cart leaning against it. Jump up the cart and its ladder onto the wall, then over the rocks to the hidden camp. Some characters cannot fit under the cargo netting at the camp; another race or a smaller form gets through."] = "到了阿拉希和{area:287}之間{area:1057}的大門，轉向北，沿著{area:287}那一側的城牆走到一輛靠在牆邊的翻倒推車。跳上推車和它的梯子登上城牆，再越過岩石到達隱藏的營地。有些角色無法鑽過營地的貨網底下；換個種族或較小的形態就能通過。",
		["Careful: off the dam's ledge you land in the river below it, in the {zone:1437}. Climb out on its west bank well before the waterfall at about 65,77: the fall kills. Then head north-west to the road and follow it north over {area:880} into Arathi, or hearth if your Hearthstone is set at {area:272}."] = "小心：從水壩的岩架掉下去，會落入下方的河中，也就是{zone:1437}。在約65,77的瀑布之前，及早從西岸爬出來：從瀑布掉下去會摔死。然後向西北走到道路上，沿路向北越過{area:880}進入阿拉希；如果你的爐石設定在{area:272}，就用爐石。",
		["From {object:3202} follow Stranglethorn's west coast north to {zone:1436}, swimming where the beach runs out. It is shorter than the jungle road north and keeps you clear of Stranglethorn's level 30+ beasts and of {zone:1431}."] = "從{object:3202}沿荊棘谷西海岸向北前往{zone:1436}，沙灘沒了就游泳。這比向北走叢林道路更近，也能避開荊棘谷30級以上的野獸和{zone:1431}。",
		["Out of the river"] = "離開河流",
		["Passing {area:272} on the way to {zone:1432}? Set your Hearthstone here: after the dam, it brings you back next to {area:1057} instead of the long walk through the {zone:1437} and Arathi. Skip this step to keep your Hearthstone where it is."] = "前往{zone:1432}途中經過{area:272}？在這裡設定爐石：過了水壩後，它能把你帶回{area:1057}旁邊，省去穿過{zone:1437}和阿拉希的長途跋涉。若要讓爐石保持原處，就跳過這個步驟。",
		["Stonetalon from the north"] = "從北邊進入石爪山脈",
		["Stranglethorn's west coast"] = "荊棘谷西海岸",
		["West bank"] = "西岸",
		["West bank, before the waterfall"] = "西岸，瀑布之前",
		["{area:272} on the way"] = "途經{area:272}",
		["{zone:1413}' way into Stonetalon runs through {area:1702}, and the road on to the hills passes {area:2539} and {area:460}: all Horde posts. Come in from the north instead. With the {area:467} flight path, fly there and follow the road south. Otherwise fly to {area:415} and walk south-west to the {area:1276}, the tunnel from {zone:1440} into Stonetalon."] = "從{zone:1413}進入石爪山脈的路要經過{area:1702}，往山丘去的道路又經過{area:2539}和{area:460}：全都是部落的據點。改從北邊進來。如果有{area:467}的飛行路線，就飛過去再沿道路向南。否則飛往{area:415}，向西南走到{area:1276}，也就是從{zone:1440}通往石爪山脈的隧道。",
} end)()
t.guides["forever/professions/alchemy"] = (function() return {
		["Artisan {skill:171}"] = "專家級{skill:171}",
		["Back to an {skill:171} trainer: {spell:3171} (from 90)."] = "回到{skill:171}訓練師：{spell:3171}（90起）。",
		["Expert raises the cap from 150 to 225 for 50s (Classic's price; Forever's is not in the data); it needs {skill:171} 125 and character level 20, so you can take it on any visit from 125. Only a few trainers teach it: Alliance {npc:4160} ({zone:1457}); Horde {npc:4611} ({zone:1458}). The arrow picks the nearest of your faction. 150-225 takes about 33s 20c of vendor goods, plus 40 {object:1623}, 39 {item:3356}, 39 {object:2045} and 40 {object:2046} to gather or buy. Come with all of it in your bags (the steps above, the rest from the Auction House): these trainers also teach {spell:3452} (from 160) and {item:8951} (from 195), and the crafts need no station, so craft right here and learn each recipe as you reach its skill. One trip instead of 3."] = "高級將技能上限從150提高到225，費用50銀（經典版的價格；資料中沒有Forever的價格）；需要{skill:171} 125和角色等級20，所以技能達到125後，任何一次經過都可以學。只有少數訓練師會教：聯盟為{npc:4160}（{zone:1457}）；部落為{npc:4611}（{zone:1458}）。箭頭會選擇你陣營最近的一位。150-225約需33銀20銅的商人材料，另需採集或購買40個{object:1623}、39個{item:3356}、39個{object:2045}和40個{object:2046}。把這些全部帶在背包裡再來（按上面的步驟收集，其餘從拍賣場購買）：這些訓練師也教{spell:3452}（技能160起）和{item:8951}（技能195起），而且製作不需要工作台，可以就在這裡製作，技能一到就學新配方。只要跑一趟，不用跑3趟。",
		["Expert {skill:171}"] = "高級{skill:171}",
		["Journeyman raises the cap from 75 to 150 for 4s 50c (Classic's price; Forever's is not in the data); it needs {skill:171} 50 and character level 10, so you can take it on any visit from 50. Not every {skill:171} trainer teaches it: Alliance {npc:4900} ({zone:1445}), {npc:2837} ({zone:1434}), {npc:3964} ({zone:1440}), {npc:5499} ({zone:1453}), {npc:11042} ({zone:1457}) and {npc:5177} ({zone:1455}); Horde {npc:3009} ({zone:1456}), {npc:4609} ({zone:1458}), {npc:2837} ({zone:1434}), {npc:2391} ({zone:1424}) and {npc:3347} ({zone:1454}). The arrow picks the nearest of your faction. Learn now: {spell:2331} (from 25, 1s). Also learn {spell:1230564} (1s): Forever's {skill:171} camp item, 1 {item:2447} and 1 {item:3371}, placed at a campsite beside a campfire for its buff. The Camping 101: {skill:171} quest from your starting area's camping guide (after The Great Outdoors) sends you to an alchemy trainer who teaches it free. 75-150 takes about 1s of recipes and 9s 8c of vendor goods, plus 77 {item:785}, 152 {item:2450} and 54 {item:2453} to gather or buy."] = "中級訓練將技能上限從75提高到150，費用4銀50銅（經典版的價格；資料中沒有Forever的價格）；需要{skill:171} 50和角色等級10，所以技能達到50後，任何一次經過都可以學。並非每位{skill:171}訓練師都會教：聯盟有{npc:4900}（{zone:1445}）、{npc:2837}（{zone:1434}）、{npc:3964}（{zone:1440}）、{npc:5499}（{zone:1453}）、{npc:11042}（{zone:1457}）和{npc:5177}（{zone:1455}）；部落有{npc:3009}（{zone:1456}）、{npc:4609}（{zone:1458}）、{npc:2837}（{zone:1434}）、{npc:2391}（{zone:1424}）和{npc:3347}（{zone:1454}）。箭頭會選擇你陣營最近的一位。現在學習：{spell:2331}（技能25起，1銀）。也學習{spell:1230564}（1銀）：這是Forever的{skill:171}紮營物品，需要1個{item:2447}和1個{item:3371}，放在營地的營火旁可獲得增益效果。起始地區的紮營嚮導（完成「戶外真好」後）提供的「紮營入門指南：{skill:171}」任務，會讓你去找免費教授它的煉金術訓練師。75-150約需1銀的配方和9銀8銅的商人材料，另需採集或購買77個{item:785}、152個{item:2450}和54個{item:2453}。",
